window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["1MA"]={"book":"1MA","editions":{"fin-biblia1776":[[1,1,"Antiokus Epiphaneksen jumalattomuudesta ja julmuudesta Jerusalemia vastaan. Aleksander, Philippuksen poika, Makedonian kuningas, joka ennen Grekan maalla hallinnut oli, läksi Kittimin maakunnasta, nosti suuret sodat, otti vahvat kaupungit,","Antiokus Epiphaneksen jumalattomuudesta ja julmuudesta Jerusalemia vastaan. Aleksander, Philippuksen poika, Makedonian kuningas, joka ennen Grekan maalla hallinnut oli, läksi Kittimin maakunnasta, nosti suuret sodat, otti vahvat kaupungit,"],[1,2,"Ja löi Dariuksen, Persian ja Median kuninkaan, ja hallitsi hänen siassansa, ja voitti sen jälkeen muut kuninkaat kaikissa maakunnissa allensa,","Ja löi Dariuksen, Persian ja Median kuninkaan, ja hallitsi hänen siassansa, ja voitti sen jälkeen muut kuninkaat kaikissa maakunnissa allensa,"],[1,3,"Ja vaelsi aina edemmäksi, ja otti kaikki maat ja valtakunnat, ja ei kenkään rohjennut asettna häntä vastaan.","Ja vaelsi aina edemmäksi, ja otti kaikki maat ja valtakunnat, ja ei kenkään rohjennut asettna häntä vastaan."],[1,4,"Ja hänen sydämensä paisui ja tuli ylpiäksi; oli myös hänellä sangen väkevä sotajoukko.","Ja hänen sydämensä paisui ja tuli ylpiäksi; oli myös hänellä sangen väkevä sotajoukko."],[1,5,"Kuin hän ne valtakunnat oli saanut allensa, tuli hän sairaaksi.","Kuin hän ne valtakunnat oli saanut allensa, tuli hän sairaaksi."],[1,6,"Vaan kuin hän havaitsi, että hänen piti kuoleman,","Vaan kuin hän havaitsi, että hänen piti kuoleman,"],[1,7,"kutsui hän päämiehensä tykönsä, jotka nuoruudesta olivat hänen kanssansa kasvaneet. ja sääsi eläissänsä heidät maakuntain ruhtinaiksi.","kutsui hän päämiehensä tykönsä, jotka nuoruudesta olivat hänen kanssansa kasvaneet. ja sääsi eläissänsä heidät maakuntain ruhtinaiksi."],[1,8,"Ja Aleksander kuoli, kuin hän kaksitoistakymmentä vuotta oli vallinnut.","Ja Aleksander kuoli, kuin hän kaksitoistakymmentä vuotta oli vallinnut."],[1,9,"Jälkeen hänen kuolemansa tuli valtakunta hänen ruhtinaillensa, he ottivat maakunnat kukin paikkansa, ja tekivät itsensä kuninkaiksi.","Jälkeen hänen kuolemansa tuli valtakunta hänen ruhtinaillensa, he ottivat maakunnat kukin paikkansa, ja tekivät itsensä kuninkaiksi."],[1,10,"Ja he ja heidän jälkeentulevaisensa hallitsivat kauvan aikaa, ja suuri sota oli heidän välillänsä, ja paljo tuskaa joka paikassa maailmassa.","Ja he ja heidän jälkeentulevaisensa hallitsivat kauvan aikaa, ja suuri sota oli heidän välillänsä, ja paljo tuskaa joka paikassa maailmassa."],[1,11,"Ja yhdestä näistä ruhtinaista syntyi vahingollinen pahuuden juuri, nimeltä Antiokus Epiphanes, joka Roomissa oli ollut takauksena isänsä, suuren Antiokuksen edestä. Ja tämä Antiokus Epiphanes rupesi hallitsemaan sadannella ja seitsemännelläneljättäkymmentä Grekan valtakunnan vuodella.","Ja yhdestä näistä ruhtinaista syntyi vahingollinen pahuuden juuri, nimeltä Antiokus Epiphanes, joka Roomissa oli ollut takauksena isänsä, suuren Antiokuksen edestä. Ja tämä Antiokus Epiphanes rupesi hallitsemaan sadannella ja seitsemännelläneljättäkymmentä Grekan valtakunnan vuodella."],[1,12,"Niihin aikoin olivat Israelissa väärät miehet, jotka yllyttivät kansaa ja sanoivat: tehkäämme liitto ympärillä asuvaisten pakanain kanssa, ja ruvetkaamme heidän jumalanpalvelukseensa; sillä meidän on täytynyt kärsiä paljon pahuutta siitä ajasta, kuin me olemme heistä luopuneet.","Niihin aikoin olivat Israelissa väärät miehet, jotka yllyttivät kansaa ja sanoivat: tehkäämme liitto ympärillä asuvaisten pakanain kanssa, ja ruvetkaamme heidän jumalanpalvelukseensa; sillä meidän on täytynyt kärsiä paljon pahuutta siitä ajasta, kuin me olemme heistä luopuneet."],[1,13,"Tämä neuvo kelpasi heille hyvin.","Tämä neuvo kelpasi heille hyvin."],[1,14,"Ja he lähettivät muutamia kansasta kuninkaan tykö, joka käski heidän ottaa pakanain säädyt.","Ja he lähettivät muutamia kansasta kuninkaan tykö, joka käski heidän ottaa pakanain säädyt."],[1,15,"Silloin he asettivat Jerusalemissa pakanallisen harjoitushuoneen,","Silloin he asettivat Jerusalemissa pakanallisen harjoitushuoneen,"],[1,16,"Eikä ympärileikkausta pitäneet, vaan lankesivat pois pyhästä liitosta, ja pitivät itsensä niinkuin pakanat ja olivat peräti paatuneet tekemään kaikkinaista syntiä ja häpiää.","Eikä ympärileikkausta pitäneet, vaan lankesivat pois pyhästä liitosta, ja pitivät itsensä niinkuin pakanat ja olivat peräti paatuneet tekemään kaikkinaista syntiä ja häpiää."],[1,17,"Kuin Antiokus oli vahvistanut valtakuntansa, aikoi hän myös saada Egyptin valtakunnan, ja niin pitää molemmat valtakunnat.","Kuin Antiokus oli vahvistanut valtakuntansa, aikoi hän myös saada Egyptin valtakunnan, ja niin pitää molemmat valtakunnat."],[1,18,"Ja hän meni Egyptiin sangen vahvana, vaunuin, elephanttein, hevosmiesten ja laivain paljoudella.","Ja hän meni Egyptiin sangen vahvana, vaunuin, elephanttein, hevosmiesten ja laivain paljoudella."],[1,19,"Vaan Ptolomeus pelkäsi ja pakeni, ja monta Egyptin miestä kaatui haavoitettuna.","Vaan Ptolomeus pelkäsi ja pakeni, ja monta Egyptin miestä kaatui haavoitettuna."],[1,20,"Ja Antiokus sai vahvimmat kaupungit Egyptissä, ja kiskoi suuren saaliin ja vei pois.","Ja Antiokus sai vahvimmat kaupungit Egyptissä, ja kiskoi suuren saaliin ja vei pois."],[1,21,"Mutta kuin Antiokus Egyptissä tämän voiton saanut oli, ja palasi kotia sadannella ja kolmannella vuodella viidettäkymmentä,","Mutta kuin Antiokus Egyptissä tämän voiton saanut oli, ja palasi kotia sadannella ja kolmannella vuodella viidettäkymmentä,"],[1,22,"Meni hän ylös Israeliin ja Jerusalemiin suurella joukolla,","Meni hän ylös Israeliin ja Jerusalemiin suurella joukolla,"],[1,23,"Ja meni röyhkeästi pyhään., ja antoi ottaa pois kultaisen alttarin, kynttiläjalan ja kaikki ne kappaleet, jotka sen päällä olivat, ja leipäuhripöydän, ja pikarit, ja maljat, kultaiset lusikat, esiripun ja kruunut, ja kultaiset templin kaunistukset, ja löi kaikki rikki,","Ja meni röyhkeästi pyhään., ja antoi ottaa pois kultaisen alttarin, kynttiläjalan ja kaikki ne kappaleet, jotka sen päällä olivat, ja leipäuhripöydän, ja pikarit, ja maljat, kultaiset lusikat, esiripun ja kruunut, ja kultaiset templin kaunistukset, ja löi kaikki rikki,"],[1,24,"Ja otti hopian ja kullan, ja kaikki kalliit astiat ja kätketyt tavarat, mitkä hän löysi, ja vei kaikki myötänsä omalle maallensa,","Ja otti hopian ja kullan, ja kaikki kalliit astiat ja kätketyt tavarat, mitkä hän löysi, ja vei kaikki myötänsä omalle maallensa,"],[1,25,"Ja antoi surmata paljon väkeä, ja puhui juuri ylpiästi.","Ja antoi surmata paljon väkeä, ja puhui juuri ylpiästi."],[1,26,"Ja suuri sydämen suru oli koko Israelissa ja kaikissa paikoissa, joissa he asuivat.","Ja suuri sydämen suru oli koko Israelissa ja kaikissa paikoissa, joissa he asuivat."],[1,27,"Ja päämiehet ja vanhimmat murehtivat, neitseet ja nuorukaiset suuresti surkastuivat, miehet ja vaimot valittivat;","Ja päämiehet ja vanhimmat murehtivat, neitseet ja nuorukaiset suuresti surkastuivat, miehet ja vaimot valittivat;"],[1,28,"Ja koko maakunta oli surullinen siitä julmuudesta, joka siellä tapahtui;","Ja koko maakunta oli surullinen siitä julmuudesta, joka siellä tapahtui;"],[1,29,"Ja koko Jakobin huone oli täytetty katkeruudella.","Ja koko Jakobin huone oli täytetty katkeruudella."],[1,30,"Ja kahden vuoden perästä lähetti kuningas veropäämiehen Juudeaan; se tuli Jerusalemiin suurella väellä,","Ja kahden vuoden perästä lähetti kuningas veropäämiehen Juudeaan; se tuli Jerusalemiin suurella väellä,"],[1,31,"Ja anoi ystävällisesti, että hänen piti pääsemän sisälle, ja ei luvannut mitään vahinkoa tehdä, vaan se oli kaikki petos.","Ja anoi ystävällisesti, että hänen piti pääsemän sisälle, ja ei luvannut mitään vahinkoa tehdä, vaan se oli kaikki petos."],[1,32,"Ja he uskoivat hänen, ja sallivat tulla sisälle, ja hän karkasi petoksella kaupungin päälle, ja löi paljon kansaa Israelista,","Ja he uskoivat hänen, ja sallivat tulla sisälle, ja hän karkasi petoksella kaupungin päälle, ja löi paljon kansaa Israelista,"],[1,33,"Ja ryösti kaupungin, ja poltti huoneet, kukisti muurit,","Ja ryösti kaupungin, ja poltti huoneet, kukisti muurit,"],[1,34,"Ja vei pois vaimot, lapset ja karjan.","Ja vei pois vaimot, lapset ja karjan."],[1,35,"Ja Davidin linnan hän vahvisti vahvoilla muureilla ja torneilla;","Ja Davidin linnan hän vahvisti vahvoilla muureilla ja torneilla;"],[1,36,"Ja asetti siihen jumalattoman joukon, joka siinä kaikkea pahuutta teki.","Ja asetti siihen jumalattoman joukon, joka siinä kaikkea pahuutta teki."],[1,37,"Ja he ryöväsivät sota-aseet ja elatuksen Jerusalemin kaupungista, ja panivat sinne,","Ja he ryöväsivät sota-aseet ja elatuksen Jerusalemin kaupungista, ja panivat sinne,"],[1,38,"Ja piirittivät pyhän, ja väijyivät kansaa, jotka templiin menivät, ja hyökkäsivät linnasta pyhään, estääksensä jumalanpalvelusta,","Ja piirittivät pyhän, ja väijyivät kansaa, jotka templiin menivät, ja hyökkäsivät linnasta pyhään, estääksensä jumalanpalvelusta,"],[1,39,"Ja vuodattivat pyhässä siassa paljon viatointa verta, ja saastuttivat sen.","Ja vuodattivat pyhässä siassa paljon viatointa verta, ja saastuttivat sen."],[1,40,"Ja Jerusalemin asuvaiset pakenivat ja muukalaiset jäivät siaan; vaan ne, jotka siinä syntyneet olivat, piti lähtemän pois.","Ja Jerusalemin asuvaiset pakenivat ja muukalaiset jäivät siaan; vaan ne, jotka siinä syntyneet olivat, piti lähtemän pois."],[1,41,"Pyhä sia oli kylmillä, pyhäpäivät tulivat kaikki murhepäiviksi ja sabbatit surkeudeksi, ja kaikki heidän kunniansa raukesi tyhjään.","Pyhä sia oli kylmillä, pyhäpäivät tulivat kaikki murhepäiviksi ja sabbatit surkeudeksi, ja kaikki heidän kunniansa raukesi tyhjään."],[1,42,"Niin kuuluisa kuin Jerusalem oli ennen ollut, niin surkian ja vaivaloisen täytyi sen siihen aikaan olla.","Niin kuuluisa kuin Jerusalem oli ennen ollut, niin surkian ja vaivaloisen täytyi sen siihen aikaan olla."],[1,43,"Ja Antiokus antoi myös ympäri kaiken valtakuntansa käskyn, että kaikki kansa yksimielisesti piti yhdenkaltaisen jumalanpalveluksen pitämän.","Ja Antiokus antoi myös ympäri kaiken valtakuntansa käskyn, että kaikki kansa yksimielisesti piti yhdenkaltaisen jumalanpalveluksen pitämän."],[1,44,"Silloin hylkäsi kaikki kansa lakinsa, ja mielistyivät Antiokuksen käskyyn.","Silloin hylkäsi kaikki kansa lakinsa, ja mielistyivät Antiokuksen käskyyn."],[1,45,"Ja monta Israelista lankesi siihen, ja uhrasi epäjumalille ja turmeli sabbatin.","Ja monta Israelista lankesi siihen, ja uhrasi epäjumalille ja turmeli sabbatin."],[1,46,"Antiokus lähetti myös kirjat Jerusalemiin ja kaikkiin Juudan kaupunkeihin, joissa hän käski, että heidän piti pakanain jumalanpalveluksen ottaman vastaan,","Antiokus lähetti myös kirjat Jerusalemiin ja kaikkiin Juudan kaupunkeihin, joissa hän käski, että heidän piti pakanain jumalanpalveluksen ottaman vastaan,"],[1,47,"Ja polttouhrin ja ruokauhrin ja syntiuhrin pyhässä siassa, sabbatin ja muut juhlapäivät maahan lyömän.","Ja polttouhrin ja ruokauhrin ja syntiuhrin pyhässä siassa, sabbatin ja muut juhlapäivät maahan lyömän."],[1,48,"Ja käski, että pyhä ja pyhä kansa piti saastutettaman.","Ja käski, että pyhä ja pyhä kansa piti saastutettaman."],[1,49,"Ja antoi rakentaa alttarit, kirkot ja epäjumalat,","Ja antoi rakentaa alttarit, kirkot ja epäjumalat,"],[1,50,"Ja uhrata sianlihoja ja muita saastaisia eläimiä.","Ja uhrata sianlihoja ja muita saastaisia eläimiä."],[1,51,"Ja kielsi ympärileikkauksen, ja käski kansan totutettaa kaikkiin kauhistuksiin, että heidän piti Jumalan lain ja oikeuden unhottaman, ja toiset tavat ottaman.","Ja kielsi ympärileikkauksen, ja käski kansan totutettaa kaikkiin kauhistuksiin, että heidän piti Jumalan lain ja oikeuden unhottaman, ja toiset tavat ottaman."],[1,52,"Ja kuka ikänä ei ollut tässä asiassa Antiokukselle kuuliainen, se piti surmattaman.","Ja kuka ikänä ei ollut tässä asiassa Antiokukselle kuuliainen, se piti surmattaman."],[1,53,"Tämän käskyn antoi hän käydä ulos kaikkeen valtakuntaansa, ja asetti päämiehet, jotka kansan piti vaatiman kaikkia senkaltaisia pitämään.","Tämän käskyn antoi hän käydä ulos kaikkeen valtakuntaansa, ja asetti päämiehet, jotka kansan piti vaatiman kaikkia senkaltaisia pitämään."],[1,54,"Nämät toimittivat, että Juudan maalla uhrattiin, ja käskivät, että niin piti pidettämän.","Nämät toimittivat, että Juudan maalla uhrattiin, ja käskivät, että niin piti pidettämän."],[1,55,"Ja monta kansasta luopui Jumalan laista heidän tykönsä.","Ja monta kansasta luopui Jumalan laista heidän tykönsä."],[1,56,"He tekivät kaikkea pahuutta maakunnassa, ja karkoittivat Israelin pois, että heidän täytyi lymyttää ja kätkeä itsensä luoliin, paossansa.","He tekivät kaikkea pahuutta maakunnassa, ja karkoittivat Israelin pois, että heidän täytyi lymyttää ja kätkeä itsensä luoliin, paossansa."],[1,57,"Sadannella ja viidennellä vuodella viidettäkymmentä, viidentenä päivänä toistakymmentä Kasleun kuulla, antoi kuningas Antiokus panna hävityksen kauhistuksen Jumalan alttarille,","Sadannella ja viidennellä vuodella viidettäkymmentä, viidentenä päivänä toistakymmentä Kasleun kuulla, antoi kuningas Antiokus panna hävityksen kauhistuksen Jumalan alttarille,"],[1,58,"Ja antoi panna alttarit ylös joka Juudan kaupungissa, niin että joka miehen kadulla julkisesti ja huoneensa edessä suitsuttaman ja uhraaman piti.","Ja antoi panna alttarit ylös joka Juudan kaupungissa, niin että joka miehen kadulla julkisesti ja huoneensa edessä suitsuttaman ja uhraaman piti."],[1,59,"Ja antoi repiä rikki ja polttaa Herran lakikirjat,","Ja antoi repiä rikki ja polttaa Herran lakikirjat,"],[1,60,"Ja murhata kaikki ne, joiden tykönä Jumalan liiton kirjat löydettiin, ja jotka Herran lain pitivät.","Ja murhata kaikki ne, joiden tykönä Jumalan liiton kirjat löydettiin, ja jotka Herran lain pitivät."],[1,61,"Ja tätä he tekivät sotaväellänsä joka kuu, kuin kansa tuli kokoon kaupungeissa.","Ja tätä he tekivät sotaväellänsä joka kuu, kuin kansa tuli kokoon kaupungeissa."],[1,62,"Ja viidentenä päivänä kolmattakymmentä kuusta uhrasivat he alttarilla, jonka he rakentaneet olivat Herran alttaria vastaan.","Ja viidentenä päivänä kolmattakymmentä kuusta uhrasivat he alttarilla, jonka he rakentaneet olivat Herran alttaria vastaan."],[1,63,"Ja ne vaimot, jotka lapsensa ympärileikkasivat, tapettiin, niinkuin Antiokus oli käskenyt.","Ja ne vaimot, jotka lapsensa ympärileikkasivat, tapettiin, niinkuin Antiokus oli käskenyt."],[1,64,"Vanhimmat tapettiin huoneissansa, ja lapset hirtettiin. Mutta monta Israelin kansasta olivat vahvat, ja ei tahtoneet syödä saastaista, Ja antoivat ennen itsensä tapettaa, kuin he itsensä saastuttivat, Eikä tahtoneet luopua Jumalan pyhästä laista, sentähden he tulivat surmatuksi.","Vanhimmat tapettiin huoneissansa, ja lapset hirtettiin. Mutta monta Israelin kansasta olivat vahvat, ja ei tahtoneet syödä saastaista, Ja antoivat ennen itsensä tapettaa, kuin he itsensä saastuttivat, Eikä tahtoneet luopua Jumalan pyhästä laista, sentähden he tulivat surmatuksi."],[2,1,"Niinä päivinä nousi pappi Matatias, Johanneksen poika, Simeonin pojan, Joarimin suvusta Jerusalemista, joka asui Modin vuorella.","Niinä päivinä nousi pappi Matatias, Johanneksen poika, Simeonin pojan, Joarimin suvusta Jerusalemista, joka asui Modin vuorella."],[2,2,"Ja hänellä oli viisi poikaa: Johannes, liialta nimeltä Gaddis,","Ja hänellä oli viisi poikaa: Johannes, liialta nimeltä Gaddis,"],[2,3,"Simon, liialta nimeltä Tassi,","Simon, liialta nimeltä Tassi,"],[2,4,"Juudas, liialta nimeltä Makkabealainen,","Juudas, liialta nimeltä Makkabealainen,"],[2,5,"Eleatsar, liialta nimeltä Aaron, ja Jonatan, liialta nimeltä Apphus.","Eleatsar, liialta nimeltä Aaron, ja Jonatan, liialta nimeltä Apphus."],[2,6,"Nämät murehtivat sangen kovin sitä suurta surkeutta, joka Juudeassa ja Jerusalemissa oli.","Nämät murehtivat sangen kovin sitä suurta surkeutta, joka Juudeassa ja Jerusalemissa oli."],[2,7,"Ja Matatias valitti ja sanoi: voi että minä sitä varten synnyin, että minun pitää näkemän minun kansani ja pyhän kaupungin hävityksen, ja vielä sittenkin alallani oleman, ja antaman vihollisen tehdä niinkuin hän itse tahtoo!","Ja Matatias valitti ja sanoi: voi että minä sitä varten synnyin, että minun pitää näkemän minun kansani ja pyhän kaupungin hävityksen, ja vielä sittenkin alallani oleman, ja antaman vihollisen tehdä niinkuin hän itse tahtoo!"],[2,8,"Muukalaiset pitävät hallussansa pyhän, ja Jumalan templi on niinkuin kunniatoin ihminen.","Muukalaiset pitävät hallussansa pyhän, ja Jumalan templi on niinkuin kunniatoin ihminen."],[2,9,"Sen kaunistukset ovat viedyt pois, lapset ovat kaduilla lyödyt, ja nuoret miehet muukalaisilta syöstyt lävitse.","Sen kaunistukset ovat viedyt pois, lapset ovat kaduilla lyödyt, ja nuoret miehet muukalaisilta syöstyt lävitse."],[2,10,"Valtakunta on tullut kaikkein pakanain saaliiksi, ja he ryöstävät sen.","Valtakunta on tullut kaikkein pakanain saaliiksi, ja he ryöstävät sen."],[2,11,"Kaikki sen kunnia on tullut pois; joka ennen oli niinkuin suuri kuningatar, se on nyt ylönkatsotuksi orjaksi tullut.","Kaikki sen kunnia on tullut pois; joka ennen oli niinkuin suuri kuningatar, se on nyt ylönkatsotuksi orjaksi tullut."],[2,12,"Katso, meidän pyhämme, kerskauksemme ja kunniamme on poissa; pakanat ovat sen hävittäneet.","Katso, meidän pyhämme, kerskauksemme ja kunniamme on poissa; pakanat ovat sen hävittäneet."],[2,13,"Kellä olis ilo enään elää?","Kellä olis ilo enään elää?"],[2,14,"Ja Matatias repäisi vaatteensa, hän ja hänen poikansa, ja pukivat säkit yllensä ja murehtivat sangen raskaasti.","Ja Matatias repäisi vaatteensa, hän ja hänen poikansa, ja pukivat säkit yllensä ja murehtivat sangen raskaasti."],[2,15,"Kuin Antiokuksen käskyläiset sinne tulivat vaatimaan myös niitä, jotka Modin kaupunkiin paenneet olivat, luopumaan Jumalan laista, ja epäjumalille uhraamaan ja pyhää savua suitsuttamaan:","Kuin Antiokuksen käskyläiset sinne tulivat vaatimaan myös niitä, jotka Modin kaupunkiin paenneet olivat, luopumaan Jumalan laista, ja epäjumalille uhraamaan ja pyhää savua suitsuttamaan:"],[2,16,"Silloin luopui monta Israelin kansasta heidän tykönsä; mutta Matatias ja hänen poikansa pysyivät vahvana.","Silloin luopui monta Israelin kansasta heidän tykönsä; mutta Matatias ja hänen poikansa pysyivät vahvana."],[2,17,"Ja Antiokuksen käskyläiset sanoivat Matatiakselle: sinä olet ylimmäinen ja voimallisin tässä kanpungissa, ja sinulla on monta poikaa ja sukulaista,","Ja Antiokuksen käskyläiset sanoivat Matatiakselle: sinä olet ylimmäinen ja voimallisin tässä kanpungissa, ja sinulla on monta poikaa ja sukulaista,"],[2,18,"Sentähden astu sinä ensin edes, ja tee, mitä kuningas on käskenyt, niinkuin kaikki maakunnat, niin myös Juudan miehet, jotka vielä Jerusalemissa ovat, tehneet ovat, niin kuningas leppyy sinulle ja sinun pojilles, ja lahjoittaa sinulle hopiaa ja kultaa ja suuria lahjoja.","Sentähden astu sinä ensin edes, ja tee, mitä kuningas on käskenyt, niinkuin kaikki maakunnat, niin myös Juudan miehet, jotka vielä Jerusalemissa ovat, tehneet ovat, niin kuningas leppyy sinulle ja sinun pojilles, ja lahjoittaa sinulle hopiaa ja kultaa ja suuria lahjoja."],[2,19,"Ja Matatias vastasi lujasti ja sanoi: jos vielä kaikki maakunnat Antiokukselle kuuliaiset olisivat, ja jokainen isäinsä laista luopuis, ja mielistyis kuninkaan käskyyn;","Ja Matatias vastasi lujasti ja sanoi: jos vielä kaikki maakunnat Antiokukselle kuuliaiset olisivat, ja jokainen isäinsä laista luopuis, ja mielistyis kuninkaan käskyyn;"],[2,20,"En kuitenkaan minä, ja minun poikani ja veljeni tahdo hyljätä isäin lakia: siitä meitä Jumala varjelkoon!","En kuitenkaan minä, ja minun poikani ja veljeni tahdo hyljätä isäin lakia: siitä meitä Jumala varjelkoon!"],[2,21,"Ei se olisi meille hyvää, että me Jumalan sanasta ja laista luopuisimme.","Ei se olisi meille hyvää, että me Jumalan sanasta ja laista luopuisimme."],[2,22,"Emme tahdo mielistyä Antiokuksen käskyyn, ja uhrata, emmekä luopua laistamme, ja toisia säätyjä ottaa.","Emme tahdo mielistyä Antiokuksen käskyyn, ja uhrata, emmekä luopua laistamme, ja toisia säätyjä ottaa."],[2,23,"Kuin hän nämät sanat puhunut oli, tuli yksi Juudalainen kaikkein silmäin nähden ja uhrasi epäjumalalle alttarilla Modin kaupungissa, niinkuin kuningas oli, käskenyt.","Kuin hän nämät sanat puhunut oli, tuli yksi Juudalainen kaikkein silmäin nähden ja uhrasi epäjumalalle alttarilla Modin kaupungissa, niinkuin kuningas oli, käskenyt."],[2,24,"Ja Matatias näki sen, ja se pisti hänen sydäntänsä, ja hänen kiivauksensa syttyi lain tähden;","Ja Matatias näki sen, ja se pisti hänen sydäntänsä, ja hänen kiivauksensa syttyi lain tähden;"],[2,25,"Ja hän juoksi ja tappoi sen Juudalaisen alttarin edessä, ja Antiokuksen käskyläisen, joka uhraamaan vaati, ja kukisti alttarin maahan.","Ja hän juoksi ja tappoi sen Juudalaisen alttarin edessä, ja Antiokuksen käskyläisen, joka uhraamaan vaati, ja kukisti alttarin maahan."],[2,26,"Sen hän teki kiivaudessa lain tähden, niinkuin Pinehas teki Zambrille Salomin pojalle.","Sen hän teki kiivaudessa lain tähden, niinkuin Pinehas teki Zambrille Salomin pojalle."],[2,27,"Ja Matatias korotti äänensä kaiken kaupungin ylitse, sanoen: jolla on kiivaus laista, ja tahtoo pitää liiton, hän käykään minun kanssani kaupungista ulos.","Ja Matatias korotti äänensä kaiken kaupungin ylitse, sanoen: jolla on kiivaus laista, ja tahtoo pitää liiton, hän käykään minun kanssani kaupungista ulos."],[2,28,"Niin pakeni hän ja hänen poikansa vuorille, ja jättivät kaupunkiin kaikki, mitä heillä oli.","Niin pakeni hän ja hänen poikansa vuorille, ja jättivät kaupunkiin kaikki, mitä heillä oli."],[2,29,"Ja monta hurskasta ihmistä läksi ulos erämaihin.","Ja monta hurskasta ihmistä läksi ulos erämaihin."],[2,30,"Ja olivat siellä valmoinensa, lapsinensa ja karjoinensa; sillä julmuus oli sangen suureksi paisunut.","Ja olivat siellä valmoinensa, lapsinensa ja karjoinensa; sillä julmuus oli sangen suureksi paisunut."],[2,31,"Mutta kuin kuninkaan väki Jerusalemissa, Davidin kaupungissa, kuulla saivat, että muutamat olivat asettuneet kuninkaan käskyä vastaan, ja antauneet kaupungista ulos erämaihin, salaisiin paikkoihin, lymyttääksensä ja pelastaaksensa itsensä, ja että paljo kansaa oli heidän seuraansa mennyt;","Mutta kuin kuninkaan väki Jerusalemissa, Davidin kaupungissa, kuulla saivat, että muutamat olivat asettuneet kuninkaan käskyä vastaan, ja antauneet kaupungista ulos erämaihin, salaisiin paikkoihin, lymyttääksensä ja pelastaaksensa itsensä, ja että paljo kansaa oli heidän seuraansa mennyt;"],[2,32,"Kiiruhtivat he karkaamaan heidän päällensä sabbatin päivänä, ja antoivat heille sanoa: vieläkö te nyt 'tahdotte kovakorvaiset olla?","Kiiruhtivat he karkaamaan heidän päällensä sabbatin päivänä, ja antoivat heille sanoa: vieläkö te nyt 'tahdotte kovakorvaiset olla?"],[2,33,"Käykäät ulos ja tehkäät mitä kuningas on käskenyt, ja te saatte olla rauhassa.","Käykäät ulos ja tehkäät mitä kuningas on käskenyt, ja te saatte olla rauhassa."],[2,34,"Ja he vastasivat: emme tahdo lähteä, emmekä rikkoa sabbatia, niinkuin kuningas käskee.","Ja he vastasivat: emme tahdo lähteä, emmekä rikkoa sabbatia, niinkuin kuningas käskee."],[2,35,"Ja he hyökkäsivät sodalla heidän päällensä.","Ja he hyökkäsivät sodalla heidän päällensä."],[2,36,"Ja ne, jotka siellä olivat, ei itseänsä puolustaneet, eikä kiveäkään heittäneet, eikä myös luolankaan suuta tukinneet, vaan sanoivat:","Ja ne, jotka siellä olivat, ei itseänsä puolustaneet, eikä kiveäkään heittäneet, eikä myös luolankaan suuta tukinneet, vaan sanoivat:"],[2,37,"Me tahdomme näin kuolla viattomuudessamme: taivas ja maa todistavat, että te meitä väärin ja viattomasti tapatte.","Me tahdomme näin kuolla viattomuudessamme: taivas ja maa todistavat, että te meitä väärin ja viattomasti tapatte."],[2,38,"Ja niin he hyökkäsivät heidän päällensä sabbatina, ja tappoivat heidät, ja heidän vaimonsa ja lapsensa, tuhannen ihmistä, ja heidän karjansa.","Ja niin he hyökkäsivät heidän päällensä sabbatina, ja tappoivat heidät, ja heidän vaimonsa ja lapsensa, tuhannen ihmistä, ja heidän karjansa."],[2,39,"Kuin Matatias ja hänen ystävänsä sen kuulla saivat, murehtivat he sangen kovin,","Kuin Matatias ja hänen ystävänsä sen kuulla saivat, murehtivat he sangen kovin,"],[2,40,"Ja sanoivat toinen toisellensa: jos me kaikki niin tehdä tahdomme, kuin meidän veljemme tehneet ovat, ja emme sodi pakanoita vastaan, että me varjelisimme henkemme ja lakimme, niin ei heidän ole työtä meitä peräti hukuttaa maan päältä.","Ja sanoivat toinen toisellensa: jos me kaikki niin tehdä tahdomme, kuin meidän veljemme tehneet ovat, ja emme sodi pakanoita vastaan, että me varjelisimme henkemme ja lakimme, niin ei heidän ole työtä meitä peräti hukuttaa maan päältä."],[2,41,"Ja he päättivät keskenänsä, sanoen: jos he tulevat meidän päällemme sabbatina, niin varjelkaamme meitämme, ettemme kaikki hukkuisi, niinkuin meidän veljemme vuorten rotkoissa murhatut ovat.","Ja he päättivät keskenänsä, sanoen: jos he tulevat meidän päällemme sabbatina, niin varjelkaamme meitämme, ettemme kaikki hukkuisi, niinkuin meidän veljemme vuorten rotkoissa murhatut ovat."],[2,42,"Ja suuri joukko hurskaita ihmisiä kokoontuivat yhteen, jotka kaikki laissa olivat pysyväiset.","Ja suuri joukko hurskaita ihmisiä kokoontuivat yhteen, jotka kaikki laissa olivat pysyväiset."],[2,43,"Ja kaikki, jotka julmuuden tähden paenneet olivat, tulivat; heidän tykönsä.","Ja kaikki, jotka julmuuden tähden paenneet olivat, tulivat; heidän tykönsä."],[2,44,"Ja he myös nousivat ja löivät monta jumalatointa ja eriseuraista kiivaudessansa ja vihassansa; mutta muut pakenivat, ja pääsivät pakanain sekaan.","Ja he myös nousivat ja löivät monta jumalatointa ja eriseuraista kiivaudessansa ja vihassansa; mutta muut pakenivat, ja pääsivät pakanain sekaan."],[2,45,"Sitte Matatias ja hänen ystävänsä vaelsivat lujasti Israelin maata ympäri ja kukistivat maahan heidän alttarinsa,","Sitte Matatias ja hänen ystävänsä vaelsivat lujasti Israelin maata ympäri ja kukistivat maahan heidän alttarinsa,"],[2,46,"Ja ympärileikkasivat lapset, jotka vielä ympärileikkaamatta olivat,","Ja ympärileikkasivat lapset, jotka vielä ympärileikkaamatta olivat,"],[2,47,"Ja hyökkäsivät jumalattomain päälle; ja se menestyi heille,","Ja hyökkäsivät jumalattomain päälle; ja se menestyi heille,"],[2,48,"Niin että he pysyivät laissa kaikkein pakanain ja kuningasten voimaa vastaan, ettei jumalattomat yhtäkään voimusta heistä saaneet.","Niin että he pysyivät laissa kaikkein pakanain ja kuningasten voimaa vastaan, ettei jumalattomat yhtäkään voimusta heistä saaneet."],[2,49,"Mutta kuin Matatias juuri vanha oli, sanoi hän ennen kuolemaansa pojillensa: nyt on tullut meidän päällemme suuri ahdistus ja vaino, ja suuri julmuus ja raskas rangaistus;","Mutta kuin Matatias juuri vanha oli, sanoi hän ennen kuolemaansa pojillensa: nyt on tullut meidän päällemme suuri ahdistus ja vaino, ja suuri julmuus ja raskas rangaistus;"],[2,50,"Sen tähden, rakkaat poikani, pitäkäät kiivaus lain tähden, ja älkäät säästäkö henkeänne meidän: isäimme liiton tähden;","Sen tähden, rakkaat poikani, pitäkäät kiivaus lain tähden, ja älkäät säästäkö henkeänne meidän: isäimme liiton tähden;"],[2,51,"Ja mieleenne johdattakaat, mitkä työt isämme aikanansa tehneet ovat, niin te voitatte suuren kunnian ja ijankaikkisen nimen.","Ja mieleenne johdattakaat, mitkä työt isämme aikanansa tehneet ovat, niin te voitatte suuren kunnian ja ijankaikkisen nimen."],[2,52,"Abraham kiusattiin ja löydettiin vahvaksi uskossa, se luettiin hänelle vanhurskaudeksi.","Abraham kiusattiin ja löydettiin vahvaksi uskossa, se luettiin hänelle vanhurskaudeksi."],[2,53,"Joseph vaivassansa piti käskyn, ja tuli Egyptin herraksi.","Joseph vaivassansa piti käskyn, ja tuli Egyptin herraksi."],[2,54,"Pinehas, meidän isämme, piti kiivauden Jumalan kunnian tähden, ja sai todistuksen, että pappeus piti hänellä ijäti oleman.","Pinehas, meidän isämme, piti kiivauden Jumalan kunnian tähden, ja sai todistuksen, että pappeus piti hänellä ijäti oleman."],[2,55,"Josua toimitti sen käskyn, joka hänelle annettu oli, sentähden tuli hän ylimmäiseksi päämieheksi Israelissa.","Josua toimitti sen käskyn, joka hänelle annettu oli, sentähden tuli hän ylimmäiseksi päämieheksi Israelissa."],[2,56,"Kaleb antoi todistuksen ja nuhteli kansaa; sentähden sai hän erinomaisen perimisen.","Kaleb antoi todistuksen ja nuhteli kansaa; sentähden sai hän erinomaisen perimisen."],[2,57,"David jumalisuudessansa peri kuninkaallisen valtakunnan ijankaikkisesti.","David jumalisuudessansa peri kuninkaallisen valtakunnan ijankaikkisesti."],[2,58,"Elia piti kiivauden laista, ja otettiin ylös taivaasen.","Elia piti kiivauden laista, ja otettiin ylös taivaasen."],[2,59,"Anania, Atsaria ja Misael uskoivat ja tulesta pelastettiin.","Anania, Atsaria ja Misael uskoivat ja tulesta pelastettiin."],[2,60,"Daniel viattomuutensa tähden pelastettiin jalopeuran kidasta.","Daniel viattomuutensa tähden pelastettiin jalopeuran kidasta."],[2,61,"Näin mieleenne johdattakaat, mitä kullakin ajalla tapahtunut on, niin te löydätte, että kaikki ne, jotka Jumalaan uskaltavat, pysyvät vahvana.","Näin mieleenne johdattakaat, mitä kullakin ajalla tapahtunut on, niin te löydätte, että kaikki ne, jotka Jumalaan uskaltavat, pysyvät vahvana."],[2,62,"Sentähden älkäät peljätkö jumalattomain uhkauksia; sillä heidän kunniansa on loka ja toukka.","Sentähden älkäät peljätkö jumalattomain uhkauksia; sillä heidän kunniansa on loka ja toukka."],[2,63,"Tänäpänä hän on korotettu, huomenna ei häntä mistään löydetä; sillä hän on tullut maaksi jälleen, ja hänen ajatuksensa on hukkunut.","Tänäpänä hän on korotettu, huomenna ei häntä mistään löydetä; sillä hän on tullut maaksi jälleen, ja hänen ajatuksensa on hukkunut."],[2,64,"Sentähden, rakkaat lapset, olkaat rohkiat ja miehuulliset laissa, niin Jumala teitä korottaa jälleen.","Sentähden, rakkaat lapset, olkaat rohkiat ja miehuulliset laissa, niin Jumala teitä korottaa jälleen."],[2,65,"Katso, teidän veljenne Simon on viisas neuvossa, kuulkaat häntä aina niinkuin isää.","Katso, teidän veljenne Simon on viisas neuvossa, kuulkaat häntä aina niinkuin isää."],[2,66,"Juudas Makkabealainen on väkevä ja jalo sotamies hamasta nuoruudestansa, hänen pitää oleman päämiehen ja sotiman.","Juudas Makkabealainen on väkevä ja jalo sotamies hamasta nuoruudestansa, hänen pitää oleman päämiehen ja sotiman."],[2,67,"Ja ottakaat tykönne kaikki ne, jotka lain pitävät; kostakaat se väkivalta, joka teidän kansallenne tehty on.","Ja ottakaat tykönne kaikki ne, jotka lain pitävät; kostakaat se väkivalta, joka teidän kansallenne tehty on."],[2,68,"Ja maksakaat pakanoille sen jälkeen, minkä he ansainneet ovat, ja pysykäät lujasti laissa.","Ja maksakaat pakanoille sen jälkeen, minkä he ansainneet ovat, ja pysykäät lujasti laissa."],[2,69,"Sitte hän siunasi heitä, ja tuli kutsutuksi isäinsä tykö,","Sitte hän siunasi heitä, ja tuli kutsutuksi isäinsä tykö,"],[2,70,"Ja kuoli, kuin hän oli sadan ja kuuden ajastaikainen viidettäkymmentä. Ja hänen poikansa hautasivat hänen isänsä hautaan Modin kaupungissa, ja koko Israel murehti häntä suurella murheella.","Ja kuoli, kuin hän oli sadan ja kuuden ajastaikainen viidettäkymmentä. Ja hänen poikansa hautasivat hänen isänsä hautaan Modin kaupungissa, ja koko Israel murehti häntä suurella murheella."],[3,1,"Juudas Makkabealaisen sotavalmistuksesta ja hänen vihollisistansa. Ja Juudas, joka kutsuttiin Makkabealaiseksi, tuli isänsä siaan.","Juudas Makkabealaisen sotavalmistuksesta ja hänen vihollisistansa. Ja Juudas, joka kutsuttiin Makkabealaiseksi, tuli isänsä siaan."],[3,2,"Ja kaikki hänen veljensä, ja kaikki, jotka hänen isänsä kanssa yhtä pitäneet olivat, auttivat häntä (vihollisia vastaan) ja sotivat Israelin edestä ilolla.","Ja kaikki hänen veljensä, ja kaikki, jotka hänen isänsä kanssa yhtä pitäneet olivat, auttivat häntä (vihollisia vastaan) ja sotivat Israelin edestä ilolla."],[3,3,"Ja Juudas saatti suuren kunnian kansallensa, hän oli haarniskoissansa niinkuin sankari, ja varjeli miekallansa sotajoukkonsa.","Ja Juudas saatti suuren kunnian kansallensa, hän oli haarniskoissansa niinkuin sankari, ja varjeli miekallansa sotajoukkonsa."],[3,4,"Hän oli rohkia niinkuin jalopeura, ja pelkäämätöin niinkuin nuori kiljuva jalopeura, kuin se juoksee saaliin jälkeen.","Hän oli rohkia niinkuin jalopeura, ja pelkäämätöin niinkuin nuori kiljuva jalopeura, kuin se juoksee saaliin jälkeen."],[3,5,"Hän etsi luopuneita ja jumalattomia, jotka vaativat kansaa luopumaan laista, rankaisi ja poltti heidät.","Hän etsi luopuneita ja jumalattomia, jotka vaativat kansaa luopumaan laista, rankaisi ja poltti heidät."],[3,6,"Niin että hänen vihollisensa pelkäsivät häntä kaikissa paikoissa ja pakenivat, ja luopuneet tulivat poljetuksi, ja hän sai onnen ja voiton.","Niin että hänen vihollisensa pelkäsivät häntä kaikissa paikoissa ja pakenivat, ja luopuneet tulivat poljetuksi, ja hän sai onnen ja voiton."],[3,7,"Tästä sai moni kuningas karvaan mielen, vaan Jakobille oli se iloksi, ja hänelle itselle ijankaikkiseksi muistoksi ja kunniaksi.","Tästä sai moni kuningas karvaan mielen, vaan Jakobille oli se iloksi, ja hänelle itselle ijankaikkiseksi muistoksi ja kunniaksi."],[3,8,"Hän vaelsi Juudan kaupunkien lävitse, ja surmasi jumalattomia, ja käänsi pois vihan Israelista.","Hän vaelsi Juudan kaupunkien lävitse, ja surmasi jumalattomia, ja käänsi pois vihan Israelista."],[3,9,"Ja hän oli kuuluisa hamaan maan ääreen, niin että kaikki maahan poljetut pakenivat hänen tykönsä.","Ja hän oli kuuluisa hamaan maan ääreen, niin että kaikki maahan poljetut pakenivat hänen tykönsä."],[3,10,"Sentähden kokosi Apollonius pakanoista ja Samariasta suuren sotaväen, sotimaan Israelia vastaan.","Sentähden kokosi Apollonius pakanoista ja Samariasta suuren sotaväen, sotimaan Israelia vastaan."],[3,11,"Kuin Juudas sen kuuli, meni hän häntä vastaan, löi ja tappoi hänen ja suuren joukon vihollisia, ynnä hänen kanssansa vaan ne, jotka pääsivät, pakenivat.","Kuin Juudas sen kuuli, meni hän häntä vastaan, löi ja tappoi hänen ja suuren joukon vihollisia, ynnä hänen kanssansa vaan ne, jotka pääsivät, pakenivat."],[3,12,"Ja Juudas sai heidän kalunsa, ja otti Apolloniuksen miekan, jonka hän sitte kantoi kaiken elinaikansa.","Ja Juudas sai heidän kalunsa, ja otti Apolloniuksen miekan, jonka hän sitte kantoi kaiken elinaikansa."],[3,13,"Senjälkeen, kuin Seron, Syrian sodanpäämies, sai kuulla uskollisten joukon pitävän yhtä Juudaan kanssa, ja siellä olevan koossa suuren sotaväen joukon, sanoi hän:","Senjälkeen, kuin Seron, Syrian sodanpäämies, sai kuulla uskollisten joukon pitävän yhtä Juudaan kanssa, ja siellä olevan koossa suuren sotaväen joukon, sanoi hän:"],[3,14,"Minä tahdon voittaa kunnian, että minä ylistettäisiin koko valtakunnassa, ja tahdon lyödä Juudaan ja hänen joukkonsa, jotka kuninkaan käskyn ovat katsoneet ylön.","Minä tahdon voittaa kunnian, että minä ylistettäisiin koko valtakunnassa, ja tahdon lyödä Juudaan ja hänen joukkonsa, jotka kuninkaan käskyn ovat katsoneet ylön."],[3,15,"Sentähden hankitsi hän itsensä ja suuri väki meni hänen kanssansa kostamaan Israelia, ja tulivat hamaan Bethoronin paltaan asti.","Sentähden hankitsi hän itsensä ja suuri väki meni hänen kanssansa kostamaan Israelia, ja tulivat hamaan Bethoronin paltaan asti."],[3,16,"Silloin meni Juudas häntä vastaan vähällä joukolla.","Silloin meni Juudas häntä vastaan vähällä joukolla."],[3,17,"Mutta kuin he saivat nähdä viholliset, sanoivat he Juudaalle: meitä on vähä, ja me olemme myös heikot paastosta, kuinka siis me voimme lyödä niin suurta väkevää joukkoa?","Mutta kuin he saivat nähdä viholliset, sanoivat he Juudaalle: meitä on vähä, ja me olemme myös heikot paastosta, kuinka siis me voimme lyödä niin suurta väkevää joukkoa?"],[3,18,"Mutta Juudas sanoi: se taitaa kyllä tapahtua, että vähä joukko voittaa suuren; sillä Jumala taitaa kyllä antaa voiton, niin vähän joukon kuin paljonkin kautta;","Mutta Juudas sanoi: se taitaa kyllä tapahtua, että vähä joukko voittaa suuren; sillä Jumala taitaa kyllä antaa voiton, niin vähän joukon kuin paljonkin kautta;"],[3,19,"Sillä voitto tulee taivaasta, ja ei väen paljoudesta.","Sillä voitto tulee taivaasta, ja ei väen paljoudesta."],[3,20,"He uskaltavat suureen väkeensä, ja aikovat tappaa ja hävittää meitä, meidän vaimomme ja lapsemme.","He uskaltavat suureen väkeensä, ja aikovat tappaa ja hävittää meitä, meidän vaimomme ja lapsemme."],[3,21,"Vaan meidän pitää meitämme varjeleman ja sotiman meidän henkemme edestä ja meidän lakimme edestä.","Vaan meidän pitää meitämme varjeleman ja sotiman meidän henkemme edestä ja meidän lakimme edestä."],[3,22,"Sentähden on Jumala heitä maahan lyövä meidän silmäimme edessä: ei teidän pidä heitä pelkäämän.","Sentähden on Jumala heitä maahan lyövä meidän silmäimme edessä: ei teidän pidä heitä pelkäämän."],[3,23,"Kuin hän näin puhunut oli, hyökkäsi hän hopusti vihollisten päälle, ennen kuin he sen äkkäsivät, ja löi Seronin ja hänen väkensä pakoon,","Kuin hän näin puhunut oli, hyökkäsi hän hopusti vihollisten päälle, ennen kuin he sen äkkäsivät, ja löi Seronin ja hänen väkensä pakoon,"],[3,24,"Ja ajoi heitä takaa Bethoronista alaspäin, niin lakialle kedolle, ja löi heitä kuoliaaksi kahdeksansataa; ja ne, jotka pääsivät, pakenivat Philistealaisten maalle.","Ja ajoi heitä takaa Bethoronista alaspäin, niin lakialle kedolle, ja löi heitä kuoliaaksi kahdeksansataa; ja ne, jotka pääsivät, pakenivat Philistealaisten maalle."],[3,25,"Niin tuli suuri pelko kaikille kansoille ympäristöllä Juudaan ja hänen veljeinsä edessä.","Niin tuli suuri pelko kaikille kansoille ympäristöllä Juudaan ja hänen veljeinsä edessä."],[3,26,"Ja kaikissa maakunnissa puhuttiin Juudaasta ja hänen teoistansa; ja se tuli myös kuninkaan korville.","Ja kaikissa maakunnissa puhuttiin Juudaasta ja hänen teoistansa; ja se tuli myös kuninkaan korville."],[3,27,"Kuin Antiokus nämät kaikki kuulla sai, julmistui hän ylönpalttisesti, lähetti ja antoi käskyn kaikkeen valtakuntaansa, ja kokosi suuren väen;","Kuin Antiokus nämät kaikki kuulla sai, julmistui hän ylönpalttisesti, lähetti ja antoi käskyn kaikkeen valtakuntaansa, ja kokosi suuren väen;"],[3,28,"Ja otti tavarastansa ja valmisti vuoden palkan, ja antoi käskyn, että kaikissa paikoissa piti oltaman valmiina sotaan.","Ja otti tavarastansa ja valmisti vuoden palkan, ja antoi käskyn, että kaikissa paikoissa piti oltaman valmiina sotaan."],[3,29,"Mutta kuin hän näki, ettei hänellä ollut rahaa täydeksi, ja ettei maakunta niin paljon antaa voinut, sen sodan tähden, jonka hän kauvan oli pitänyt lakia vastaan,","Mutta kuin hän näki, ettei hänellä ollut rahaa täydeksi, ja ettei maakunta niin paljon antaa voinut, sen sodan tähden, jonka hän kauvan oli pitänyt lakia vastaan,"],[3,30,"Pelkäsi hän, ettei hän voinut senkaltaista kulutusta vasta tehdä, kuin siihen päivään asti; sillä hän oli palkkaa ja lahjoja enemmän antanut ulos, kuin kaikki kuninkaat hänen edellänsä.","Pelkäsi hän, ettei hän voinut senkaltaista kulutusta vasta tehdä, kuin siihen päivään asti; sillä hän oli palkkaa ja lahjoja enemmän antanut ulos, kuin kaikki kuninkaat hänen edellänsä."],[3,31,"Sentähden tuli hän surulliseksi, ja matkusti Persian maata verolliseksi laskemaan, ja kokoomaan paljon rahaa.","Sentähden tuli hän surulliseksi, ja matkusti Persian maata verolliseksi laskemaan, ja kokoomaan paljon rahaa."],[3,32,"Ja hän jätti siaansa yhden päämiehen kuninkaan asiain päälle koko valtakuntaansa, ruveten Euphratista, niin hamaan Egyptiin asti,","Ja hän jätti siaansa yhden päämiehen kuninkaan asiain päälle koko valtakuntaansa, ruveten Euphratista, niin hamaan Egyptiin asti,"],[3,33,"Ja antoi hänen kasvattaa poikaansa, nuorta Antiokusta, siihen asti kuin hän palajava oli,","Ja antoi hänen kasvattaa poikaansa, nuorta Antiokusta, siihen asti kuin hän palajava oli,"],[3,34,"Ja antoi hänelle puolen sotaväestä ja elephanteista, ja käski häntä kaikista asioista ja Juudan ja Jerusalemin asuvaisista:","Ja antoi hänelle puolen sotaväestä ja elephanteista, ja käski häntä kaikista asioista ja Juudan ja Jerusalemin asuvaisista:"],[3,35,"Että hänen piti lähettämän sotajoukon heitä vastaan surettamaan jääneen kansan Israelissa ja Jerusalemissa, ja hukuttamaan heidän muistonsa siitä paikasta,","Että hänen piti lähettämän sotajoukon heitä vastaan surettamaan jääneen kansan Israelissa ja Jerusalemissa, ja hukuttamaan heidän muistonsa siitä paikasta,"],[3,36,"Ja asettamaan muukalaisia sinne asumaan, ja että pakanoille piti maa jaettaman.","Ja asettamaan muukalaisia sinne asumaan, ja että pakanoille piti maa jaettaman."],[3,37,"Sillä seitsemäntenä vuotena viidettäkymmentä toista sataa läksi kuningas kaupungistansa Antiokiasta ja meni Euphratin virran ylitse, ja vaelsi ylimmäisten maakuntain lävitse.","Sillä seitsemäntenä vuotena viidettäkymmentä toista sataa läksi kuningas kaupungistansa Antiokiasta ja meni Euphratin virran ylitse, ja vaelsi ylimmäisten maakuntain lävitse."],[3,38,"Mutta Lysias valitsi muutamia voimallisia miehiä kuninkaan ystävistä päämiehiksi, nimittäin: Ptolomeuksen Dorimenin pojan, Nikanorin ja Gorgian.","Mutta Lysias valitsi muutamia voimallisia miehiä kuninkaan ystävistä päämiehiksi, nimittäin: Ptolomeuksen Dorimenin pojan, Nikanorin ja Gorgian."],[3,39,"Ja antoi heille neljäkymmentä tuhatta jalkamiestä ja seitsemäntuhatta hevosmiestä, että heidän piti menemän Juudan maahan ja hävittämän Juudalaisia, niinkuin kuningas oli käskenyt.","Ja antoi heille neljäkymmentä tuhatta jalkamiestä ja seitsemäntuhatta hevosmiestä, että heidän piti menemän Juudan maahan ja hävittämän Juudalaisia, niinkuin kuningas oli käskenyt."],[3,40,"Kuin he nyt tällä väellä lähteneet olivat, tulivat he ja sioittivat heitänsä Emmaonin tykö, tasaiselle kedolle.","Kuin he nyt tällä väellä lähteneet olivat, tulivat he ja sioittivat heitänsä Emmaonin tykö, tasaiselle kedolle."],[3,41,"Kuin sen maakunnan kauppamiehet ympäristöllä sen kuulivat, tulivat he leiriin, ja toivat myötänsä paljon rahaa, ostaaksensa Israelin lapsia orjaksensa. Ja Syriasta ja muista pakanoista meni enempi sotaväkeä heidän tykönsä.","Kuin sen maakunnan kauppamiehet ympäristöllä sen kuulivat, tulivat he leiriin, ja toivat myötänsä paljon rahaa, ostaaksensa Israelin lapsia orjaksensa. Ja Syriasta ja muista pakanoista meni enempi sotaväkeä heidän tykönsä."],[3,42,"Kuin nyt Juudas Ja hänen veljensä näkivät, että vaino eneni ja vihollinen makasi heidän rajoillansa, ja he saivat ymmärtää, että kuningas oli käskenyt hukuttaa kaiken Juudean,","Kuin nyt Juudas Ja hänen veljensä näkivät, että vaino eneni ja vihollinen makasi heidän rajoillansa, ja he saivat ymmärtää, että kuningas oli käskenyt hukuttaa kaiken Juudean,"],[3,43,"Rohkaisivat he itsensä, Ja olivat yhtäpitäväiset, että he tahtoivat kansansa avuksi ehtiä ja sotia pyhän edestä.","Rohkaisivat he itsensä, Ja olivat yhtäpitäväiset, että he tahtoivat kansansa avuksi ehtiä ja sotia pyhän edestä."],[3,44,"Sentähden kokosivat he sotaväkensä yhteen, että he olisivat aikanansa valmiit sotimaan ja rukoilemaan Jumalalta armoa ja apua.","Sentähden kokosivat he sotaväkensä yhteen, että he olisivat aikanansa valmiit sotimaan ja rukoilemaan Jumalalta armoa ja apua."],[3,45,"Mutta siihen aikaan oli Jerusalem autio, ja ei siellä yksikään Israelin lapsista enään asunut, ja pyhä oli saastutettu epäjumalilla, jotka sinne pannut olivat, ja pakanat asuivat linnassa, ja kaikki kunnia oli Jakobista otettu pois, ei myös siellä kuulunut huilua eikä kanteletta.","Mutta siihen aikaan oli Jerusalem autio, ja ei siellä yksikään Israelin lapsista enään asunut, ja pyhä oli saastutettu epäjumalilla, jotka sinne pannut olivat, ja pakanat asuivat linnassa, ja kaikki kunnia oli Jakobista otettu pois, ei myös siellä kuulunut huilua eikä kanteletta."],[3,46,"Sentähden tuli kansa yhteen Mitspassa, joka on Jerusalemin kohdalla; sillä Mitspassa piti Israelin entisiin aikoin rukoileman.","Sentähden tuli kansa yhteen Mitspassa, joka on Jerusalemin kohdalla; sillä Mitspassa piti Israelin entisiin aikoin rukoileman."],[3,47,"Tässä paikassa tulivat he myös nyt kokoon, paastosivat ja pukivat säkit yllensä, ja panivat tuhkaa päänsä päälle, ja repäisivät vaatteensa rikki,","Tässä paikassa tulivat he myös nyt kokoon, paastosivat ja pukivat säkit yllensä, ja panivat tuhkaa päänsä päälle, ja repäisivät vaatteensa rikki,"],[3,48,"Ja toivat lakikirjat edes, joita pakanat olivat etsiä antaneet kirjoittaaksensa niihin epäjumalainsa kuvat.","Ja toivat lakikirjat edes, joita pakanat olivat etsiä antaneet kirjoittaaksensa niihin epäjumalainsa kuvat."],[3,49,"He veivät sinne myös pappein vaatteet, esikoiset ja kymmenykset, tekivät nasiiria, joiden määrätystä ajasta piti ottaman vaarin,","He veivät sinne myös pappein vaatteet, esikoiset ja kymmenykset, tekivät nasiiria, joiden määrätystä ajasta piti ottaman vaarin,"],[3,50,"Ja huusivat surkiasti taivaasen, sanoen: mitä me nyt näillä teemme? ja kuhunka me nämät viemme?","Ja huusivat surkiasti taivaasen, sanoen: mitä me nyt näillä teemme? ja kuhunka me nämät viemme?"],[3,51,"Sillä sinun pyhäs on saastutettu, ja papit ovat ajetut pois.","Sillä sinun pyhäs on saastutettu, ja papit ovat ajetut pois."],[3,52,"Ja katso, pakanat kokoontuvat meitä vastaan, että he meidät peräti kadottaisivat.","Ja katso, pakanat kokoontuvat meitä vastaan, että he meidät peräti kadottaisivat."],[3,53,"Sinä tiedät, mitä heidän mielessänsä on meitä vastaan. Kuinka me taidamme heidän edessänsä seisoa, jollet sinä meitä auta, meidän Jumalamme!","Sinä tiedät, mitä heidän mielessänsä on meitä vastaan. Kuinka me taidamme heidän edessänsä seisoa, jollet sinä meitä auta, meidän Jumalamme!"],[3,54,"Senjälkeen antoi Juudas kutsua kansan vaskitorvilla kokoon, ja asetti hallituksen päämiehet, esimiehet, väen asettajat, ja tuhanten, satain, viidenkymmenten ja kymmenten johdattajat","Senjälkeen antoi Juudas kutsua kansan vaskitorvilla kokoon, ja asetti hallituksen päämiehet, esimiehet, väen asettajat, ja tuhanten, satain, viidenkymmenten ja kymmenten johdattajat"],[3,55,"Ja antoi kuuluttaa, että jotka kartanoita rakentaneet olivat, ja vaimon kihlanneet, ja viinapuita istuttaneet, eli jotka pelkurit olivat, piti kotiansa palajaman, niinkuin laki antaa myöten.","Ja antoi kuuluttaa, että jotka kartanoita rakentaneet olivat, ja vaimon kihlanneet, ja viinapuita istuttaneet, eli jotka pelkurit olivat, piti kotiansa palajaman, niinkuin laki antaa myöten."],[3,56,"Sitte he läksivät matkaan, ja sioittivat itsensä myös Emmaonin tykö, etelän puolella.","Sitte he läksivät matkaan, ja sioittivat itsensä myös Emmaonin tykö, etelän puolella."],[3,57,"Ja Juudas neuvoi väkeänsä ja sanoi: hankitkaat ja älkäät hämmästykö, että te huomeneksi valmiit olisitte sotimaan pakanoita vastaan, jotka meitä ja meidän pyhäämme aikovat maahan lyödä.","Ja Juudas neuvoi väkeänsä ja sanoi: hankitkaat ja älkäät hämmästykö, että te huomeneksi valmiit olisitte sotimaan pakanoita vastaan, jotka meitä ja meidän pyhäämme aikovat maahan lyödä."],[3,58,"Sillä se on meille parempi, että me kuolemme sodassa, kuin se, että me näemme senkaltaista tuskaa, joka on tullut meidän kansamme ja jumalanpalveluksemme päälle.","Sillä se on meille parempi, että me kuolemme sodassa, kuin se, että me näemme senkaltaista tuskaa, joka on tullut meidän kansamme ja jumalanpalveluksemme päälle."],[3,59,"Mutta niinkuin Jumalan tahto on taivaassa, niin tapahtukoon.","Mutta niinkuin Jumalan tahto on taivaassa, niin tapahtukoon."],[4,1,"Juudaan voitosta Gorgiaa vastaan, niin myös pyhän ja jumalanpalveluksen uudistamisesta. Ja Gorgias otti viisituhatta jalkamiestä ja tuhannen parasta ratsasmiestä, ja meni yöllä salaisesti Juudalaisten leiriin,","Juudaan voitosta Gorgiaa vastaan, niin myös pyhän ja jumalanpalveluksen uudistamisesta. Ja Gorgias otti viisituhatta jalkamiestä ja tuhannen parasta ratsasmiestä, ja meni yöllä salaisesti Juudalaisten leiriin,"],[4,2,"Että hän olis tietämättä karannut heidän päällensä ja muutamat niistä, jotka linnassa maanneet olivat, olivat heidän johdattajansa.","Että hän olis tietämättä karannut heidän päällensä ja muutamat niistä, jotka linnassa maanneet olivat, olivat heidän johdattajansa."],[4,3,"Vaan kuin Juudas sai sen ymmärtää, niin hän nousi, ja vahvin väki hänen kanssansa, ennättämään ja pettämään vihollisia,","Vaan kuin Juudas sai sen ymmärtää, niin hän nousi, ja vahvin väki hänen kanssansa, ennättämään ja pettämään vihollisia,"],[4,4,"Ja lyömään heitä, kuin he vielä siellä ja täällä hajalla olivat.","Ja lyömään heitä, kuin he vielä siellä ja täällä hajalla olivat."],[4,5,"Kuin Gorgias Juudaan leiriin tuli, ja ei sieltä ketään löytänyt, etsi hän heitä vuorten päällä; sillä hän luuli heidän paenneen hänen edestänsä.","Kuin Gorgias Juudaan leiriin tuli, ja ei sieltä ketään löytänyt, etsi hän heitä vuorten päällä; sillä hän luuli heidän paenneen hänen edestänsä."],[4,6,"Mutta Juudas riensi, että hän varhain aamulla olis joutunut kedolle väljään, kolmellatuhannella miehellä, joilla ei kuitenkaan haarniskoita ollut, vaan ainoastaan heidän vaatteensa ja miekkansa.","Mutta Juudas riensi, että hän varhain aamulla olis joutunut kedolle väljään, kolmellatuhannella miehellä, joilla ei kuitenkaan haarniskoita ollut, vaan ainoastaan heidän vaatteensa ja miekkansa."],[4,7,"Kuin he näkivät, että viholliset hyvin hankitut ja raudoitetut olivat, ja että heillä olivat jalot sota-aseet ja harjoitettu sotaväki,","Kuin he näkivät, että viholliset hyvin hankitut ja raudoitetut olivat, ja että heillä olivat jalot sota-aseet ja harjoitettu sotaväki,"],[4,8,"Sanoi Juudas väellensä: älkäät peljätkö tätä suurta joukkoa, ja älkäät hämmästykö heidän voimaansa.","Sanoi Juudas väellensä: älkäät peljätkö tätä suurta joukkoa, ja älkäät hämmästykö heidän voimaansa."],[4,9,"Muistakaat, kuinka meidän isämme Punaisessa meressä tulivat pelastetuksi, kuin Pharao suurella sotajoukolla heitä ajoi takaa.","Muistakaat, kuinka meidän isämme Punaisessa meressä tulivat pelastetuksi, kuin Pharao suurella sotajoukolla heitä ajoi takaa."],[4,10,"Ja huutakaamme nyt taivaasen, niin Herra myös meitä armahtaa, ja muistaa liiton, jonka hän meidän isillemme tehnyt on,","Ja huutakaamme nyt taivaasen, niin Herra myös meitä armahtaa, ja muistaa liiton, jonka hän meidän isillemme tehnyt on,"],[4,11,"Ja lyö meidän vihollisemme maahan meidän silmäimme edessä tänäpänä. Ja kaikki pakanat pitää ymmärtämän, että se on Jumala, joka auttaa ja pelastaa Israelin.","Ja lyö meidän vihollisemme maahan meidän silmäimme edessä tänäpänä. Ja kaikki pakanat pitää ymmärtämän, että se on Jumala, joka auttaa ja pelastaa Israelin."],[4,12,"Kuin pakanat näkivät, että Juudas tuli heitä vastaan,","Kuin pakanat näkivät, että Juudas tuli heitä vastaan,"],[4,13,"Läksivät he myös leiristänsä sotimaan Juudaa vastaan.","Läksivät he myös leiristänsä sotimaan Juudaa vastaan."],[4,14,"Mutta Juudas antoi puhaltaa vaskitorviin ja löi vihollisia; ja pakanat lyötiin pakoon, ja he pakenivat siltä väliltä ja ne jälkimäiset lankesivat miekan edessä.","Mutta Juudas antoi puhaltaa vaskitorviin ja löi vihollisia; ja pakanat lyötiin pakoon, ja he pakenivat siltä väliltä ja ne jälkimäiset lankesivat miekan edessä."],[4,15,"Sillä Juudas ajoi heitä takaa hamaan Assaremotin ja Edomin ketoon asti, Asdodiin ja Jamniaan asti, ja heistä laukesi siellä kolmetuhatta miestä.","Sillä Juudas ajoi heitä takaa hamaan Assaremotin ja Edomin ketoon asti, Asdodiin ja Jamniaan asti, ja heistä laukesi siellä kolmetuhatta miestä."],[4,16,"Mutta kuin Juudas ja hänen sotaväkensä palasi heitä takaa ajamasta, haastoi hän väkeänsä ja sanoi: ei teidän pidä mitään saalista ottaman;","Mutta kuin Juudas ja hänen sotaväkensä palasi heitä takaa ajamasta, haastoi hän väkeänsä ja sanoi: ei teidän pidä mitään saalista ottaman;"],[4,17,"Sillä meidän pitää vielä kerran sotiman vihollisia vastaan.","Sillä meidän pitää vielä kerran sotiman vihollisia vastaan."],[4,18,"Gorgias on väkinensä meidän edessämme mäellä; sentähden seisokaat nyt niinkuin te asetetut olette vihollista vastaan, ja puolustakaat teitänne, ja kuin te olette viholliset lyöneet, niin te saatte pelkäämättä ja ilman vaaraa saaliin ottaa.","Gorgias on väkinensä meidän edessämme mäellä; sentähden seisokaat nyt niinkuin te asetetut olette vihollista vastaan, ja puolustakaat teitänne, ja kuin te olette viholliset lyöneet, niin te saatte pelkäämättä ja ilman vaaraa saaliin ottaa."],[4,19,"Kuin Juudas näitä puhui, näkyi yksi joukko.","Kuin Juudas näitä puhui, näkyi yksi joukko."],[4,20,"Ja Gorgias näki, että hänen väkensä lyöty oli ja heidän leirinsä poltettu, sillä hän näki savun, josta hän ymmärsi, mitä tapahtunut oli.","Ja Gorgias näki, että hänen väkensä lyöty oli ja heidän leirinsä poltettu, sillä hän näki savun, josta hän ymmärsi, mitä tapahtunut oli."],[4,21,"Näkivät he myös Juudaan ja hänen sotaväkensä väljällä olevan, hankitut sotaan;","Näkivät he myös Juudaan ja hänen sotaväkensä väljällä olevan, hankitut sotaan;"],[4,22,"Sentähden hämmästyi Gorgias sangen kovin, ja pakeni pakanain maalle.","Sentähden hämmästyi Gorgias sangen kovin, ja pakeni pakanain maalle."],[4,23,"Ja niin käänsi Juudas itsensä takaperin saaliin päälle, joka leirissä oli, ja sai suuren tavaran, paljon kultaa, hopiaa, silkkiä, purppuraa ja paljon muuta riistaa.","Ja niin käänsi Juudas itsensä takaperin saaliin päälle, joka leirissä oli, ja sai suuren tavaran, paljon kultaa, hopiaa, silkkiä, purppuraa ja paljon muuta riistaa."],[4,24,"Sitte menivät he kotiansa, kiittivät ja kunnioittivat Jumalaa veisuilla, ja sanoivat: kiittäkäät Herraa, sillä hän on laupias, ja hänen laupiutensa pysyy ijankaikkisesti.","Sitte menivät he kotiansa, kiittivät ja kunnioittivat Jumalaa veisuilla, ja sanoivat: kiittäkäät Herraa, sillä hän on laupias, ja hänen laupiutensa pysyy ijankaikkisesti."],[4,25,"Tänäpänä sai Israel kuuluisan voiton.","Tänäpänä sai Israel kuuluisan voiton."],[4,26,"Mutta ne pakanat, jotka päässeet olivat, tulivat Lysiaan tykö, ja sanoivat hänelle, kuinka heille tapahtunut oli.","Mutta ne pakanat, jotka päässeet olivat, tulivat Lysiaan tykö, ja sanoivat hänelle, kuinka heille tapahtunut oli."],[4,27,"Kuin hän sen kuuli, tuli hän sangen murheelliseksi, ettei se niin tapahtunut, kuin kuningas oli käskenyt.","Kuin hän sen kuuli, tuli hän sangen murheelliseksi, ettei se niin tapahtunut, kuin kuningas oli käskenyt."],[4,28,"Sentähden kokosi Lysias taas toisena vuotena kohta sen perästä paljon sotaväkeä, kuusikymmentä tuhatta jalkamiestä ja viisituhatta ratsasmiestä lyömään Juudalaisia.","Sentähden kokosi Lysias taas toisena vuotena kohta sen perästä paljon sotaväkeä, kuusikymmentä tuhatta jalkamiestä ja viisituhatta ratsasmiestä lyömään Juudalaisia."],[4,29,"Tämä sotajoukko meni Idumeaan, ja sioitti itsensä Betsuran tykö; sinne tuli myös Juudas kymmenellätuhannella miehellä.","Tämä sotajoukko meni Idumeaan, ja sioitti itsensä Betsuran tykö; sinne tuli myös Juudas kymmenellätuhannella miehellä."],[4,30,"Mutta kuin hän näki, että vihollisella niin paljo väkeä oli, rukoili hän ja sanoi: kiitos olkoon sinulle, sinä Israelin vapahtaja, sinä, joka sinun palveIias Davidin käden kautta löit suuren sankarin, ja koko pakanain sotajoukon annoit Jonatanin Saulin pojan ja hänen palveliansa käsiin.","Mutta kuin hän näki, että vihollisella niin paljo väkeä oli, rukoili hän ja sanoi: kiitos olkoon sinulle, sinä Israelin vapahtaja, sinä, joka sinun palveIias Davidin käden kautta löit suuren sankarin, ja koko pakanain sotajoukon annoit Jonatanin Saulin pojan ja hänen palveliansa käsiin."],[4,31,"Minä rukoilen sinua, ettäs myös tahtoisit nämät meidän vihollisemme antaa.kansas Israelin käsiin, että he väkensä ja ratsasmiestensä kanssa häpiään tulisivat.","Minä rukoilen sinua, ettäs myös tahtoisit nämät meidän vihollisemme antaa.kansas Israelin käsiin, että he väkensä ja ratsasmiestensä kanssa häpiään tulisivat."],[4,32,"Anna heille hämmästynyt ja vapiseva sydän,","Anna heille hämmästynyt ja vapiseva sydän,"],[4,33,"Ja lyö heitä niiden miekalla, jotka sinua rakastavat, että kaikki mahtaisivat sinua kiittää ja kunnioittaa, jotka sinun nimes tuntevat!","Ja lyö heitä niiden miekalla, jotka sinua rakastavat, että kaikki mahtaisivat sinua kiittää ja kunnioittaa, jotka sinun nimes tuntevat!"],[4,34,"Sitte löi hän heitä, ja Lysiaan väestä lankesi viisituhatta miestä.","Sitte löi hän heitä, ja Lysiaan väestä lankesi viisituhatta miestä."],[4,35,"Mutta kuin Lysias näki, että hänen väkensä pakeni, ja Juudalaiset olivat rohkiat ja valmiit sekä kunniallisesti elämään että kunniallisesti kuolemaan, meni hän Antiokiaan ottamaan sotaväkeä jälleen, että hän vielä vahvempana olis tullut Juudalaisia vastaan.","Mutta kuin Lysias näki, että hänen väkensä pakeni, ja Juudalaiset olivat rohkiat ja valmiit sekä kunniallisesti elämään että kunniallisesti kuolemaan, meni hän Antiokiaan ottamaan sotaväkeä jälleen, että hän vielä vahvempana olis tullut Juudalaisia vastaan."],[4,36,"Mutta Juudas ja hänen veljensä sanoivat: että meidäu vihollisemme on karkotettu, niin käykäämme puhdistamaan ja uudistamaan pyhä sia.","Mutta Juudas ja hänen veljensä sanoivat: että meidäu vihollisemme on karkotettu, niin käykäämme puhdistamaan ja uudistamaan pyhä sia."],[4,37,"Sen tähden tuli sotaväki yhteen, ja menivät kaikki ylös Zionin vuorelle.","Sen tähden tuli sotaväki yhteen, ja menivät kaikki ylös Zionin vuorelle."],[4,38,"Ja kuin he näkivät, että pyhä sia oli hävitetty, ja alttari saastutettu, portit poltetut, ja esikartanoissa vesat ja ruohot kasvoivat, niinkuin metsässä ja mäellä, ja pappein asumasiat maahan rauvenneeksi:","Ja kuin he näkivät, että pyhä sia oli hävitetty, ja alttari saastutettu, portit poltetut, ja esikartanoissa vesat ja ruohot kasvoivat, niinkuin metsässä ja mäellä, ja pappein asumasiat maahan rauvenneeksi:"],[4,39,"Silloin he repäisivät vaatteensa, ja itkivät katkerasti ja panivat tuhkaa päänsä päälle,","Silloin he repäisivät vaatteensa, ja itkivät katkerasti ja panivat tuhkaa päänsä päälle,"],[4,40,"Lankesivat maahan kasvoillensa, ja antoivat soittaa vaskitorvella, ja huusivat taivaasen.","Lankesivat maahan kasvoillensa, ja antoivat soittaa vaskitorvella, ja huusivat taivaasen."],[4,41,"Ja Juudas asetti yhden joukon estämään vihollisia, jotka linnassa olivat, kuin hän oli puhdistava pyhää siaa,","Ja Juudas asetti yhden joukon estämään vihollisia, jotka linnassa olivat, kuin hän oli puhdistava pyhää siaa,"],[4,42,"Ja asetti siihen papit, jotka ei itsiänsä saastuttaneet, vaan olivat olleet pysyväiset laissa.","Ja asetti siihen papit, jotka ei itsiänsä saastuttaneet, vaan olivat olleet pysyväiset laissa."],[4,43,"Nämät puhdistivat pyhän sian, ja veivät pois kauhistuksen ja saastaiset kivet saastaiseen paikkaan.","Nämät puhdistivat pyhän sian, ja veivät pois kauhistuksen ja saastaiset kivet saastaiseen paikkaan."],[4,44,"Ja että polttouhrln alttari myös saastutettu oli, pitivät he neuvoa, kuinka heidän sen kanssa piti tekemän.","Ja että polttouhrln alttari myös saastutettu oli, pitivät he neuvoa, kuinka heidän sen kanssa piti tekemän."],[4,45,"Ja löysivät hyvän neuvon: että se piti peräti maahan purettaman, ettei siitä pahennusta pitänyt tuleman, että pakanat olivat saastuttaneet sen; sen tähden lyötiin se kaikki maahan,","Ja löysivät hyvän neuvon: että se piti peräti maahan purettaman, ettei siitä pahennusta pitänyt tuleman, että pakanat olivat saastuttaneet sen; sen tähden lyötiin se kaikki maahan,"],[4,46,"Ja panivat tallelle kivet mäelle lähes huonetta, erinomaiseen paikkaan, siihenasti kuin joku propheta olis tullut ja sanonut, mitä niillä piti tehtämän.","Ja panivat tallelle kivet mäelle lähes huonetta, erinomaiseen paikkaan, siihenasti kuin joku propheta olis tullut ja sanonut, mitä niillä piti tehtämän."],[4,47,"Mutta he ottivat toiset uudet vuolemattomat kivet lain jälkeen, ja tekivät uuden alttarin, senkaltaisen kuin se entinenkin oli ollut,","Mutta he ottivat toiset uudet vuolemattomat kivet lain jälkeen, ja tekivät uuden alttarin, senkaltaisen kuin se entinenkin oli ollut,"],[4,48,"Ja rakensivat pyhän huoneen jälleen, ja istuimet ja pappein olinsiat huoneissa.","Ja rakensivat pyhän huoneen jälleen, ja istuimet ja pappein olinsiat huoneissa."],[4,49,"Ja antoivat uudet pyhät astiat tehdä, kultaisen kynttiläjalan, suitsutusalttarin ja pöydän. ja veivät ne jälleen templiin.","Ja antoivat uudet pyhät astiat tehdä, kultaisen kynttiläjalan, suitsutusalttarin ja pöydän. ja veivät ne jälleen templiin."],[4,50,"Ja panivat savukaluin alttarille, ja sytyttivät lamput kynttiläjalassa valistamaan templissä;","Ja panivat savukaluin alttarille, ja sytyttivät lamput kynttiläjalassa valistamaan templissä;"],[4,51,"Panivat leivät pöydälle, ja ripustivat ylös esiripun, ja toimittivat templin kauniisti jälleen.","Panivat leivät pöydälle, ja ripustivat ylös esiripun, ja toimittivat templin kauniisti jälleen."],[4,52,"Ja viidentenä päivänä kolmattakymmentä yhdeksännessä kuukaudessa, joka kutsutaan Kasleu, kahdeksantena vuotena viidettäkymmentä toista sataa.","Ja viidentenä päivänä kolmattakymmentä yhdeksännessä kuukaudessa, joka kutsutaan Kasleu, kahdeksantena vuotena viidettäkymmentä toista sataa."],[4,53,"Nousivat he varhain ylös ja uhrasivat lain jälkeen polttouhrin alttarilla.","Nousivat he varhain ylös ja uhrasivat lain jälkeen polttouhrin alttarilla."],[4,54,"Tämä oli ensimmäinen uhri, sittekuin pakanat pyhän saastuttaneet olivat, ja tämä uhri uudistettiiu veisuilla, huiluilla, kanteleilla ja symbaleilla.","Tämä oli ensimmäinen uhri, sittekuin pakanat pyhän saastuttaneet olivat, ja tämä uhri uudistettiiu veisuilla, huiluilla, kanteleilla ja symbaleilla."],[4,55,"Ja kaikki kansa lankesi kasvoillensa, rukoilivat ja kiittivät Herraa taivaasta, joka heille onnen ja voiton antanut oli.","Ja kaikki kansa lankesi kasvoillensa, rukoilivat ja kiittivät Herraa taivaasta, joka heille onnen ja voiton antanut oli."],[4,56,"Ja pitivät uuden alttarin juhlaa kahdeksan päivää, ja uhrasivat sen päällä polttouhria ja kiitosuhria ilolla.","Ja pitivät uuden alttarin juhlaa kahdeksan päivää, ja uhrasivat sen päällä polttouhria ja kiitosuhria ilolla."],[4,57,"Ja kaunistivat templin kultaisilla seppeleillä ja kilvillä, ja tekivät uudet portit ja asuinhuoneet.","Ja kaunistivat templin kultaisilla seppeleillä ja kilvillä, ja tekivät uudet portit ja asuinhuoneet."],[4,58,"Ja suuri ilo oli kansan seassa, että se häpiä heiltä otettiin pois, jonka pakanat olivat saattaneet heidän päällensä.","Ja suuri ilo oli kansan seassa, että se häpiä heiltä otettiin pois, jonka pakanat olivat saattaneet heidän päällensä."],[4,59,"Ja Juudas ja hänen veljensä, ja kaikki Israelin kansa asettivat joka vuosi pidettää viidennestä päivästä kolmattakymmentä Kasleyn kuulla, kahdeksan päivää, sen uuden alttarin juhlaa ilolla ja kiitoksella.","Ja Juudas ja hänen veljensä, ja kaikki Israelin kansa asettivat joka vuosi pidettää viidennestä päivästä kolmattakymmentä Kasleyn kuulla, kahdeksan päivää, sen uuden alttarin juhlaa ilolla ja kiitoksella."],[4,60,"Ja he rakensivat lujat muurit ja tornit templin ympäri Zionin vuorelle, ettei pakanat olisi taitaneet saada ja hävittää pyhää, niinkuin ennen.","Ja he rakensivat lujat muurit ja tornit templin ympäri Zionin vuorelle, ettei pakanat olisi taitaneet saada ja hävittää pyhää, niinkuin ennen."],[4,61,"Ja Juudas pani sotaväkeä varjelemaan pyhää; hän vahvisti myös Betsuran, että kansalla olis linna Idumeaa vastaan, jossa he olisivat taitaneet varjella itsensä.","Ja Juudas pani sotaväkeä varjelemaan pyhää; hän vahvisti myös Betsuran, että kansalla olis linna Idumeaa vastaan, jossa he olisivat taitaneet varjella itsensä."],[5,1,"Mutta kuin pakanat ympäristöllä kuulivat, että alttari oli jälleen pantu ylös ja pyhä puhdistettu, julmistuivat he sangen kovin,","Mutta kuin pakanat ympäristöllä kuulivat, että alttari oli jälleen pantu ylös ja pyhä puhdistettu, julmistuivat he sangen kovin,"],[5,2,"Ja ajattelivat, kuinka he voisivat hävittää koko Jakobin sukukunnan, ja rupesivat tappamaan kaikkia Juudalaisia heidän rajoissansa.","Ja ajattelivat, kuinka he voisivat hävittää koko Jakobin sukukunnan, ja rupesivat tappamaan kaikkia Juudalaisia heidän rajoissansa."],[5,3,"Mutta Juudas vaelsi Idumeaan Esaun lapsia vastaan, ja hyökkäsi heidän päällensä Arabatissa, kussa he Israelin lapset piirittäneet olivat, ja löi monta Idumealaista kuoliaaksi, Ja otti heidän kalunsa pois.","Mutta Juudas vaelsi Idumeaan Esaun lapsia vastaan, ja hyökkäsi heidän päällensä Arabatissa, kussa he Israelin lapset piirittäneet olivat, ja löi monta Idumealaista kuoliaaksi, Ja otti heidän kalunsa pois."],[5,4,"Ja että myös Beanin lapset olivat tiellä pettäneet ja murhanneet Israelin lapsia,","Ja että myös Beanin lapset olivat tiellä pettäneet ja murhanneet Israelin lapsia,"],[5,5,"Ajatteli Juudas myös sitä, ja peräti hukutti heidät, ja poltti heidän linnansa, kaikkein niiden kanssa, jotka siinä olivat.","Ajatteli Juudas myös sitä, ja peräti hukutti heidät, ja poltti heidän linnansa, kaikkein niiden kanssa, jotka siinä olivat."],[5,6,"Senjälkeen vaelsi hän Ammonin lapsia vastaan, jotka hyvin varustetut olivat ja heillä oli paljo sotaväkeä, ja heidän päämiehensä oli Timoteus.","Senjälkeen vaelsi hän Ammonin lapsia vastaan, jotka hyvin varustetut olivat ja heillä oli paljo sotaväkeä, ja heidän päämiehensä oli Timoteus."],[5,7,"Ja Juudas piti heidän kanssansa monta sotaa ja sai voiton,","Ja Juudas piti heidän kanssansa monta sotaa ja sai voiton,"],[5,8,"Ja voitti Jatserin kaupungin ja muut ympäriolevaiset kylät, ja palasi Juudeaan jälleen.","Ja voitti Jatserin kaupungin ja muut ympäriolevaiset kylät, ja palasi Juudeaan jälleen."],[5,9,"Mutta pakanat Galaadissa hankitsivat myös Israelia vastaan rajoissansa, heitä surettamaan.","Mutta pakanat Galaadissa hankitsivat myös Israelia vastaan rajoissansa, heitä surettamaan."],[5,10,"Vaan kansa pakeni Dateman linnaan, ja kirjoittivat Juudaan ja hänen veljeinsä tykö näin:","Vaan kansa pakeni Dateman linnaan, ja kirjoittivat Juudaan ja hänen veljeinsä tykö näin:"],[5,11,"Kaikki pakanat tässä ympäristöllä ovat kokoontuneet meitä vastaan, meitä kaikkia hävittämään, ja heidän päämiehensä on Timoteus: nämät tahtovat tulla väkirynnäköllä linnaamme, johonka me olemme paenneet:","Kaikki pakanat tässä ympäristöllä ovat kokoontuneet meitä vastaan, meitä kaikkia hävittämään, ja heidän päämiehensä on Timoteus: nämät tahtovat tulla väkirynnäköllä linnaamme, johonka me olemme paenneet:"],[5,12,"Sen tähden me rukoilemme, että sinä tulisit meille avuksi varjelemaan meitä; meitä on vähä, sillä viholliset ovat monta maahan lyöneet,","Sen tähden me rukoilemme, että sinä tulisit meille avuksi varjelemaan meitä; meitä on vähä, sillä viholliset ovat monta maahan lyöneet,"],[5,13,"Ja Tubissa tappaneet liki tuhannen miestä, ja vieneet pois heidän vaimonsa, lapsensa ja tavaransa.","Ja Tubissa tappaneet liki tuhannen miestä, ja vieneet pois heidän vaimonsa, lapsensa ja tavaransa."],[5,14,"Kuin tätä kirjaa luettiin, tulivat toiset sanansaattajat Galileasta reväistyilIä vaatteilla, surkuttelivat,","Kuin tätä kirjaa luettiin, tulivat toiset sanansaattajat Galileasta reväistyilIä vaatteilla, surkuttelivat,"],[5,15,"Ja sanoivat, että pakanat kaikista kaupungeista siinä ympäri Ptolomaista, Tyrosta ja Sidonista, ovat vaeltaneet suurella voimalla Galilean lävitse ja että koko Galilea oli täynnä vihollisia, jotka tulleet olivat Israelia hävittämään.","Ja sanoivat, että pakanat kaikista kaupungeista siinä ympäri Ptolomaista, Tyrosta ja Sidonista, ovat vaeltaneet suurella voimalla Galilean lävitse ja että koko Galilea oli täynnä vihollisia, jotka tulleet olivat Israelia hävittämään."],[5,16,"Kuin Juudas ja kansa tämän kuulivat, pitivät he neuvoa, kuinka he olisivat voineet auttaa veijiänsä tässä vaivassa.","Kuin Juudas ja kansa tämän kuulivat, pitivät he neuvoa, kuinka he olisivat voineet auttaa veijiänsä tässä vaivassa."],[5,17,"Ja Juudas käski veljensä Simonin valita itsellensä erinomaisen väen ja mennä Galileaan, auttamaan veljiänsä, ja itse tahtoi hän veljensä Jonatanin kanssa matkustaa Galaadiin,","Ja Juudas käski veljensä Simonin valita itsellensä erinomaisen väen ja mennä Galileaan, auttamaan veljiänsä, ja itse tahtoi hän veljensä Jonatanin kanssa matkustaa Galaadiin,"],[5,18,"Ja teki Josephin, Sakarian pojan, ja Atsarian sen väen päämieheksi, joka kotia jäi varjelemaan Juudaa.","Ja teki Josephin, Sakarian pojan, ja Atsarian sen väen päämieheksi, joka kotia jäi varjelemaan Juudaa."],[5,19,"Ja käski heidän hallita kansaa, ja kielsi lähtemästä vihollisia käsittelemään, siihenasti kuin hän olis tullut jälleen.","Ja käski heidän hallita kansaa, ja kielsi lähtemästä vihollisia käsittelemään, siihenasti kuin hän olis tullut jälleen."],[5,20,"Ja Simon vaelsi Galileaan kolmellatuhannella miehellä, ja Juudas Galaadiin kahdeksallatuhannella.","Ja Simon vaelsi Galileaan kolmellatuhannella miehellä, ja Juudas Galaadiin kahdeksallatuhannella."],[5,21,"Kuin Simon tuli Galileaan, tappeli hän monasti pakanain kanssa, ja voitti ja ajoi heitä takaa hamaan Ptolomain portin eteen,","Kuin Simon tuli Galileaan, tappeli hän monasti pakanain kanssa, ja voitti ja ajoi heitä takaa hamaan Ptolomain portin eteen,"],[5,22,"Niin että liki kolmetuhatta pakanaa tapettiin, ja Simon otti heidän tavaransa.","Niin että liki kolmetuhatta pakanaa tapettiin, ja Simon otti heidän tavaransa."],[5,23,"Sitte tuli hän jälleen veljeinsä tykö Galileaan ja Arabatiin, ja käski heidät vaimoinensa ja lapsinensa matkustaa hänen kanssansa Juudeaan, ja vei heidät sinne suurella ilolla.","Sitte tuli hän jälleen veljeinsä tykö Galileaan ja Arabatiin, ja käski heidät vaimoinensa ja lapsinensa matkustaa hänen kanssansa Juudeaan, ja vei heidät sinne suurella ilolla."],[5,24,"Mutta Juudas Makkabealainen ja Jonatan hänen veljensä matkustivat Jordanin ylitse erämaahan, kolmen päiväkunnan matkan.","Mutta Juudas Makkabealainen ja Jonatan hänen veljensä matkustivat Jordanin ylitse erämaahan, kolmen päiväkunnan matkan."],[5,25,"SilIoln tullvat heidän tykönsä Nabatealaiset, ja ottivat heidät ystävällisesti vastaan, ja juttelivat heille, kuinka heidän veljillensä Galaadissa kävi,","SilIoln tullvat heidän tykönsä Nabatealaiset, ja ottivat heidät ystävällisesti vastaan, ja juttelivat heille, kuinka heidän veljillensä Galaadissa kävi,"],[5,26,"Ja että monta oli viety vankina pois Barasaan, Bosoriin, Alimaan, Kasboon, Magethiin ja Karnaimiin, jotka kaikki olivat suuret ja lujat kaupungit, että myös monta niissä muissa Galaadin kaupungeissa vankina olivat.","Ja että monta oli viety vankina pois Barasaan, Bosoriin, Alimaan, Kasboon, Magethiin ja Karnaimiin, jotka kaikki olivat suuret ja lujat kaupungit, että myös monta niissä muissa Galaadin kaupungeissa vankina olivat."],[5,27,"Sentähden he päättivät, että he kohta huomeneltain sen jälkeen tahtoivat matkustaa vahvoja kaupungeita vastaan, niitä väkisin ottamaan.","Sentähden he päättivät, että he kohta huomeneltain sen jälkeen tahtoivat matkustaa vahvoja kaupungeita vastaan, niitä väkisin ottamaan."],[5,28,"Ja Juudas palasi päiväkunnan matkan takaperin, ja meni Bosorin kaupungin päälle, ennenkuin he taisivat pitää vaarinsa, ja sai sen väkisin ja antoi siinä tappaa kaiken miehenpuolen, ja otti heidän tavaransa, ja poltti kaupungin.","Ja Juudas palasi päiväkunnan matkan takaperin, ja meni Bosorin kaupungin päälle, ennenkuin he taisivat pitää vaarinsa, ja sai sen väkisin ja antoi siinä tappaa kaiken miehenpuolen, ja otti heidän tavaransa, ja poltti kaupungin."],[5,29,"Senjälkeen meni hän kohta yöllä linnaan, johon hänen veljensä ahdistetut olivat.","Senjälkeen meni hän kohta yöllä linnaan, johon hänen veljensä ahdistetut olivat."],[5,30,"Ja kuin hän huomeneltain sinne tuli, näki hän siellä sangen suuren joukon väkeä, joiden lukua ei tiedetty, jotka tikapuita ja sota-aseita kantoivat, ja rupesivat rintarynnäköllä hyökkäämään sisälle.","Ja kuin hän huomeneltain sinne tuli, näki hän siellä sangen suuren joukon väkeä, joiden lukua ei tiedetty, jotka tikapuita ja sota-aseita kantoivat, ja rupesivat rintarynnäköllä hyökkäämään sisälle."],[5,31,"Ja kaupungissa oli surkia huuto, niin että se kajahti ylös taivaasen.","Ja kaupungissa oli surkia huuto, niin että se kajahti ylös taivaasen."],[5,32,"Silloin neuvoi Juudas väkensä sotimaan veljeinsä edestä ja auttamaan heitä,","Silloin neuvoi Juudas väkensä sotimaan veljeinsä edestä ja auttamaan heitä,"],[5,33,"Ja teki kolme joukkoa, ja löi takaa heidän päällensä, ja antoi vaskitorvet soida, vaan kansa, huusi korkiasti ja rukoili Jumalaa.","Ja teki kolme joukkoa, ja löi takaa heidän päällensä, ja antoi vaskitorvet soida, vaan kansa, huusi korkiasti ja rukoili Jumalaa."],[5,34,"Mutta kuin Timoteuksen sotajoukko näki, että Juudas oli heidän takanansa, pakenivat he, ja lyötiin kovin, niin että heistä kuo- li sinä päivänä liki kahdeksantuhatta.","Mutta kuin Timoteuksen sotajoukko näki, että Juudas oli heidän takanansa, pakenivat he, ja lyötiin kovin, niin että heistä kuo- li sinä päivänä liki kahdeksantuhatta."],[5,35,"Sitte matkusti Juudas Matsphaan ja kävi sen päälle väkirynnäköllä ja voitti sen, ja antoi myös siinä tappaa kaikki miehenpuolen, otti tavaran, ja poltti kaupungin.","Sitte matkusti Juudas Matsphaan ja kävi sen päälle väkirynnäköllä ja voitti sen, ja antoi myös siinä tappaa kaikki miehenpuolen, otti tavaran, ja poltti kaupungin."],[5,36,"Sitte voitti hän Kasbonin, Magetin, Bosorin ja muut kaupungit Galaadissa.","Sitte voitti hän Kasbonin, Magetin, Bosorin ja muut kaupungit Galaadissa."],[5,37,"Mutta Timoteus kokosi taas suuren joukon, ja sioitti itsensä Raphouin kohdalle sillä puolella ojaa.","Mutta Timoteus kokosi taas suuren joukon, ja sioitti itsensä Raphouin kohdalle sillä puolella ojaa."],[5,38,"Niin lähetti Juudas miehet sinne tutkimaan ja katsomaan, kuinka vahva vihollinen oli, ja kuinka he makasivat.","Niin lähetti Juudas miehet sinne tutkimaan ja katsomaan, kuinka vahva vihollinen oli, ja kuinka he makasivat."],[5,39,"Nämät toivat hänelle tiedon, että se oli sangen suuri joukko kaikista pakanoista ympäristöltä, ja heillä oli myös palkkaväkeä Arabiasta, ja tämä väki makasi toisella puolella ojaa, ja olivat varustetut tappelemaan; sentähden meni Juudas ylös heitä vastaan.","Nämät toivat hänelle tiedon, että se oli sangen suuri joukko kaikista pakanoista ympäristöltä, ja heillä oli myös palkkaväkeä Arabiasta, ja tämä väki makasi toisella puolella ojaa, ja olivat varustetut tappelemaan; sentähden meni Juudas ylös heitä vastaan."],[5,40,"Ja Timoteus sanoi päämiehillensä: jos Juudas tulee ojan tykö, ja on niin rohkia, että hän ehtii tänne tulla ylitse, niin emme voi olla häntä vastaan, vaan hän lyö meidät.","Ja Timoteus sanoi päämiehillensä: jos Juudas tulee ojan tykö, ja on niin rohkia, että hän ehtii tänne tulla ylitse, niin emme voi olla häntä vastaan, vaan hän lyö meidät."],[5,41,"Mutta jos hän pelkää, ja ei uskalla tänne ojan ylitse, niin me tahdomme veden ylitse hänen tykönsä, hyökätä hänen päällensä, ja lyömme hänen.","Mutta jos hän pelkää, ja ei uskalla tänne ojan ylitse, niin me tahdomme veden ylitse hänen tykönsä, hyökätä hänen päällensä, ja lyömme hänen."],[5,42,"Kuin Juudas tuli ojan tykö, asetti hän papit rantaan, ja antoi heille käskyn kaikkea väkeä vaatimaan, ettei yksikään olisi jäänyt, vaan olleet avulliset lyömään vihollisia.","Kuin Juudas tuli ojan tykö, asetti hän papit rantaan, ja antoi heille käskyn kaikkea väkeä vaatimaan, ettei yksikään olisi jäänyt, vaan olleet avulliset lyömään vihollisia."],[5,43,"Kuin Juudas tuli joukkoinensa veden ylitse, pakenivat viholliset, ja pudottivat aseensa maahan, tulivat yhteen templiin Karnaimin kaupungissa.","Kuin Juudas tuli joukkoinensa veden ylitse, pakenivat viholliset, ja pudottivat aseensa maahan, tulivat yhteen templiin Karnaimin kaupungissa."],[5,44,"Mutta Juudas sai kaupungin, ja poltti templin ja kaikki ne, jotka siinä olivat. Näin Karnaim kukistettiin, ja ei voinut itsiänsä varjella Juudaa vastaan.","Mutta Juudas sai kaupungin, ja poltti templin ja kaikki ne, jotka siinä olivat. Näin Karnaim kukistettiin, ja ei voinut itsiänsä varjella Juudaa vastaan."],[5,45,"Sitte antoi Juudas tulla kokoon kaiken Israelin kansan kuin Galaadissa oli, pienet ja suuret, vaimot ja lapset, menemään kanssansa Juudeaan.","Sitte antoi Juudas tulla kokoon kaiken Israelin kansan kuin Galaadissa oli, pienet ja suuret, vaimot ja lapset, menemään kanssansa Juudeaan."],[5,46,"Ja matkallansa tulivat he yhden suuren vahvan kaupungin tykö, Ephron nimeltä, joka oli valtamaantiessä, jonka ympäri ei saatu mennä, vaan heidän piti vaeltaman sen lävitse.","Ja matkallansa tulivat he yhden suuren vahvan kaupungin tykö, Ephron nimeltä, joka oli valtamaantiessä, jonka ympäri ei saatu mennä, vaan heidän piti vaeltaman sen lävitse."],[5,47,"Ja ne Ephronista ei tahtoneet päästää Juudaa sen lävitse,","Ja ne Ephronista ei tahtoneet päästää Juudaa sen lävitse,"],[5,48,"Vaan olivat kaupungissa, ja pitivät portit kiinni.","Vaan olivat kaupungissa, ja pitivät portit kiinni."],[5,49,"Mutta Juudas lähetti heidän tykönsä, sanoi heille rauhan, ja rukoili ystävällisesti,","Mutta Juudas lähetti heidän tykönsä, sanoi heille rauhan, ja rukoili ystävällisesti,"],[5,50,"Että he olisivat heidät laskeneet lävitse, niin ei heille pitänyt yhtään vahinkoa tapahtuman hänen kansaltansa; ei hän mitään muuta anonut, vaan ainoastaan vaeltaa lävitse; mutta ne Ephronissa ei tahtoneet heitä päästää sisälle.","Että he olisivat heidät laskeneet lävitse, niin ei heille pitänyt yhtään vahinkoa tapahtuman hänen kansaltansa; ei hän mitään muuta anonut, vaan ainoastaan vaeltaa lävitse; mutta ne Ephronissa ei tahtoneet heitä päästää sisälle."],[5,51,"Niin Juudas kuulutti ja sanoi kaikelle sotaväelle, että itsekukin heistä piti astuman siallensa, ja hyökkäämän väkirynnäköllä kaupunkiin, kukin joukko paikastansa; ja niin he tekivät koko sen päivän ja kaiken sen yön, ja voittivat kaupungin.","Niin Juudas kuulutti ja sanoi kaikelle sotaväelle, että itsekukin heistä piti astuman siallensa, ja hyökkäämän väkirynnäköllä kaupunkiin, kukin joukko paikastansa; ja niin he tekivät koko sen päivän ja kaiken sen yön, ja voittivat kaupungin."],[5,52,"Ja Juudas antoi siinä tappaa kaiken miehenpuolen, otti heidän tavaransa, ja kukisti kaupungin ja vaelsi sen lävitse kuolleiden ruumisten ylitse, ja he tulivat Jordanin ylitse tasaiselle kedolle.","Ja Juudas antoi siinä tappaa kaiken miehenpuolen, otti heidän tavaransa, ja kukisti kaupungin ja vaelsi sen lävitse kuolleiden ruumisten ylitse, ja he tulivat Jordanin ylitse tasaiselle kedolle."],[5,53,"Ja Juudas vaati kansan, joka perässä oli, joutumaan, ja lohdutti heitä kaiken sen matkan siihen asti, kuin hän vei heidät Juudan maahan.","Ja Juudas vaati kansan, joka perässä oli, joutumaan, ja lohdutti heitä kaiken sen matkan siihen asti, kuin hän vei heidät Juudan maahan."],[5,54,"Silloin menivät he ylös Zionin vuorelle suurella ilolla, ja uhrasivat polttouhrin, että Jumala oli heille voiton antanut, ja saattanut heitä ilolla kotiansa jälleen.","Silloin menivät he ylös Zionin vuorelle suurella ilolla, ja uhrasivat polttouhrin, että Jumala oli heille voiton antanut, ja saattanut heitä ilolla kotiansa jälleen."],[5,55,"Mutta kuin Juudas ja Jonatan vielä Galaadissa olivat, ja Simon heidän veljensä, Galileassa Ptolemain edessä;","Mutta kuin Juudas ja Jonatan vielä Galaadissa olivat, ja Simon heidän veljensä, Galileassa Ptolemain edessä;"],[5,56,"Ja Joseph Sakarian poika ja Atsaria, päämiehet, kuulivat heidän voitostansa ja suurista töistänsä, sanoivat he:","Ja Joseph Sakarian poika ja Atsaria, päämiehet, kuulivat heidän voitostansa ja suurista töistänsä, sanoivat he:"],[5,57,"Me tahdomme myös voittaa kunnian, ja lyödä pakanoita, jotka tässä ympäri asnvat!","Me tahdomme myös voittaa kunnian, ja lyödä pakanoita, jotka tässä ympäri asnvat!"],[5,58,"Ja antoivat käskyn sotaväellensä, että heidän piti nouseman, ja matkustivat Jamniaan.","Ja antoivat käskyn sotaväellensä, että heidän piti nouseman, ja matkustivat Jamniaan."],[5,59,"Niin Gorgias kävi ulos heitä vastaan sotaväkinensä,","Niin Gorgias kävi ulos heitä vastaan sotaväkinensä,"],[5,60,"Ja löi Josephin ja Atsarian pakoon, ja ajoi heitä takaa hamaan Juudan maalle. Ja Israelista tuli pois sinä päivänä paljo väkeä, liki kaksituhatta miestä,","Ja löi Josephin ja Atsarian pakoon, ja ajoi heitä takaa hamaan Juudan maalle. Ja Israelista tuli pois sinä päivänä paljo väkeä, liki kaksituhatta miestä,"],[5,61,"Ettei he Juudaan ja hänen veljeinsä käskyä totelleet, ja olivat sen tehneet omasta röyhkeydestänsä, voittaaksensa kunniaa;","Ettei he Juudaan ja hänen veljeinsä käskyä totelleet, ja olivat sen tehneet omasta röyhkeydestänsä, voittaaksensa kunniaa;"],[5,62,"Ehkei he olleet ne miehet, jotka Jumalalta suodut olivat, että Israel heidän kauttansa piti autetuksi tuleman.","Ehkei he olleet ne miehet, jotka Jumalalta suodut olivat, että Israel heidän kauttansa piti autetuksi tuleman."],[5,63,"Mutta Juudaasta ja hänen veljistänsä pidettiin paljon koko Israelissa, ja kaikkein pakanain seassa.","Mutta Juudaasta ja hänen veljistänsä pidettiin paljon koko Israelissa, ja kaikkein pakanain seassa."],[5,64,"Ja kussa heidän nimensä mainittiin, siinä he ylistettiin.","Ja kussa heidän nimensä mainittiin, siinä he ylistettiin."],[5,65,"Ja Juudas meni ulos veljiensä Esaun lapsia vastaan lounaan päin, ja voitti Hebronin ja le kylät ympäristöltä, ja poltti hänen muurinsa ja torninsa.","Ja Juudas meni ulos veljiensä Esaun lapsia vastaan lounaan päin, ja voitti Hebronin ja le kylät ympäristöltä, ja poltti hänen muurinsa ja torninsa."],[5,66,"Ja palasi jälleen pakanain maalle Samariaan,","Ja palasi jälleen pakanain maalle Samariaan,"],[5,67,"Jossa oli monta pappia tapettu, jotka myös röyhkeät olivat olleet ja käsitelleet pakanoita neuvomatta ja ilman käskyä.","Jossa oli monta pappia tapettu, jotka myös röyhkeät olivat olleet ja käsitelleet pakanoita neuvomatta ja ilman käskyä."],[5,68,"Sitte vaelsi Juudas Asdodiin, pakanain maalle, ja epäjumalain alttarit kukisti, ja poltti epäjumalat, ja otti saaliin kaupungeista, ja tuli jälleen kotiansa Juudan maalle.","Sitte vaelsi Juudas Asdodiin, pakanain maalle, ja epäjumalain alttarit kukisti, ja poltti epäjumalat, ja otti saaliin kaupungeista, ja tuli jälleen kotiansa Juudan maalle."],[6,1,"Antiokus Epiphaneksen kuoltua, tulee hänen poikansa Antiokus Eupator hänen siaansa. Mutta kuin kuningas Antiokus vaelsi sinne ja tänne ylimmäisessä valtakunnassa, sanottiin hänelle siitä kuuluisasta kaupungista Elimadista, joka oli Persian maakunnassa, että siinä oli paljo kultaa ja hopiaa ja suuret rikkaudet,","Antiokus Epiphaneksen kuoltua, tulee hänen poikansa Antiokus Eupator hänen siaansa. Mutta kuin kuningas Antiokus vaelsi sinne ja tänne ylimmäisessä valtakunnassa, sanottiin hänelle siitä kuuluisasta kaupungista Elimadista, joka oli Persian maakunnassa, että siinä oli paljo kultaa ja hopiaa ja suuret rikkaudet,"],[6,2,"Ja että templissä olivat suuret tavarat ja kultaiset vaatteet, haarniskat ja kilvet, jotka Philippuksen poika, kuningas Aleksander Makedoniasta, siihen antanut oli.","Ja että templissä olivat suuret tavarat ja kultaiset vaatteet, haarniskat ja kilvet, jotka Philippuksen poika, kuningas Aleksander Makedoniasta, siihen antanut oli."],[6,3,"Tuli sentähden Antiokus sen kaupungin alle, saamaan ja ryöstämään sitä; mutta ne, jotka kaupungissa olivat varustetut:","Tuli sentähden Antiokus sen kaupungin alle, saamaan ja ryöstämään sitä; mutta ne, jotka kaupungissa olivat varustetut:"],[6,4,"Sen tähden olivat he valmiit varjelemaan itseänsä. Ja ei Antiokus taitanut mitään toimittaa, vaan täytyi palata jälleen tietänsä myöten Babeliin päin suurella murheella.","Sen tähden olivat he valmiit varjelemaan itseänsä. Ja ei Antiokus taitanut mitään toimittaa, vaan täytyi palata jälleen tietänsä myöten Babeliin päin suurella murheella."],[6,5,"Silloin sai hän sanoman, että hänen sotaväkensä, jonka hän Juudan maalle lähettänyt oli, lyöty oli, ja Lysiaan oli täytynyt paeta,","Silloin sai hän sanoman, että hänen sotaväkensä, jonka hän Juudan maalle lähettänyt oli, lyöty oli, ja Lysiaan oli täytynyt paeta,"],[6,6,"Ja että Juudalaiset olivat voittaneet hänen leiristänsä suuret tavarat ja paljon sota-aseita, joilla he sitte olivat itsensä paremmin varustaneet, ja tulleet voimallisemmaksi","Ja että Juudalaiset olivat voittaneet hänen leiristänsä suuret tavarat ja paljon sota-aseita, joilla he sitte olivat itsensä paremmin varustaneet, ja tulleet voimallisemmaksi"],[6,7,"Ja olivat heittäneet ulos kauhistuksen Jerusalemin templistä, ja vahvistaneet pyhän jälleen vahvalla muurilla niinkuin ennenkin, ja myös vahvistaneet Betsuran.","Ja olivat heittäneet ulos kauhistuksen Jerusalemin templistä, ja vahvistaneet pyhän jälleen vahvalla muurilla niinkuin ennenkin, ja myös vahvistaneet Betsuran."],[6,8,"Kuin Antiokns tämän puheen kuuli, hämmästyi hän sangen suuresti, ja tuli ylönpalttisesti murheelliseksi, ja laski itsensä vuoteelle, ja tuli murheesta sairaaksi, ettei hänen aikomuksensa menestynyt,","Kuin Antiokns tämän puheen kuuli, hämmästyi hän sangen suuresti, ja tuli ylönpalttisesti murheelliseksi, ja laski itsensä vuoteelle, ja tuli murheesta sairaaksi, ettei hänen aikomuksensa menestynyt,"],[6,9,"Ja viipyi kauvan siinä kaupungissa; sillä murhe, jota pitemmältä, sitä raskaampi se oli hänelle, ja teki hänen niin heikoksi, että hän ymmärsi sen kautta kuolevansa.","Ja viipyi kauvan siinä kaupungissa; sillä murhe, jota pitemmältä, sitä raskaampi se oli hänelle, ja teki hänen niin heikoksi, että hän ymmärsi sen kautta kuolevansa."],[6,10,"Sentähden kutsui hän ystävänsä tykönsä, ja sanoi heille: en minä taida enään unta saada suuren murheen ja sydämen surun tähden, joka minulla on.","Sentähden kutsui hän ystävänsä tykönsä, ja sanoi heille: en minä taida enään unta saada suuren murheen ja sydämen surun tähden, joka minulla on."],[6,11,"Voi kuinka kaikki minun menoni toisin päin kääntynyt on! Niinkauvan kuin minä olen hallinnut, on minulla ilo ja voitto ollut, ja olen minun omiltani rakastettu ja suurena pidetty.","Voi kuinka kaikki minun menoni toisin päin kääntynyt on! Niinkauvan kuin minä olen hallinnut, on minulla ilo ja voitto ollut, ja olen minun omiltani rakastettu ja suurena pidetty."],[6,12,"Mutta nyt olen minä niin sydämestä murheellinen, ja minun mieleeni johtuu se paha, jonka minä Jerusalemissa tehnyt olen, kuin minä kaikki kulta. ja hopia-astiat templistä vein pois, ja annoin tappaa viattomat ihmiset Juudeassa.","Mutta nyt olen minä niin sydämestä murheellinen, ja minun mieleeni johtuu se paha, jonka minä Jerusalemissa tehnyt olen, kuin minä kaikki kulta. ja hopia-astiat templistä vein pois, ja annoin tappaa viattomat ihmiset Juudeassa."],[6,13,"Siitä tulee nyt minulle kaikki tämä onnettomuus, ja täytyy vieraalla maalla tässä surussa kuolla.","Siitä tulee nyt minulle kaikki tämä onnettomuus, ja täytyy vieraalla maalla tässä surussa kuolla."],[6,14,"Ja hän kutsui ystävänsä Philippuksen, sen hän asetti koko valtakunnan päämieheksi,","Ja hän kutsui ystävänsä Philippuksen, sen hän asetti koko valtakunnan päämieheksi,"],[6,15,"Ja antoi hänelle kruunun, kaapun ja sormuksen, ja käski hänen kasvattaa hänen poikansa nuoren Antiokuksen ja asettaa valtakuntaan.","Ja antoi hänelle kruunun, kaapun ja sormuksen, ja käski hänen kasvattaa hänen poikansa nuoren Antiokuksen ja asettaa valtakuntaan."],[6,16,"Ja niin Antiokus kuoli siinä kaupungissa, yhdeksäntenä ajastaikana viidettäkymmentä toistasataa.","Ja niin Antiokus kuoli siinä kaupungissa, yhdeksäntenä ajastaikana viidettäkymmentä toistasataa."],[6,17,"Kuin Lysias kuuli, että kuningas kuollut oli, teki hän Antiokus Epiphaneksen pojan kuninkaaksi, nuoren Antiokuksen, jonka opetusisä hän oli ollut, ja nimitti hänen Eupatoriksi.","Kuin Lysias kuuli, että kuningas kuollut oli, teki hän Antiokus Epiphaneksen pojan kuninkaaksi, nuoren Antiokuksen, jonka opetusisä hän oli ollut, ja nimitti hänen Eupatoriksi."],[6,18,"Ja pakanat, joiden hallussa Zionin linna vielä oli, tekivät Israelin kansalle paljon vahinkoa pyhässä; sillä heillä oli hyvä luja linna.","Ja pakanat, joiden hallussa Zionin linna vielä oli, tekivät Israelin kansalle paljon vahinkoa pyhässä; sillä heillä oli hyvä luja linna."],[6,19,"Sentähden ajatteli Juudas ahdistaa heitä, että hän olis heidät surettanut.","Sentähden ajatteli Juudas ahdistaa heitä, että hän olis heidät surettanut."],[6,20,"Ja kansa tuli kokoon viidentenäkymmenentenä vuotena toista sataa, ja toi sen eteen kaikkinaisia sota-aseita.","Ja kansa tuli kokoon viidentenäkymmenentenä vuotena toista sataa, ja toi sen eteen kaikkinaisia sota-aseita."],[6,21,"Ja muutamat pakanoista läksivät ulos linnasta menemään kuninkaan tykö apua anomaan. Heidän seuraansa antoivat itsensä monta, jotka Israelista luopuneet olivat, ja menivät heidän kanssansa kuninkaan tykö, ja sanoivat:","Ja muutamat pakanoista läksivät ulos linnasta menemään kuninkaan tykö apua anomaan. Heidän seuraansa antoivat itsensä monta, jotka Israelista luopuneet olivat, ja menivät heidän kanssansa kuninkaan tykö, ja sanoivat:"],[6,22,"Miksi et tahdo rangaista, ja meidän veljeimme tähden kostaa?","Miksi et tahdo rangaista, ja meidän veljeimme tähden kostaa?"],[6,23,"Sillä me tahdoimme olla sinun isälles alamaiset ja hänen käskyllensä kuuliaiset;","Sillä me tahdoimme olla sinun isälles alamaiset ja hänen käskyllensä kuuliaiset;"],[6,24,"Sentähden meidän kansa luopui meistä, ja kussa he saivat meistä jonkun kiinni, niin he tappoivat sen, ja jakoivat meidän perimisemme keskenänsä.","Sentähden meidän kansa luopui meistä, ja kussa he saivat meistä jonkun kiinni, niin he tappoivat sen, ja jakoivat meidän perimisemme keskenänsä."],[6,25,"Ja ei ainoastaan ole vaivanneet meitä, mutta senkaltaisia ovat he tehneet koko maakunnassa.","Ja ei ainoastaan ole vaivanneet meitä, mutta senkaltaisia ovat he tehneet koko maakunnassa."],[6,26,"Ja nyt ahdistavat linnan Jerusalemissa, ottaaksensa sitä, ja ovat vahvaksi rakentaneet pyhän ja Betsuran.","Ja nyt ahdistavat linnan Jerusalemissa, ottaaksensa sitä, ja ovat vahvaksi rakentaneet pyhän ja Betsuran."],[6,27,"Ellet sinä nyt riennä sinuas estämään heitä, niin he tulevat vahvemmiksi, ja tekevät enempi vahinkoa, ja et sinä taida sitte enään heitä hillitä.","Ellet sinä nyt riennä sinuas estämään heitä, niin he tulevat vahvemmiksi, ja tekevät enempi vahinkoa, ja et sinä taida sitte enään heitä hillitä."],[6,28,"Kuin kuningas senkaltaisia kuuli, julmistui hän sangen suuresti, ja antoi kutsua kokoon ruhtinaansa, ja jalkaväen ja hevosväen päämiehet,","Kuin kuningas senkaltaisia kuuli, julmistui hän sangen suuresti, ja antoi kutsua kokoon ruhtinaansa, ja jalkaväen ja hevosväen päämiehet,"],[6,29,"Ja otti muukalaista palkkaväkeä luotokunnista,","Ja otti muukalaista palkkaväkeä luotokunnista,"],[6,30,"Ja kokosi satatuhatta miestä jalkaväkeä, ja kaksikymmentä tuhatta ratsasmiestä, ja kaksineljättäkymmentä elephanttia, jotka sotaan olivat harjoitetut.","Ja kokosi satatuhatta miestä jalkaväkeä, ja kaksikymmentä tuhatta ratsasmiestä, ja kaksineljättäkymmentä elephanttia, jotka sotaan olivat harjoitetut."],[6,31,"Tämä sotaväki vaelsi Idumean lävitse; ja kuin he tulivat maalle, piirittivät he Betsuran, ja asettivat sen alle monenkaltaiset sodanneuvot, mennäksensä väkirynnäköllä sisälle. Mutta Juudalaiset tulivat ulos, ja polttivat ne rakennukset, ja sotivat miehuullisesti.","Tämä sotaväki vaelsi Idumean lävitse; ja kuin he tulivat maalle, piirittivät he Betsuran, ja asettivat sen alle monenkaltaiset sodanneuvot, mennäksensä väkirynnäköllä sisälle. Mutta Juudalaiset tulivat ulos, ja polttivat ne rakennukset, ja sotivat miehuullisesti."],[6,32,"Ja Juudas luopui Zionin linnasta, ja tuli sotaväen kanssa Betsakaraan kuninkaan leiriä vastaan.","Ja Juudas luopui Zionin linnasta, ja tuli sotaväen kanssa Betsakaraan kuninkaan leiriä vastaan."],[6,33,"Silloin oli kuningas huomeneltain varhain ylhäällä ennen päivää, ja johdatti sotaväen Betsakaran tielle, ja antoi asettaa rintasodan, ja vaskitorvea soittaa,","Silloin oli kuningas huomeneltain varhain ylhäällä ennen päivää, ja johdatti sotaväen Betsakaran tielle, ja antoi asettaa rintasodan, ja vaskitorvea soittaa,"],[6,34,"Ja priiskottaa elephantit punaisella viinalla ja morin marjan nesteellä, kehoittaaksensa heitä käymään edes ja vihastumaan;","Ja priiskottaa elephantit punaisella viinalla ja morin marjan nesteellä, kehoittaaksensa heitä käymään edes ja vihastumaan;"],[6,35,"Ja jakoi elephantit joukkoin keskelle, että kunkin elephantin tykö oli asetettu tuhannen jalkamiestä rautalakeilla ja haarniskoilla, ja viisisataa hevosmiestä.","Ja jakoi elephantit joukkoin keskelle, että kunkin elephantin tykö oli asetettu tuhannen jalkamiestä rautalakeilla ja haarniskoilla, ja viisisataa hevosmiestä."],[6,36,"Nämät ottivat vaarin elephantista niin ettei he välttäneet pois sen tyköä, ja kuhunka elephantti käännettiin, sinne myös heidän piti kääntymän.","Nämät ottivat vaarin elephantista niin ettei he välttäneet pois sen tyköä, ja kuhunka elephantti käännettiin, sinne myös heidän piti kääntymän."],[6,37,"Ja kukin elephantti kantoi selässänsä puutornia, jossa kaksi neljättäkymmentä sotamiestä oli, ja se mies, joka eläintä ajoi ja hallitsi.","Ja kukin elephantti kantoi selässänsä puutornia, jossa kaksi neljättäkymmentä sotamiestä oli, ja se mies, joka eläintä ajoi ja hallitsi."],[6,38,"Ne muut hevosmiehet asetti hän molemmille puolille estämään jalkaväkeä toinen toisestansa hajoamasta.","Ne muut hevosmiehet asetti hän molemmille puolille estämään jalkaväkeä toinen toisestansa hajoamasta."],[6,39,"Ja kuin aurinko koitti ja paisti kultaisten kilpien päälle, leimahti koko vuori siitä, niinkuin se kaikki olis ollut tuli.","Ja kuin aurinko koitti ja paisti kultaisten kilpien päälle, leimahti koko vuori siitä, niinkuin se kaikki olis ollut tuli."],[6,40,"Ja kuninkaan sotaväestä meni osa vuorelle ja osa alas lakialle kedolle visusti, hyvässä järjestyksessä.","Ja kuninkaan sotaväestä meni osa vuorelle ja osa alas lakialle kedolle visusti, hyvässä järjestyksessä."],[6,41,"Ja joka heidät kuuli, se peljästyi siitä hirmuisesta pauhinasta ja suuresta väen paljoudesta, ja siitä helinästä, jonka heidän haarniskansa ja rautansa antoivat; sillä se oli sangen suuri ja hyvin varustettu sotajoukko.","Ja joka heidät kuuli, se peljästyi siitä hirmuisesta pauhinasta ja suuresta väen paljoudesta, ja siitä helinästä, jonka heidän haarniskansa ja rautansa antoivat; sillä se oli sangen suuri ja hyvin varustettu sotajoukko."],[6,42,"Ja Juudas myös kävi edes joukkoinensa varjelemaan itsiänsä, ja löi kuusisataa kuoliaaksi kuninkaan väestä.","Ja Juudas myös kävi edes joukkoinensa varjelemaan itsiänsä, ja löi kuusisataa kuoliaaksi kuninkaan väestä."],[6,43,"Ja Eleasar, Sauran poika, otti vaaria yhdestä elephantista, että se oli suurin ja paremmin valmistettu kuin muut, ja luuli kuninkaan sen päällä olevan,","Ja Eleasar, Sauran poika, otti vaaria yhdestä elephantista, että se oli suurin ja paremmin valmistettu kuin muut, ja luuli kuninkaan sen päällä olevan,"],[6,44,"Ja rohkeni sen kimppuun, että hän olis avun saattanut kansallensa Israelille, ja saanut ijankaikkisen nimen.","Ja rohkeni sen kimppuun, että hän olis avun saattanut kansallensa Israelille, ja saanut ijankaikkisen nimen."],[6,45,"Ja juoksi sen tykö suurella rohkeudella, ja tunki itsensä vihollisten lävitse, ja tappoi monta heistä molemmilta puoliltansa,","Ja juoksi sen tykö suurella rohkeudella, ja tunki itsensä vihollisten lävitse, ja tappoi monta heistä molemmilta puoliltansa,"],[6,46,"Ja antoi itsensä elephantin alle ja pisti sen, niin että elephantti lankesi hänen päällensä ja kuoli, kuoli hän myös itse sen alla.","Ja antoi itsensä elephantin alle ja pisti sen, niin että elephantti lankesi hänen päällensä ja kuoli, kuoli hän myös itse sen alla."],[6,47,"Mutta että juudalaiset näkivät, että kuninkaan sotaväki niin väkevä oli, välttivät he sivulle, ja hylkäsivät viholliset sillä erällä.","Mutta että juudalaiset näkivät, että kuninkaan sotaväki niin väkevä oli, välttivät he sivulle, ja hylkäsivät viholliset sillä erällä."],[6,48,"Sentähden meni kuninkaan sotaväki Jerusalemiin, ja tulivat Juudeaan.","Sentähden meni kuninkaan sotaväki Jerusalemiin, ja tulivat Juudeaan."],[6,49,"Mutta ne, jotka Betsurassa olivat, ei voineet enään siinä olla nälän tähden; sillä se oli seitsemäs vuosi, jolla piti maalle lepo oleman; ja he saivat luvan kuninkaalta, että heidän piti menemän ulos pelkäämättä.","Mutta ne, jotka Betsurassa olivat, ei voineet enään siinä olla nälän tähden; sillä se oli seitsemäs vuosi, jolla piti maalle lepo oleman; ja he saivat luvan kuninkaalta, että heidän piti menemän ulos pelkäämättä."],[6,50,"Niin kuningas otti Betsuran, ja pani siihen sotaväen, varjelemaan linnaa,","Niin kuningas otti Betsuran, ja pani siihen sotaväen, varjelemaan linnaa,"],[6,51,"Ja vaelsi Zioniin, ja piiritti pyhän kauvaksi aikaa, ja valmisti siinä kaikkinaiset sota-aseet.","Ja vaelsi Zioniin, ja piiritti pyhän kauvaksi aikaa, ja valmisti siinä kaikkinaiset sota-aseet."],[6,52,"Mutta Israelin kansa varjeli itsensä pyhässä monta päivää, ja tekivät he myös moninaisia sota-aseita vihollisia vastaan.","Mutta Israelin kansa varjeli itsensä pyhässä monta päivää, ja tekivät he myös moninaisia sota-aseita vihollisia vastaan."],[6,53,"Mutta ei heilläkään ollut mitään syötävää, että se oli se seitsemäs vuosi, ja ne vieraat Juudalaiset, jotka pakanain maalta Juudeaan tuodut olivat, että he olisivat siellä olleet varjellut, olivat kaiken ravinnon kuluttaneet.","Mutta ei heilläkään ollut mitään syötävää, että se oli se seitsemäs vuosi, ja ne vieraat Juudalaiset, jotka pakanain maalta Juudeaan tuodut olivat, että he olisivat siellä olleet varjellut, olivat kaiken ravinnon kuluttaneet."],[6,54,"Ja pyhät olivat sangen harvat; sillä he kuolivat nälästä, sen. tähden täytyi heidän erota toinen toisestansa, ja itsensä jakaa kukin paikkaansa.","Ja pyhät olivat sangen harvat; sillä he kuolivat nälästä, sen. tähden täytyi heidän erota toinen toisestansa, ja itsensä jakaa kukin paikkaansa."],[6,55,"Sillä välillä sai Lysias kuulla, että Philippus, jonka haltuun kuninkaan isä nuoren kuninkaan, ja valtakunnan eläissänsä oli antanut,","Sillä välillä sai Lysias kuulla, että Philippus, jonka haltuun kuninkaan isä nuoren kuninkaan, ja valtakunnan eläissänsä oli antanut,"],[6,56,"Oli jälleen tullut Persiasta ja Mediasta sillä sotaväellä, jonka kuningas sinne vienyt oli; ja että Philippus rupesi hallitsemaan.","Oli jälleen tullut Persiasta ja Mediasta sillä sotaväellä, jonka kuningas sinne vienyt oli; ja että Philippus rupesi hallitsemaan."],[6,57,"Sentähden riensi hän pois Juudeasta kotiansa jälleen valtakuntaan, ja sanoi kuninkaalle ja päämiehille: me kärsimme tässä vaivaa ja ei ole meillä mitään syötävää, ja meiltä on paljo väkeä tullut pois, ja tämä sia, jonka me piirittäneet olemme, on sangen vahva, ja meillä on kyllä kotona valtakunnassa toimittamista, jotka asiat korkeammat ovat.","Sentähden riensi hän pois Juudeasta kotiansa jälleen valtakuntaan, ja sanoi kuninkaalle ja päämiehille: me kärsimme tässä vaivaa ja ei ole meillä mitään syötävää, ja meiltä on paljo väkeä tullut pois, ja tämä sia, jonka me piirittäneet olemme, on sangen vahva, ja meillä on kyllä kotona valtakunnassa toimittamista, jotka asiat korkeammat ovat."],[6,58,"Tehkäämme rauha tämän kansan kanssa, ja sallikaamme heidän pitää lakinsa, niinkuin he ennenkin pitäneet ovat.","Tehkäämme rauha tämän kansan kanssa, ja sallikaamme heidän pitää lakinsa, niinkuin he ennenkin pitäneet ovat."],[6,59,"Sillä ainoasti sentähden he vihaiset ovat ja sotivat, että me tahdomme panna pois heidän lakinsa.","Sillä ainoasti sentähden he vihaiset ovat ja sotivat, että me tahdomme panna pois heidän lakinsa."],[6,60,"Tämä puhe kelpasi kuninkaalle ja päämiehille hyvin.","Tämä puhe kelpasi kuninkaalle ja päämiehille hyvin."],[6,61,"Ja kuningas lähetti heidän tykönsä, tekemään rauhaa heidän kanssansa; johon he suostuivat, sillä kuningas päämiehinensä vannoi sen heille.","Ja kuningas lähetti heidän tykönsä, tekemään rauhaa heidän kanssansa; johon he suostuivat, sillä kuningas päämiehinensä vannoi sen heille."],[6,62,"Mutta kuin he tulivat ulos linnasta, meni kuningas sinne sisälle; ja kuin kuningas näki, että se niin vahva oli, niin ei hän pitänyt valaansa, vaan käski kaikki muurit ympäriltä lyödä jälleen maahan.","Mutta kuin he tulivat ulos linnasta, meni kuningas sinne sisälle; ja kuin kuningas näki, että se niin vahva oli, niin ei hän pitänyt valaansa, vaan käski kaikki muurit ympäriltä lyödä jälleen maahan."],[6,63,"Sitte vaelsi hän kiiruusti Antiokiaan. Silloin sai hän ymmärtää, että Philippus oli siellä itsensä tehnyt kuninkaaksi, sen tähden soti hän hänen kanssansa, ja otti kaupungin jälleen väkiväellä.","Sitte vaelsi hän kiiruusti Antiokiaan. Silloin sai hän ymmärtää, että Philippus oli siellä itsensä tehnyt kuninkaaksi, sen tähden soti hän hänen kanssansa, ja otti kaupungin jälleen väkiväellä."],[7,1,"Ensimäisenä vuotena kuudettakymmeutä toista sataa tuli Demetrius Seleukuksen poika Roomista jälleen valtakuntaansa, ja sai yhden merikaupungin vähällä väellä, ja hallitsi siinä kuninkaana.","Ensimäisenä vuotena kuudettakymmeutä toista sataa tuli Demetrius Seleukuksen poika Roomista jälleen valtakuntaansa, ja sai yhden merikaupungin vähällä väellä, ja hallitsi siinä kuninkaana."],[7,2,"Ja kuin hän pääkaupunkiin Antiokiaan tuli, otti sotaväki Antiokuksen ja Lysiaan kiinni, antaaksensa heitä Demetriuksen haltuun.","Ja kuin hän pääkaupunkiin Antiokiaan tuli, otti sotaväki Antiokuksen ja Lysiaan kiinni, antaaksensa heitä Demetriuksen haltuun."],[7,3,"Vaan kuin se Demetriukselle sanottiin, kielsi hän heitä antamasta hänen tulla silmäinsä eteen.","Vaan kuin se Demetriukselle sanottiin, kielsi hän heitä antamasta hänen tulla silmäinsä eteen."],[7,4,"Sentähden tappoi sotaväki heidät.","Sentähden tappoi sotaväki heidät."],[7,5,"Kuin Demetrius oli valtakunnan saanut, tuli hänen tykönsä monta jumalatointa ja luopunutta Israelista, ja ylimmäinen heistä oli Alkimus, joka olis mielellänsä ollut ylimmäinen pappi.","Kuin Demetrius oli valtakunnan saanut, tuli hänen tykönsä monta jumalatointa ja luopunutta Israelista, ja ylimmäinen heistä oli Alkimus, joka olis mielellänsä ollut ylimmäinen pappi."],[7,6,"Nämät kantelivat Juudaan ja oman kansansa päälle, ja sanoivat: Juudas ja hänen veljensä ovat tappaneet eli ajaneet ulos meidän maaltamme kaikki, jotka sinulle tahtoivat kuuliaiset olla.","Nämät kantelivat Juudaan ja oman kansansa päälle, ja sanoivat: Juudas ja hänen veljensä ovat tappaneet eli ajaneet ulos meidän maaltamme kaikki, jotka sinulle tahtoivat kuuliaiset olla."],[7,7,"Sentähden lähetä sinne joku, jonka sinä uskot, ja anna katsoa kuinka he meidän ja kuninkaan maan ovat hävittäneet, ja anna heitä rangaista ja kaikkia, jotka pitävät heidän kanssansa.","Sentähden lähetä sinne joku, jonka sinä uskot, ja anna katsoa kuinka he meidän ja kuninkaan maan ovat hävittäneet, ja anna heitä rangaista ja kaikkia, jotka pitävät heidän kanssansa."],[7,8,"Sen tähden teki kuningas ystävänsä Bakkideksen (joka jalo oli valtakunnassa, ja johon kuningas paljon uskoi,) koko sen maakunnan päämieheksi, tuolla puolella Euphratin virran,","Sen tähden teki kuningas ystävänsä Bakkideksen (joka jalo oli valtakunnassa, ja johon kuningas paljon uskoi,) koko sen maakunnan päämieheksi, tuolla puolella Euphratin virran,"],[7,9,"Ja lähetti hänen kanssansa luopuneen Alkimuksen, jonka hän myös ylimmäiseksi papiksi teki, ja käski hänen Israelin kansaa rangaista.","Ja lähetti hänen kanssansa luopuneen Alkimuksen, jonka hän myös ylimmäiseksi papiksi teki, ja käski hänen Israelin kansaa rangaista."],[7,10,"Ja he menivät Juudan maalle suurella sotajoukolla, ja hän lähetti sanansaattajat Juudaan ja hänen veljeinsä tykö sovintoa toimittamaan, Ja teettelivät itsensä niinkuin he olisivat tahtoneet pitää rauhan heidän kanssansa.","Ja he menivät Juudan maalle suurella sotajoukolla, ja hän lähetti sanansaattajat Juudaan ja hänen veljeinsä tykö sovintoa toimittamaan, Ja teettelivät itsensä niinkuin he olisivat tahtoneet pitää rauhan heidän kanssansa."],[7,11,"Vaan se oli kaikki petos; sentähden ei Juudas heitä uskonut, sillä hän näki, että he niin jalosti varustetut olivat, ja näin suurella sotajoukolla vaelsivat.","Vaan se oli kaikki petos; sentähden ei Juudas heitä uskonut, sillä hän näki, että he niin jalosti varustetut olivat, ja näin suurella sotajoukolla vaelsivat."],[7,12,"Mutta monta pappia tuli Alkimuksen ja Bakkideksen tykö, ja monta muuta hurskasta, jotka Israelissa olivat, ja toivoivat hyvää Alkimuksesta,","Mutta monta pappia tuli Alkimuksen ja Bakkideksen tykö, ja monta muuta hurskasta, jotka Israelissa olivat, ja toivoivat hyvää Alkimuksesta,"],[7,13,"Ja anoivat rauhaa, ja sanoivat:","Ja anoivat rauhaa, ja sanoivat:"],[7,14,"Alkimus on pappi Aaronin suvusta, ei hän meitä petä.","Alkimus on pappi Aaronin suvusta, ei hän meitä petä."],[7,15,"Alkimus lupasi heille rauhan, ja teki valan ja sanoi: emme tahdo teille eikä teidän ystävillenne mitään pahaa tehdä.","Alkimus lupasi heille rauhan, ja teki valan ja sanoi: emme tahdo teille eikä teidän ystävillenne mitään pahaa tehdä."],[7,16,"Kuin he niin uskoivat hänen, antoi hän ottaa kiinni kuusikymmentä heistä, ja tappoi kaikki yhtenä päivänä, niinkuin kirjoitettu on:","Kuin he niin uskoivat hänen, antoi hän ottaa kiinni kuusikymmentä heistä, ja tappoi kaikki yhtenä päivänä, niinkuin kirjoitettu on:"],[7,17,"Sinun pyhäis lihat ovat he pedoille antaneet; he ovat vuodattaneet verta ympäri Jerusalemin niinkuin vettä, ja ei ollut siellä ketään, joka heitä hautasi.","Sinun pyhäis lihat ovat he pedoille antaneet; he ovat vuodattaneet verta ympäri Jerusalemin niinkuin vettä, ja ei ollut siellä ketään, joka heitä hautasi."],[7,18,"Sen tähden tuli sangen suuri pelko ja vavistus kansalle, jotka valittivat, ettei Alkimuksessa ollut totuutta eikä uskollisuutta; sillä ei hän pitänyt valaansa.","Sen tähden tuli sangen suuri pelko ja vavistus kansalle, jotka valittivat, ettei Alkimuksessa ollut totuutta eikä uskollisuutta; sillä ei hän pitänyt valaansa."],[7,19,"Ja Bakkides vaelsi matkaansa Jerusalemista, ja piiritti Betsetan, ja lähetti ja antoi ottaa monta kiinni, jotka ensin olivat itsensä antaneet hänen tykönsä, vaan petoksen tähden jälleen luopuneet hänestä, ja antoi monta heistä tappaa ja heittää suureen luolaan.","Ja Bakkides vaelsi matkaansa Jerusalemista, ja piiritti Betsetan, ja lähetti ja antoi ottaa monta kiinni, jotka ensin olivat itsensä antaneet hänen tykönsä, vaan petoksen tähden jälleen luopuneet hänestä, ja antoi monta heistä tappaa ja heittää suureen luolaan."],[7,20,"Sitte antoi Bakkides maan Alkimuksen haltuun, ja jätti sotaväkeä hänelle, ja meni jälleen kuninkaan tykö.","Sitte antoi Bakkides maan Alkimuksen haltuun, ja jätti sotaväkeä hänelle, ja meni jälleen kuninkaan tykö."],[7,21,"Ja Alkimus aikoi väkivallalla olla ylimmäinen pappi,","Ja Alkimus aikoi väkivallalla olla ylimmäinen pappi,"],[7,22,"Ja veti tykönsä kaikki luopuneet Israelista, ja otti väkisin Juudan maan allensa, ja vaivasi Israelin kansaa sangen raskaasti.","Ja veti tykönsä kaikki luopuneet Israelista, ja otti väkisin Juudan maan allensa, ja vaivasi Israelin kansaa sangen raskaasti."],[7,23,"Kuin Juudas näki, että Alkimus ja ne luopuneet Israelista tekivät paljon vahinkoa Israelissa,","Kuin Juudas näki, että Alkimus ja ne luopuneet Israelista tekivät paljon vahinkoa Israelissa,"],[7,24,"Meni hän taas ympäri koko Juudan ja rankaisi ne luopuneet, ja esti, ettei he enään sinne eikä tänne rohjenneet maakunnassa vaeltaa.","Meni hän taas ympäri koko Juudan ja rankaisi ne luopuneet, ja esti, ettei he enään sinne eikä tänne rohjenneet maakunnassa vaeltaa."],[7,25,"Mutta kuin Alkimus näki, että Juudas ja hänen väkensä jälleen voimaansa tulivat ja ettei hän taitanut olla heitä vastaan, meni hän jälleen kuninkaan tykö, ja kantoi kovin heidän päällensä.","Mutta kuin Alkimus näki, että Juudas ja hänen väkensä jälleen voimaansa tulivat ja ettei hän taitanut olla heitä vastaan, meni hän jälleen kuninkaan tykö, ja kantoi kovin heidän päällensä."],[7,26,"Sentähden lähetti kuningas sinne yhden suuren ruhtinaan Nikanorin, joka Israelin kansalle juuri armotoin oli, ja käski hänen peräti hävittää Israelin kansan.","Sentähden lähetti kuningas sinne yhden suuren ruhtinaan Nikanorin, joka Israelin kansalle juuri armotoin oli, ja käski hänen peräti hävittää Israelin kansan."],[7,27,"Ja Nikanor meni suurella sotajoukolla Jerusalemiin, ja lähetti sanan Juudaan ja hänen veljeinsä tykö petoksella, niinkuin hän tahtonut olis rauhaa heidän kanssansa tehdä, ja sanoi:","Ja Nikanor meni suurella sotajoukolla Jerusalemiin, ja lähetti sanan Juudaan ja hänen veljeinsä tykö petoksella, niinkuin hän tahtonut olis rauhaa heidän kanssansa tehdä, ja sanoi:"],[7,28,"Minä tahdon pitää rauhan teidän kanssanne, ja vähällä väellä tulla sovinnossa puhuttelemaan sinua.","Minä tahdon pitää rauhan teidän kanssanne, ja vähällä väellä tulla sovinnossa puhuttelemaan sinua."],[7,29,"Näin tuli Nikanor Juudaan tykö, ja ottivat toinen toisensa vastaan, ja puhuttelivat keskenänsä sovinnolla; vaan se oli toimitettu, että Juudas piti siellä otettaman kiinni.","Näin tuli Nikanor Juudaan tykö, ja ottivat toinen toisensa vastaan, ja puhuttelivat keskenänsä sovinnolla; vaan se oli toimitettu, että Juudas piti siellä otettaman kiinni."],[7,30,"Se tuli Juudaalle tiettäväksi, että Nikanor oli tullut ottamaan häntä kiinni petoksella, sen. tähden kartti hän häntä, eikä tahtonut enää tulla hänen tykönsä.","Se tuli Juudaalle tiettäväksi, että Nikanor oli tullut ottamaan häntä kiinni petoksella, sen. tähden kartti hän häntä, eikä tahtonut enää tulla hänen tykönsä."],[7,31,"Ja kuin Nikanor sen havaitsi, että hänen aivoituksensa oli julki tullut, meni hän Juudaa vastaan, ja tappeli hänen kanssansa Kaphar Salaman tykönä.","Ja kuin Nikanor sen havaitsi, että hänen aivoituksensa oli julki tullut, meni hän Juudaa vastaan, ja tappeli hänen kanssansa Kaphar Salaman tykönä."],[7,32,"Siinä tuli pois Nikanorilta viisituhatta miestä, ja hänen väkensä täytyi paeta Davidin linnaan.","Siinä tuli pois Nikanorilta viisituhatta miestä, ja hänen väkensä täytyi paeta Davidin linnaan."],[7,33,"Tuli myös Nikanor senjälkeen ylös pyhään Zionin vuorelle, ja papit ja vanhimmat menivät ulos ottamaan häntä rauhallisesti vastaan, ja antamaan hänen nähdä, että he kuninkaan tähden suuren uhrin tehneet olivat.","Tuli myös Nikanor senjälkeen ylös pyhään Zionin vuorelle, ja papit ja vanhimmat menivät ulos ottamaan häntä rauhallisesti vastaan, ja antamaan hänen nähdä, että he kuninkaan tähden suuren uhrin tehneet olivat."],[7,34,"Mutta Nikanor sylki heitä ja heidän jumalanpalvelustansa, häpäisi ja saastutti uhrin,","Mutta Nikanor sylki heitä ja heidän jumalanpalvelustansa, häpäisi ja saastutti uhrin,"],[7,35,"Ja vannoi valan ja sanoi: ellette saata Juudaa ja hänen väkeänsä minun käsiini, niin minä tahdon polttaa tämän huoneen niin pian kuin minä rauhassa tähän jälleen tulen; ja vaelsi matkaansa suuressa julmuudessa.","Ja vannoi valan ja sanoi: ellette saata Juudaa ja hänen väkeänsä minun käsiini, niin minä tahdon polttaa tämän huoneen niin pian kuin minä rauhassa tähän jälleen tulen; ja vaelsi matkaansa suuressa julmuudessa."],[7,36,"Mutta papit menivät sisälle, ja astuivat alttarin eteen templissä, itkivät ja sanoivat:","Mutta papit menivät sisälle, ja astuivat alttarin eteen templissä, itkivät ja sanoivat:"],[7,37,"Herra, että sinä tämän huoneen valinnut olet, sinua tässä rukoiltaa ja sinusta saarnattaa:","Herra, että sinä tämän huoneen valinnut olet, sinua tässä rukoiltaa ja sinusta saarnattaa:"],[7,38,"Niin me rukoilemme, ettäs tahtoisit kostaa Nikanorin ja hänen joukkonsa, ja muistaa. että he sinun pyhäs ja sinua pilkanneet ovat, ja ettäs tahtoisit heitä karkottaa pois maasta ja hukuttaa!","Niin me rukoilemme, ettäs tahtoisit kostaa Nikanorin ja hänen joukkonsa, ja muistaa. että he sinun pyhäs ja sinua pilkanneet ovat, ja ettäs tahtoisit heitä karkottaa pois maasta ja hukuttaa!"],[7,39,"Ja Nikanor vaelsi matkaansa Jerusalemista, ja sioitti itsensä Bethoronin tykö. Siihen tuli myös yksi joukko Syriasta häntä auttamaan.","Ja Nikanor vaelsi matkaansa Jerusalemista, ja sioitti itsensä Bethoronin tykö. Siihen tuli myös yksi joukko Syriasta häntä auttamaan."],[7,40,"Mutta Juudas asetti väkensä häntä vastaan Adassarissa, kolmetuhatta miestä, rukoili Jumalaa ja sanoi:","Mutta Juudas asetti väkensä häntä vastaan Adassarissa, kolmetuhatta miestä, rukoili Jumalaa ja sanoi:"],[7,41,"Herra Jumala! koska kuningas Sennaheribilta lähetetyt miehet sinua pilkkasivat, lähetit sinä enkelin, joka löi maahan sata kahdeksankymmentä ja viisituhatta miestä.","Herra Jumala! koska kuningas Sennaheribilta lähetetyt miehet sinua pilkkasivat, lähetit sinä enkelin, joka löi maahan sata kahdeksankymmentä ja viisituhatta miestä."],[7,42,"Niin lyö myös tänäpänäkin nämät meidän vihollisemme meidän nähtemme, ja tuomitse Nikanor hänen suurten pahain tekoinsa jälkeen, että muut ymmärtäisivät sinun häntä sentähden rangaisseen, että hän sinun pyhääs häväissyt on.","Niin lyö myös tänäpänäkin nämät meidän vihollisemme meidän nähtemme, ja tuomitse Nikanor hänen suurten pahain tekoinsa jälkeen, että muut ymmärtäisivät sinun häntä sentähden rangaisseen, että hän sinun pyhääs häväissyt on."],[7,43,"Ja kolmantena päivänä toistakymmentä Adarin kuuta tappelivat he toinen toisensa kanssa. ja Nikanor tuli kaikkein ensimäisenä lyödyksi.","Ja kolmantena päivänä toistakymmentä Adarin kuuta tappelivat he toinen toisensa kanssa. ja Nikanor tuli kaikkein ensimäisenä lyödyksi."],[7,44,"Ja kuin hänen väkensä sen näki, heittivät he aseensa pois ja pakenivat.","Ja kuin hänen väkensä sen näki, heittivät he aseensa pois ja pakenivat."],[7,45,"Mutta Juudas ajoi heitä takaa päiväkunnan matkan Adassarasta hamaan Gasaraan asti, ja antoi vaskitorvella soittaa,","Mutta Juudas ajoi heitä takaa päiväkunnan matkan Adassarasta hamaan Gasaraan asti, ja antoi vaskitorvella soittaa,"],[7,46,"Että kaikki kansa kaikista kylistä ympäri sen maakunnan olisivat tulleet hänen tykönsä häntäi auttamaan, ja lyömään vihollisia; ja he tulivat Juudaan tykö, ja pitivät taas yhtä hänen kanssansa. Näin tuli Nikanorin väki lyödyksi, ettei yksikään heistä päässyt.","Että kaikki kansa kaikista kylistä ympäri sen maakunnan olisivat tulleet hänen tykönsä häntäi auttamaan, ja lyömään vihollisia; ja he tulivat Juudaan tykö, ja pitivät taas yhtä hänen kanssansa. Näin tuli Nikanorin väki lyödyksi, ettei yksikään heistä päässyt."],[7,47,"Ja Juudas otti heidän saaliinsa ja kalunsa ja vei myötänsä. Vaan Nikanorilta antoi hän pään hakata pois, ja oikian käden, jonka hän valassansa oli nostanut ylös, kuin hän pilkkasi ja uhkasi pyhää; ja antoi sekä pään että käden viedä pois ja Jerusalemissa ripustaa ylös.","Ja Juudas otti heidän saaliinsa ja kalunsa ja vei myötänsä. Vaan Nikanorilta antoi hän pään hakata pois, ja oikian käden, jonka hän valassansa oli nostanut ylös, kuin hän pilkkasi ja uhkasi pyhää; ja antoi sekä pään että käden viedä pois ja Jerusalemissa ripustaa ylös."],[7,48,"Silloin kansa tuli jälleen suuresti iloiseksi, ja piti tämän päivän pyhänä suurella ilolla,","Silloin kansa tuli jälleen suuresti iloiseksi, ja piti tämän päivän pyhänä suurella ilolla,"],[7,49,"Ja sääsi, että sinä päivänä joka vuosi, nimittäin kolmantena päivänä toistakymmentä Adarin kuulla, piti pyhää pidettämän.","Ja sääsi, että sinä päivänä joka vuosi, nimittäin kolmantena päivänä toistakymmentä Adarin kuulla, piti pyhää pidettämän."],[7,50,"Ja näin tuli rauha jälleen Israelin maalle vähäksi ajaksi.","Ja näin tuli rauha jälleen Israelin maalle vähäksi ajaksi."],[8,1,"Juudalaisten liitosta Roomalaisten kanssa. Mutta Juudas kuuli, että Roomalaiset olivat sangen voimalliset ja mielellänsä ottivat muukalaisia varjeluksensa alle, jotka heiltä apua etsivät ja pitivät sanansa uskollisuudessa ja toimellisuudessa.","Juudalaisten liitosta Roomalaisten kanssa. Mutta Juudas kuuli, että Roomalaiset olivat sangen voimalliset ja mielellänsä ottivat muukalaisia varjeluksensa alle, jotka heiltä apua etsivät ja pitivät sanansa uskollisuudessa ja toimellisuudessa."],[8,2,"Sillä hän kuuli, kuinka voimallisia töitä he olivat Frankriikin asuvaisia vastaan tehneet, joita he vaatineet ja allensa saattaneet olivat;","Sillä hän kuuli, kuinka voimallisia töitä he olivat Frankriikin asuvaisia vastaan tehneet, joita he vaatineet ja allensa saattaneet olivat;"],[8,3,"Ja kuinka suurta sotaa he Hispaniassa pitäneet olivat, ja olivat sen vuoren, josta kultaa ja hopiaa kaivetaan, heiltä ottaneet pois, ja että he monta kaukaista maakuntaa Roomista suurella toimella ja vahvuudella olivat voittaneet ja allensa saattaneet,","Ja kuinka suurta sotaa he Hispaniassa pitäneet olivat, ja olivat sen vuoren, josta kultaa ja hopiaa kaivetaan, heiltä ottaneet pois, ja että he monta kaukaista maakuntaa Roomista suurella toimella ja vahvuudella olivat voittaneet ja allensa saattaneet,"],[8,4,"Että he myös monta jaloa kuningasta, jotka heidän maakuntaansa olivat voimallisesti astuneet, maahan lyöneet olivat ja ajaneet pois, ja heidän valtakuntansa ottaneet allensa,","Että he myös monta jaloa kuningasta, jotka heidän maakuntaansa olivat voimallisesti astuneet, maahan lyöneet olivat ja ajaneet pois, ja heidän valtakuntansa ottaneet allensa,"],[8,5,"Ja että he myös äsken Philippuksen, Kittimin kuninkaan ja sen jälkeen hänen poikansa Perseun olivat voittaneet.","Ja että he myös äsken Philippuksen, Kittimin kuninkaan ja sen jälkeen hänen poikansa Perseun olivat voittaneet."],[8,6,"Kuuli hän myös siitä suuresta Antiokuksesta, Asian kuninkaasta, joka Roomalaisia vastaan oli mennyt sadalla ja kahdellakymmenellä elephantilla, jalosti hankituilla sotaneuvoilla ja vaunuilla;","Kuuli hän myös siitä suuresta Antiokuksesta, Asian kuninkaasta, joka Roomalaisia vastaan oli mennyt sadalla ja kahdellakymmenellä elephantilla, jalosti hankituilla sotaneuvoilla ja vaunuilla;"],[8,7,"Vaan roomalaiset löivät hänen sotaväkensä ja ahdistivat hänen niin, että hänen täytyi rauhaa rukoilla, ja laskivat hänen ja hänen jälkeentulevaisten perillistensä päälle suuren veron, jonka heidän piti roomalaisille joka vuosi antaman, ja vielä päälliseksi täytyi lähettää Roomalaisille yhden miehen panttivangiksi.","Vaan roomalaiset löivät hänen sotaväkensä ja ahdistivat hänen niin, että hänen täytyi rauhaa rukoilla, ja laskivat hänen ja hänen jälkeentulevaisten perillistensä päälle suuren veron, jonka heidän piti roomalaisille joka vuosi antaman, ja vielä päälliseksi täytyi lähettää Roomalaisille yhden miehen panttivangiksi."],[8,8,"Ottivat he myös häneltä pois Jonian, Asian ja Lydian, kaikkein parhaat maakunnat, ja antoivat ne kuningas Eumenille.","Ottivat he myös häneltä pois Jonian, Asian ja Lydian, kaikkein parhaat maakunnat, ja antoivat ne kuningas Eumenille."],[8,9,"Nousivat myös Grekiläiset heitä vastaan suurella väellä;","Nousivat myös Grekiläiset heitä vastaan suurella väellä;"],[8,10,"Vaan he lähettivät yhden päämiehen heitä vastaan, joka löi heidät ja sai maan ja antoi kaupungeista muurit jaottaa, että heidän täytyi rauhan pitää ja kuuliaiset olla.","Vaan he lähettivät yhden päämiehen heitä vastaan, joka löi heidät ja sai maan ja antoi kaupungeista muurit jaottaa, että heidän täytyi rauhan pitää ja kuuliaiset olla."],[8,11,"Senkaltaisen miehuuden osoittivat he kaikkia vihollisiansa vastaan, niin että he kaikkia niitä ahdistivat, jotka heitä vastaan itsensä asettivat.","Senkaltaisen miehuuden osoittivat he kaikkia vihollisiansa vastaan, niin että he kaikkia niitä ahdistivat, jotka heitä vastaan itsensä asettivat."],[8,12,"Mutta ystäviensä ja liittoveljiensä kanssa pitivät he hyvän rauhan uskollisesti, ja olivat niin valtiaat, että heitä kaikissa maakunnissa peljättiin.","Mutta ystäviensä ja liittoveljiensä kanssa pitivät he hyvän rauhan uskollisesti, ja olivat niin valtiaat, että heitä kaikissa maakunnissa peljättiin."],[8,13,"Jota he auttivat, se tuli varjelluksi ja sai olla maallansa; vaan jota he tahtoivat sortaa, se tuli ajetuksi pois maaltansa ja valtakunnastansa; he olivat sangen valtiaat.","Jota he auttivat, se tuli varjelluksi ja sai olla maallansa; vaan jota he tahtoivat sortaa, se tuli ajetuksi pois maaltansa ja valtakunnastansa; he olivat sangen valtiaat."],[8,14,"He olivat niin yksivakaiset, ettei yksikään heistä tehnyt itsiänsä kuninkaaksi.","He olivat niin yksivakaiset, ettei yksikään heistä tehnyt itsiänsä kuninkaaksi."],[8,15,"Ja ei heillä myös ollut kuningasta, mutta neuvonantajat, kolmesataa ja kaksikymmentä miestä, jotka hyvin hallitsivat.","Ja ei heillä myös ollut kuningasta, mutta neuvonantajat, kolmesataa ja kaksikymmentä miestä, jotka hyvin hallitsivat."],[8,16,"Ja joka vuosi he valitsivat yhden päämiehen, joka vallitsi kaikki heidän maakuntansa, ja häntä piti kaikkein kuuleman. Ei myös siellä ollut ylpeyttä, kateutta, taikka eripuraisuutta heidän keskenänsä.","Ja joka vuosi he valitsivat yhden päämiehen, joka vallitsi kaikki heidän maakuntansa, ja häntä piti kaikkein kuuleman. Ei myös siellä ollut ylpeyttä, kateutta, taikka eripuraisuutta heidän keskenänsä."],[8,17,"Ja Juudas valitsi Eupolemon Johanneksen pojan, joka oli Jakobin poika, ja Jasonin Eleatsarin pojan, ja lähetti heidät Roomiin tekemään ystävyyttä ja liittoa Roomalaisten kanssa, että he olisivat heille avulliset,","Ja Juudas valitsi Eupolemon Johanneksen pojan, joka oli Jakobin poika, ja Jasonin Eleatsarin pojan, ja lähetti heidät Roomiin tekemään ystävyyttä ja liittoa Roomalaisten kanssa, että he olisivat heille avulliset,"],[8,18,"Ettei Israelin kuninkaan valtakunta olisi tullut poljetuksi alas Grekiläisten kautta.","Ettei Israelin kuninkaan valtakunta olisi tullut poljetuksi alas Grekiläisten kautta."],[8,19,"Nämät vaelsivat Roomiin sangen pitkän matkan, ja tulivat hallituksen eteen ja sanoivat:","Nämät vaelsivat Roomiin sangen pitkän matkan, ja tulivat hallituksen eteen ja sanoivat:"],[8,20,"Juudas Makkabealainen ja hänen veljensä ja Juudan kansa ovat lähettäneet meidät teidän tykönne, tekemään rauhaa ja liittoa teidän kanssanne, että te tahtoisitte meitä ottaa teidän varjeluksenne alle, niinkuin ystäviä ja liittoveljiä.","Juudas Makkabealainen ja hänen veljensä ja Juudan kansa ovat lähettäneet meidät teidän tykönne, tekemään rauhaa ja liittoa teidän kanssanne, että te tahtoisitte meitä ottaa teidän varjeluksenne alle, niinkuin ystäviä ja liittoveljiä."],[8,21,"Se kelpasi Roomalaisille hyvin","Se kelpasi Roomalaisille hyvin"],[8,22,"Ja antoivat kirjoittaa liiton vaskisiin tauluihin, jotka he lähettivät Jerusalemiin, muistoksi senkaltaisesta rauhasta ja liitosta, ja oli näin kirjoitettu:","Ja antoivat kirjoittaa liiton vaskisiin tauluihin, jotka he lähettivät Jerusalemiin, muistoksi senkaltaisesta rauhasta ja liitosta, ja oli näin kirjoitettu:"],[8,23,"Jumala antakoon Roomalaisille ja Juudalaisille onnea ja rauhaa sekä vedellä että maalla, ja varjelkoon heitä sodista ja vihollisista ijankaikkisesti!","Jumala antakoon Roomalaisille ja Juudalaisille onnea ja rauhaa sekä vedellä että maalla, ja varjelkoon heitä sodista ja vihollisista ijankaikkisesti!"],[8,24,"Mutta jos Roomalaisille sota tapahtuu, taikka Roomissa, eli heidän maakunnissansa ja paikkakunnissansa,","Mutta jos Roomalaisille sota tapahtuu, taikka Roomissa, eli heidän maakunnissansa ja paikkakunnissansa,"],[8,25,"Niin Juudalaisten pitää uskollisesti auttaman Roomalaisia, sen jälkeen kuin tarve on.","Niin Juudalaisten pitää uskollisesti auttaman Roomalaisia, sen jälkeen kuin tarve on."],[8,26,"Ja ei pidä heidän Roomin vihollisille mitään elatusta, aseita, rahaa, laivoja eli muuta tarvetta lähettämän. Näitä anovat Rooma laiset Juudalaisilta, ja Juudalaisten tulee nämät kappaleet uskollisesti pitää ilman petosta ja vilppiä.","Ja ei pidä heidän Roomin vihollisille mitään elatusta, aseita, rahaa, laivoja eli muuta tarvetta lähettämän. Näitä anovat Rooma laiset Juudalaisilta, ja Juudalaisten tulee nämät kappaleet uskollisesti pitää ilman petosta ja vilppiä."],[8,27,"Sitä vastaan, jos Juudalaisille sota tarjona on, niin pitää Roomalaisten uskollisesti heitä auttaman, senjälkeen kuin tarve vaatii.","Sitä vastaan, jos Juudalaisille sota tarjona on, niin pitää Roomalaisten uskollisesti heitä auttaman, senjälkeen kuin tarve vaatii."],[8,28,"Ja ei pidä heidän Juudalaisten vihollisille elatusta, aseita, rahaa, laivoja taikka muita tarpeita lähettämän. Tätä lupaavat Roomalaiset Juudalaisille, ja tahtovat senkaltaisen liiton uskollisesti ja ilman petosta pitää.","Ja ei pidä heidän Juudalaisten vihollisille elatusta, aseita, rahaa, laivoja taikka muita tarpeita lähettämän. Tätä lupaavat Roomalaiset Juudalaisille, ja tahtovat senkaltaisen liiton uskollisesti ja ilman petosta pitää."],[8,29,"Näin on liitto Roomalaisten ja Juudalaisten välille tehty.","Näin on liitto Roomalaisten ja Juudalaisten välille tehty."],[8,30,"Mutta jos tästedes jompi kumpi puoli ajattelee siihen enempää lisätä, taikka jotakin muuttaa, eli siitä vähentää, siihen pitää molemmilla puolilla voima oleman; ja mitä he siihen lisäävät, taikka siitä vähentävät, se pitää kaikki lujana ja vahvana pidettämän.","Mutta jos tästedes jompi kumpi puoli ajattelee siihen enempää lisätä, taikka jotakin muuttaa, eli siitä vähentää, siihen pitää molemmilla puolilla voima oleman; ja mitä he siihen lisäävät, taikka siitä vähentävät, se pitää kaikki lujana ja vahvana pidettämän."],[8,31,"Jos myös kuningas Demetrius Juudan kansalle väkivaltaa tekee, siitä me olemme kirjoittaneet hänen tykönsä tällä tavalla: miksi sinä vaivaat meidän ystäviämme ja liittoveljiämme?","Jos myös kuningas Demetrius Juudan kansalle väkivaltaa tekee, siitä me olemme kirjoittaneet hänen tykönsä tällä tavalla: miksi sinä vaivaat meidän ystäviämme ja liittoveljiämme?"],[8,32,"Jos he tästälähin kantavat sinun päälles, niin meidän pitää heitä varjeleman, ja tahdomme sinun kimppuus sekä vedellä että maalla.","Jos he tästälähin kantavat sinun päälles, niin meidän pitää heitä varjeleman, ja tahdomme sinun kimppuus sekä vedellä että maalla."],[9,1,"Jonatan tulee sodassa tapetun veljensä Juudaan siaan. Sillä välillä kuin Demetrius ymmärsi, että Nikanor sotajoukkoinensa lyöty ja voitettu oli, lähetti hän jälleen Juudeaan nämät kaksi, Bakkideksen ja Alkimuksen, ja heidän kanssansa parhaan sotaväkensä, jotka sodissa alati oikialla puolella pidettiin.","Jonatan tulee sodassa tapetun veljensä Juudaan siaan. Sillä välillä kuin Demetrius ymmärsi, että Nikanor sotajoukkoinensa lyöty ja voitettu oli, lähetti hän jälleen Juudeaan nämät kaksi, Bakkideksen ja Alkimuksen, ja heidän kanssansa parhaan sotaväkensä, jotka sodissa alati oikialla puolella pidettiin."],[9,2,"Nämät menivät Galgalaan päin, piirittivät ja voittivat Maslotin Arbelassa ja tappoivat siellä paljon väkeä.","Nämät menivät Galgalaan päin, piirittivät ja voittivat Maslotin Arbelassa ja tappoivat siellä paljon väkeä."],[9,3,"Senjälkeen toisena vuotena kuudettakymmentä toista sataa, ensimäisellä kuulla, matkustivat he Jerusalemiin,","Senjälkeen toisena vuotena kuudettakymmentä toista sataa, ensimäisellä kuulla, matkustivat he Jerusalemiin,"],[9,4,"Ja sieltä Bereaan kahdellakymmenellä tuhannella jalkamiehellä ja kahdellatuhannella hevosmiehellä.","Ja sieltä Bereaan kahdellakymmenellä tuhannella jalkamiehellä ja kahdellatuhannella hevosmiehellä."],[9,5,"Ja Juudas sioitti itsensä Laisan tykönä kolmellatuhannella miehellä.","Ja Juudas sioitti itsensä Laisan tykönä kolmellatuhannella miehellä."],[9,6,"Vaan kuin hänen väkensä näki, että vihollisia niin suuri joukko oli, hämmästyivät he ja pakenivat, niin ettei enempi Juudaan tykö jäänyt kuin kahdeksansataa miestä.","Vaan kuin hänen väkensä näki, että vihollisia niin suuri joukko oli, hämmästyivät he ja pakenivat, niin ettei enempi Juudaan tykö jäänyt kuin kahdeksansataa miestä."],[9,7,"Kuin Juudas tämän näki, ettei hänen sotaväkensä yhdessä pysynyt, ja viholliset kumminkin täyttivät hänen päällensä, tuli hän surulliseksi; ja kuin hän näki, ettei hänellä tilaa ollut rohkaista väkeänsä, ja saattaa heitä yhteen jälleen,","Kuin Juudas tämän näki, ettei hänen sotaväkensä yhdessä pysynyt, ja viholliset kumminkin täyttivät hänen päällensä, tuli hän surulliseksi; ja kuin hän näki, ettei hänellä tilaa ollut rohkaista väkeänsä, ja saattaa heitä yhteen jälleen,"],[9,8,"Sanoi hän tässä ahdistuksessa jääneille: ylös, ja koetelkaamme, jos me vihollisten kimppuun tohdimme, ja heitä lyödä taidamme!","Sanoi hän tässä ahdistuksessa jääneille: ylös, ja koetelkaamme, jos me vihollisten kimppuun tohdimme, ja heitä lyödä taidamme!"],[9,9,"Mutta ei he tahtoneet, vaan estelivät sen pois, ja sanoivat: ei se ole mahdollinen, että me jotain taidamme tehdä; mutta anna meidän tällä erällä välttää ja palata pois, ja hakea meidän veljemme yhteen, jotka meiltä paenneet ovat; sitte me tahdomme jälleen tulla vihollisten tykö, ja lyödä heitä: nyt on meitä sangen vähä.","Mutta ei he tahtoneet, vaan estelivät sen pois, ja sanoivat: ei se ole mahdollinen, että me jotain taidamme tehdä; mutta anna meidän tällä erällä välttää ja palata pois, ja hakea meidän veljemme yhteen, jotka meiltä paenneet ovat; sitte me tahdomme jälleen tulla vihollisten tykö, ja lyödä heitä: nyt on meitä sangen vähä."],[9,10,"Mutta Juudas sanoi: pois se, että meidän pitää pakeneman; jos meidän aikamme on tullut, niin me tahdomme kunniallisesti kuolla meidän veljeimme tähden, ja ei sallia meidän kunniaamme häpiäksi tulla.","Mutta Juudas sanoi: pois se, että meidän pitää pakeneman; jos meidän aikamme on tullut, niin me tahdomme kunniallisesti kuolla meidän veljeimme tähden, ja ei sallia meidän kunniaamme häpiäksi tulla."],[9,11,"Ja viholliset nousivat ja asettuivat kukin paikkaansa näin: ensimäiset olivat ampujat, ja parhaat sotamiehet seisoivat ensimäisinä.","Ja viholliset nousivat ja asettuivat kukin paikkaansa näin: ensimäiset olivat ampujat, ja parhaat sotamiehet seisoivat ensimäisinä."],[9,12,"Hevosmiehet olivat jaetut kahteen joukkoon, yksi joukko kummallekin puolelle. Pääruhtinas Bakkides oli oikialla puolella. Tällä järjestyksellä astuivat he edes suurella huudolla ja vaskitorvien äänellä.","Hevosmiehet olivat jaetut kahteen joukkoon, yksi joukko kummallekin puolelle. Pääruhtinas Bakkides oli oikialla puolella. Tällä järjestyksellä astuivat he edes suurella huudolla ja vaskitorvien äänellä."],[9,13,"Niin antoi myös Juudas vaskitorviin puhaltaa, ja meni heidän tykönsä, ja tappeli heidän kanssansa huomenesta hamaan ehtoosen asti, niin että maa järisi siitä suuresta metelistä.","Niin antoi myös Juudas vaskitorviin puhaltaa, ja meni heidän tykönsä, ja tappeli heidän kanssansa huomenesta hamaan ehtoosen asti, niin että maa järisi siitä suuresta metelistä."],[9,14,"Kuin Juudas näki, että Bakkides itse ja suuri joukko oli oikialla puolella, niin hän karkasi itse sen päälle, hän ja ne muut, jotka ei henkeänsä säästäneet, ja peljättivät heidät,","Kuin Juudas näki, että Bakkides itse ja suuri joukko oli oikialla puolella, niin hän karkasi itse sen päälle, hän ja ne muut, jotka ei henkeänsä säästäneet, ja peljättivät heidät,"],[9,15,"Ja löivät joukon oikialta puolelta pakoon, ja ajoivat heitä takaa aina Asdodin vuoren tykö.","Ja löivät joukon oikialta puolelta pakoon, ja ajoivat heitä takaa aina Asdodin vuoren tykö."],[9,16,"Mutta koska ne, jotka vasemmalla puolella olivat, näkivät sen, että Juudas ajoi heitä takaa, riensivät he myös Juudaan perässä.","Mutta koska ne, jotka vasemmalla puolella olivat, näkivät sen, että Juudas ajoi heitä takaa, riensivät he myös Juudaan perässä."],[9,17,"Niin täytyi Juudaan kääntyä niitä vastaan, ja varjeli itsensä kauvan; ja siinä tapahtui suuri veren vuodatus, niin että monta tuli haavoitetuksi ja kuoliaaksi lyödyksi molemmilta puolilta.","Niin täytyi Juudaan kääntyä niitä vastaan, ja varjeli itsensä kauvan; ja siinä tapahtui suuri veren vuodatus, niin että monta tuli haavoitetuksi ja kuoliaaksi lyödyksi molemmilta puolilta."],[9,18,"Ja Juudas myös viimeiseltä tuli lyödyksi; niin pakenivat ne, jotka jääneet olivat.","Ja Juudas myös viimeiseltä tuli lyödyksi; niin pakenivat ne, jotka jääneet olivat."],[9,19,"Jonatan ja Simon ottivat veljensä Juudaan ruumiin, ja hautasivat hänen isänsä hautaan Modin kaupungissa,","Jonatan ja Simon ottivat veljensä Juudaan ruumiin, ja hautasivat hänen isänsä hautaan Modin kaupungissa,"],[9,20,"Ja Israelin kansa suri Juudaa kauvan aikaa, ja valitti häntä sangen raskaasti, ja sanoi:","Ja Israelin kansa suri Juudaa kauvan aikaa, ja valitti häntä sangen raskaasti, ja sanoi:"],[9,21,"Voi että sankari on kaatunut, joka Israelia varjellut ja vapahtanut on!","Voi että sankari on kaatunut, joka Israelia varjellut ja vapahtanut on!"],[9,22,"Tämä on historia Juudaasta; mutta hän on vielä monta muuta miehuullista asiaa tehnyt, jotka ei kaikki paljouden tähden ole kirjoitetut.","Tämä on historia Juudaasta; mutta hän on vielä monta muuta miehuullista asiaa tehnyt, jotka ei kaikki paljouden tähden ole kirjoitetut."],[9,23,"Juudaan kuoleman jälkeen tulivat jumalattomat ja luopuneet jälleen voimallisiksi koko Israelin maalla.","Juudaan kuoleman jälkeen tulivat jumalattomat ja luopuneet jälleen voimallisiksi koko Israelin maalla."],[9,24,"Ja siihen aikaan oli suuri nälkä maalla, niin että kaikki kansa antoi itsensä Bakkideksen alle.","Ja siihen aikaan oli suuri nälkä maalla, niin että kaikki kansa antoi itsensä Bakkideksen alle."],[9,25,"Silloin valitsi Bakkides jumalattomia miehiä, jotka hän teki virkamiehiksi,","Silloin valitsi Bakkides jumalattomia miehiä, jotka hän teki virkamiehiksi,"],[9,26,"Ja antoi joka paikassa etsiä Juudaan kumppaneita ja ystäviä, ja eteensä tuoda, että hän olis kostanut heille, ja pilkannut heitä.","Ja antoi joka paikassa etsiä Juudaan kumppaneita ja ystäviä, ja eteensä tuoda, että hän olis kostanut heille, ja pilkannut heitä."],[9,27,"Ja Israelissa oli senkaltainen suru ja ahdistus, ettei sen vertaa ole ollut jälkeen prophetain ajan.","Ja Israelissa oli senkaltainen suru ja ahdistus, ettei sen vertaa ole ollut jälkeen prophetain ajan."],[9,28,"Sentähden tulivat Juudaan kumppanit kokoon, ja sanoivat Jonatanille:","Sentähden tulivat Juudaan kumppanit kokoon, ja sanoivat Jonatanille:"],[9,29,"Sinun veljes Juudaan kuoleman jälkeen ei ole meillä yhtään enään hänen kaltaistansa, joka meitä varjelis meidän vihollisiltamme ja Bakkideksen käsistä, jotka meitä vainoovat.","Sinun veljes Juudaan kuoleman jälkeen ei ole meillä yhtään enään hänen kaltaistansa, joka meitä varjelis meidän vihollisiltamme ja Bakkideksen käsistä, jotka meitä vainoovat."],[9,30,"Sentähden valitsemme me sinut hänen siaansa esimieheksi ja pääruhtinaaksi, pitämään tätä sotaa.","Sentähden valitsemme me sinut hänen siaansa esimieheksi ja pääruhtinaaksi, pitämään tätä sotaa."],[9,31,"Ja niin tuli Jonatan heidän esimieheksensä, ja hallitsi veljensä siassa.","Ja niin tuli Jonatan heidän esimieheksensä, ja hallitsi veljensä siassa."],[9,32,"Kuin Bakkides tämän ymmärsi, antoi hän etsiä häntä, että hän olis surettanut hänen.","Kuin Bakkides tämän ymmärsi, antoi hän etsiä häntä, että hän olis surettanut hänen."],[9,33,"Koska Jonatan ja Simon hänen veljensä sen ymmärsivät, pakenivat he ja kaikki ne, jotka heidän kanssansa olivat, Tekoen korpeen, ja sioittivat itsensä Asparin veden tykö.","Koska Jonatan ja Simon hänen veljensä sen ymmärsivät, pakenivat he ja kaikki ne, jotka heidän kanssansa olivat, Tekoen korpeen, ja sioittivat itsensä Asparin veden tykö."],[9,34,"Tämän sai Bakkides tietää, joka nousi ja meni heitä vastaan.","Tämän sai Bakkides tietää, joka nousi ja meni heitä vastaan."],[9,35,"Ja Jonatan oli lähettänyt päämiehen veljen Johanneksen ystäväinsä Nabatealaisten tykö, rukoilemaan heitä, että he riistansa ja tavaransa kaupunkiinsa ottaisivat ja tallella pitäisivät.","Ja Jonatan oli lähettänyt päämiehen veljen Johanneksen ystäväinsä Nabatealaisten tykö, rukoilemaan heitä, että he riistansa ja tavaransa kaupunkiinsa ottaisivat ja tallella pitäisivät."],[9,36,"Mutta Jambrin pojat läksivät ulos Magdabanin kaupungista ja karkasivat Johanneksen päälle, ja ottivat hänen kiinni, ja ottivat häneltä kaikki, mitä hänen myötänsä oli, ja veivät heidät kaupunkiinsa.","Mutta Jambrin pojat läksivät ulos Magdabanin kaupungista ja karkasivat Johanneksen päälle, ja ottivat hänen kiinni, ja ottivat häneltä kaikki, mitä hänen myötänsä oli, ja veivät heidät kaupunkiinsa."],[9,37,"Senjälkeen ilmoitettiin Jonatanille ja Simonille hänen veljellensä, että Jambrin pojat valmistivat suuret häät, ja piti tuoman morsiamen Nadabasta suurella koreudella; sillä se oli päämiehen tytär Kanaanin maalta.","Senjälkeen ilmoitettiin Jonatanille ja Simonille hänen veljellensä, että Jambrin pojat valmistivat suuret häät, ja piti tuoman morsiamen Nadabasta suurella koreudella; sillä se oli päämiehen tytär Kanaanin maalta."],[9,38,"Niin Jonatan ja Simon ajattelivat sitä, että nämät tappaneet olivat heidän veljensä Johanneksen; sen tähden menivät he ylös, ja kätkivät itsensä vuorten onkaloihin ja vartioitsivat Jambrin lapsia.","Niin Jonatan ja Simon ajattelivat sitä, että nämät tappaneet olivat heidän veljensä Johanneksen; sen tähden menivät he ylös, ja kätkivät itsensä vuorten onkaloihin ja vartioitsivat Jambrin lapsia."],[9,39,"Kuin ylkä siitä matkusti ystävinensä, ja paljolla väellä ja tavaralla, huiluilla ja rummuilla ja kalliilla kaunistuksilla,","Kuin ylkä siitä matkusti ystävinensä, ja paljolla väellä ja tavaralla, huiluilla ja rummuilla ja kalliilla kaunistuksilla,"],[9,40,"Karkasi Simon ja Jonatan alas vuorelta, ja löivät heitä ja tappoivat monta, niin että ne, jotka pääsivät, täytyi paeta vuorelle, ja ottivat pois heidän riistansa.","Karkasi Simon ja Jonatan alas vuorelta, ja löivät heitä ja tappoivat monta, niin että ne, jotka pääsivät, täytyi paeta vuorelle, ja ottivat pois heidän riistansa."],[9,41,"Silloin häät murheeksi muuttuivat, ja huilun ilo itkuksi.","Silloin häät murheeksi muuttuivat, ja huilun ilo itkuksi."],[9,42,"Näin kostivat he sen murhan, joka heidän veljellensä tehty oli, ja palasivat jälleen ja vaelsivat Jordanin tykö.","Näin kostivat he sen murhan, joka heidän veljellensä tehty oli, ja palasivat jälleen ja vaelsivat Jordanin tykö."],[9,43,"Niin tuli myös Bakkides Jordanin tykö suurella sotajoukolla, sabbatina.","Niin tuli myös Bakkides Jordanin tykö suurella sotajoukolla, sabbatina."],[9,44,"Ja Jonatan sanoi kansallensa: ylös, ja varustakaat teitänne tappelemaan, sillä ette saa tässä nyt levossa olla niinkuin ennen.","Ja Jonatan sanoi kansallensa: ylös, ja varustakaat teitänne tappelemaan, sillä ette saa tässä nyt levossa olla niinkuin ennen."],[9,45,"Sillä viholliset ovat saapuvilla: meidän täytyy varjella meitämme, emme kuitenkaan taida välttää; sillä meillä on viholliset sekä edessämme että perässämme; niin on Jordanin virta yhdellä puolella, toisella ovat suot ja vuoret.","Sillä viholliset ovat saapuvilla: meidän täytyy varjella meitämme, emme kuitenkaan taida välttää; sillä meillä on viholliset sekä edessämme että perässämme; niin on Jordanin virta yhdellä puolella, toisella ovat suot ja vuoret."],[9,46,"Sentähden pitää teidän huutaman taivaasen, että te vihollisten käsistä autettaisiin.","Sentähden pitää teidän huutaman taivaasen, että te vihollisten käsistä autettaisiin."],[9,47,"Ja he tulivat tappelemaan, ja Jonatan löi Bakkidesta; mutta Bakkides vetäytyi takaperin.","Ja he tulivat tappelemaan, ja Jonatan löi Bakkidesta; mutta Bakkides vetäytyi takaperin."],[9,48,"Silloin hyppäsi Jonatan ja hänen väkensä Jordaniin, ja tulivat virran ylitse; vaan Bakkidek sen väki ei tohtineet antaa itsiänsä virtaan.","Silloin hyppäsi Jonatan ja hänen väkensä Jordaniin, ja tulivat virran ylitse; vaan Bakkidek sen väki ei tohtineet antaa itsiänsä virtaan."],[9,49,"Ja sinä päivänä kaatui Bakkideksen puolelta tuhannen miestä.","Ja sinä päivänä kaatui Bakkideksen puolelta tuhannen miestä."],[9,50,"Sentähden palasi Bakkides Jerusalemiin, ja rupesi vahvistamaan kaupungeita maassa; hän antoi rakentaa portit ja korkiat muurit Jerihon ympäri, Emmaonin, Bethoronin, Betelin, Tamnatanin, Pharanin ja Toponin,","Sentähden palasi Bakkides Jerusalemiin, ja rupesi vahvistamaan kaupungeita maassa; hän antoi rakentaa portit ja korkiat muurit Jerihon ympäri, Emmaonin, Bethoronin, Betelin, Tamnatanin, Pharanin ja Toponin,"],[9,51,"Ja pani niihin sotaväkeä vartiaksi, joiden Israelia vaivaaman piti.","Ja pani niihin sotaväkeä vartiaksi, joiden Israelia vaivaaman piti."],[9,52,"Niin antoi hän myös vahvistaa Betsuran, Gatsan ja linnan Jerusalemissa, ja pani myös siihen sotaväkeä ja toimitti heille ravinnon,","Niin antoi hän myös vahvistaa Betsuran, Gatsan ja linnan Jerusalemissa, ja pani myös siihen sotaväkeä ja toimitti heille ravinnon,"],[9,53,"Ja otti ylimmäisten lapset pantiksi, ja piti ne kiinni Jerusalemin linnassa.","Ja otti ylimmäisten lapset pantiksi, ja piti ne kiinni Jerusalemin linnassa."],[9,54,"Kolmantena vuotena kuudettakymmentä toista sataa, toisella kuukaudella, käski Alkimus myös maahan jaottaa sisälliset muurit kartanosta, joka kaikkein likin templin edessä oli, jotka pyhät prophetat olivat antaneet rakentaa.","Kolmantena vuotena kuudettakymmentä toista sataa, toisella kuukaudella, käski Alkimus myös maahan jaottaa sisälliset muurit kartanosta, joka kaikkein likin templin edessä oli, jotka pyhät prophetat olivat antaneet rakentaa."],[9,55,"Ja kuin tähän työhön ruvettiin, löi Jumala Alkimuksen, niin että tämä aivoitus tuli taas estetyksi; sillä hän halvattiin niin, ettei hän saanut mitään puhua, taikka jotain toimittaa, ja laittaa asioitansa.","Ja kuin tähän työhön ruvettiin, löi Jumala Alkimuksen, niin että tämä aivoitus tuli taas estetyksi; sillä hän halvattiin niin, ettei hän saanut mitään puhua, taikka jotain toimittaa, ja laittaa asioitansa."],[9,56,"Ja niin hän kuoli suuressa kivussa.","Ja niin hän kuoli suuressa kivussa."],[9,57,"Mutta koska Bakkides näki, että Alkimus kuoli, matkusti hän jälleen kuninkaan tykö; niin oli rauha ja lepo maassa kaksi vuotta.","Mutta koska Bakkides näki, että Alkimus kuoli, matkusti hän jälleen kuninkaan tykö; niin oli rauha ja lepo maassa kaksi vuotta."],[9,58,"Mutta ne luopuneet maalla pitivät neuvoa, ja sanoivat: Jonatan ja hänen seuransa istuvat alallansa, heillä on rauha, ja ovat suruttomat, kutsukaamme nyt taas Bakkides: hän taitais kaikki heidät ottaa kiinni yhtenä yönä.","Mutta ne luopuneet maalla pitivät neuvoa, ja sanoivat: Jonatan ja hänen seuransa istuvat alallansa, heillä on rauha, ja ovat suruttomat, kutsukaamme nyt taas Bakkides: hän taitais kaikki heidät ottaa kiinni yhtenä yönä."],[9,59,"Ja he menivät Bakkideksen tykö, ja sanoivat hänelle neuvonsa.","Ja he menivät Bakkideksen tykö, ja sanoivat hänelle neuvonsa."],[9,60,"Niin Bakkides nousi ylös suurella väellä, ja lähetti kirjat salaisesti kumppaniensa tykö Juudan maalle, että he Jonatanin ja kaikki ne, jotka hänen kanssansa olivat, piti ottaman kiinni. Mutta tämä neuvo tuli Jonatanille tiettäväksi, sen tähden ei he mitään matkaan saaneet;","Niin Bakkides nousi ylös suurella väellä, ja lähetti kirjat salaisesti kumppaniensa tykö Juudan maalle, että he Jonatanin ja kaikki ne, jotka hänen kanssansa olivat, piti ottaman kiinni. Mutta tämä neuvo tuli Jonatanille tiettäväksi, sen tähden ei he mitään matkaan saaneet;"],[9,61,"Vaan Jonatan otti kiinni liki viisikymmentä ylimmäistä poisluopuneiden ja jumattomien joukosta, ja antoi tappaa heidät.","Vaan Jonatan otti kiinni liki viisikymmentä ylimmäistä poisluopuneiden ja jumattomien joukosta, ja antoi tappaa heidät."],[9,62,"Sitte poikkesivat Jonatan ja Simon väkinensä korpeen yhteen hävitettyyn kaupunkiin Betbeseniin; sen hän rakensi jälleen, ja teki vahvaksi.","Sitte poikkesivat Jonatan ja Simon väkinensä korpeen yhteen hävitettyyn kaupunkiin Betbeseniin; sen hän rakensi jälleen, ja teki vahvaksi."],[9,63,"Kuin nyt Bakkides sen tietää sai, nousi hän kaiken väkensä kanssa, siihen myös ajoi Juudalaiset kanssansa;","Kuin nyt Bakkides sen tietää sai, nousi hän kaiken väkensä kanssa, siihen myös ajoi Juudalaiset kanssansa;"],[9,64,"Ja meni Betbeseniin, ja oli sen alla kauvan aikaa, ja kävi väkirynnäköllä sen päälle, ja teki ampumus- ja muut sota-aseet sen eteen.","Ja meni Betbeseniin, ja oli sen alla kauvan aikaa, ja kävi väkirynnäköllä sen päälle, ja teki ampumus- ja muut sota-aseet sen eteen."],[9,65,"Mutta Jonatan antoi kaupungin veljensä Simonin haltuun, ja meni yhdellä joukolla ulos,","Mutta Jonatan antoi kaupungin veljensä Simonin haltuun, ja meni yhdellä joukolla ulos,"],[9,66,"Ja löi Odarenin ja hänen veljensä, ja Phaseronin lapset heidän majoissansa. Vaan että se menestyi hänelle, saapui enempi kansaa hänen tykönsä, niin että hän tuli väkevämmäksi.","Ja löi Odarenin ja hänen veljensä, ja Phaseronin lapset heidän majoissansa. Vaan että se menestyi hänelle, saapui enempi kansaa hänen tykönsä, niin että hän tuli väkevämmäksi."],[9,67,"Silloin tuli myös Simon kaupungista vihollisten leiriin, ja poltti sodan rakennukset, ja löi Bakkideksen pakoon.","Silloin tuli myös Simon kaupungista vihollisten leiriin, ja poltti sodan rakennukset, ja löi Bakkideksen pakoon."],[9,68,"Ja Bakkides sai sangen katkeran sydämen, että hänen aivoituksensa ja neuvonsa oli turha,","Ja Bakkides sai sangen katkeran sydämen, että hänen aivoituksensa ja neuvonsa oli turha,"],[9,69,"Ja vihastui petollisten Juudalaisten päälle, jotka hänelle sitä neuvoa olivat antaneet, että hän jälleen tuli siihen maakuntaan, ja antoi tappaa heistä monta, ja valmisti itsensä menemään matkaansa jälleen omalle maallensa.","Ja vihastui petollisten Juudalaisten päälle, jotka hänelle sitä neuvoa olivat antaneet, että hän jälleen tuli siihen maakuntaan, ja antoi tappaa heistä monta, ja valmisti itsensä menemään matkaansa jälleen omalle maallensa."],[9,70,"Kuin Jonatan sen ymmärsi, lähetti hän sanan hänelle, tehdäksensä rauhaa hänen kanssansa, ja rukoili häntä, että hän olis antanut saaliin jälleen ja vangit irralle.","Kuin Jonatan sen ymmärsi, lähetti hän sanan hänelle, tehdäksensä rauhaa hänen kanssansa, ja rukoili häntä, että hän olis antanut saaliin jälleen ja vangit irralle."],[9,71,"Siihen mielistyi Bakkides mielellänsä, ja teki niinkuin Jonatan anoi, ja vannoi hänelle valan, ettei hän enään tahtonut tehdä hänelle pahaa kaikkena elinaikanansa.","Siihen mielistyi Bakkides mielellänsä, ja teki niinkuin Jonatan anoi, ja vannoi hänelle valan, ettei hän enään tahtonut tehdä hänelle pahaa kaikkena elinaikanansa."],[9,72,"Ja antoi hänelle jälleen kalun ja Juudan vangit irrallensa, ja palasi omalle maallensa, ja ei enään tullut Juudan maalle.","Ja antoi hänelle jälleen kalun ja Juudan vangit irrallensa, ja palasi omalle maallensa, ja ei enään tullut Juudan maalle."],[9,73,"Niin taas tuli rauha Israeliin, ja Jonatan asui Makmassa, ja hallitsi siinä kansaa, ja suretti ne petolliset poisluopuneet lsraelista.","Niin taas tuli rauha Israeliin, ja Jonatan asui Makmassa, ja hallitsi siinä kansaa, ja suretti ne petolliset poisluopuneet lsraelista."],[10,1,"Kuudentenakymmenentenä vuotena toista sataa tuli Aleksander, Antiokuksen Epiphaneksen poika, ja voitti Ptolemain kaupungin, ja hallitsi siinä.","Kuudentenakymmenentenä vuotena toista sataa tuli Aleksander, Antiokuksen Epiphaneksen poika, ja voitti Ptolemain kaupungin, ja hallitsi siinä."],[10,2,"Mutta kun Demetrius sen tietää sai, kokosi hän suuren sotaväen, ja meni Aleksanderia vastaan, ajamaan häntä pois.","Mutta kun Demetrius sen tietää sai, kokosi hän suuren sotaväen, ja meni Aleksanderia vastaan, ajamaan häntä pois."],[10,3,"Sentähden kirjoitti Demetrius Jonatanille, ja sanoi hänelle, että hän tahtoi pitää rauhan hänen kanssansa ja tehdä hänelle kaikkea hyvää.","Sentähden kirjoitti Demetrius Jonatanille, ja sanoi hänelle, että hän tahtoi pitää rauhan hänen kanssansa ja tehdä hänelle kaikkea hyvää."],[10,4,"Sillä hän ajatteli: se on parempi, että minä vedän hänen minun tyköni, ennenkuin hän menee Aleksanderin puolelle minua vastaan,","Sillä hän ajatteli: se on parempi, että minä vedän hänen minun tyköni, ennenkuin hän menee Aleksanderin puolelle minua vastaan,"],[10,5,"Että minä tapoin hänen veljensä, ja hänelle ja hänen kansallensa paljon pahaa tehnyt olen.","Että minä tapoin hänen veljensä, ja hänelle ja hänen kansallensa paljon pahaa tehnyt olen."],[10,6,"Ja Demetrius kirjoitti Jonatanille ja antoi hänelle luvan ottaa ylös ja pitää sotaväkeä, ja tehdä sota-aseita, ja että hän hänen liittoveljensä piti oleman, ja käski, että Jonatanille piti annettaman ne panttivangit jälleen irralle, jotka linnassa olivat.","Ja Demetrius kirjoitti Jonatanille ja antoi hänelle luvan ottaa ylös ja pitää sotaväkeä, ja tehdä sota-aseita, ja että hän hänen liittoveljensä piti oleman, ja käski, että Jonatanille piti annettaman ne panttivangit jälleen irralle, jotka linnassa olivat."],[10,7,"Sentähden tuli Jonatan Jerusalemiin, ja antoi lukea tämän kirjan kaiken kansan edessä ja niiden edessä, jotka linnassa olivat.","Sentähden tuli Jonatan Jerusalemiin, ja antoi lukea tämän kirjan kaiken kansan edessä ja niiden edessä, jotka linnassa olivat."],[10,8,"Knin he nyt kuulivat, että kuningas hänelle antoi luvan ja vallan ottaa sotaväkeä, ja tehdä sota-aseita, ja että kuningas piti hänen liittoveljenä, pelkäsivät he häntä sangen suuresti,","Knin he nyt kuulivat, että kuningas hänelle antoi luvan ja vallan ottaa sotaväkeä, ja tehdä sota-aseita, ja että kuningas piti hänen liittoveljenä, pelkäsivät he häntä sangen suuresti,"],[10,9,"Ja antoivat hänelle panttivangit irralle, ja Jonatan antoi ne jälleen heidän vanhimmillensa.","Ja antoivat hänelle panttivangit irralle, ja Jonatan antoi ne jälleen heidän vanhimmillensa."],[10,10,"Näin rupesi Jonatan asumaan Jerusalemissa, ja rakentamaan ja parantamaan kaupunkia,","Näin rupesi Jonatan asumaan Jerusalemissa, ja rakentamaan ja parantamaan kaupunkia,"],[10,11,"Ja antoi rakentaa muurit ja vahvistaa Zionin vuoren hyvillä vahvoilla muureilla, kaikki hakatuista kivistä.","Ja antoi rakentaa muurit ja vahvistaa Zionin vuoren hyvillä vahvoilla muureilla, kaikki hakatuista kivistä."],[10,12,"Näin tuli Jerusalem jälleen vahvaksi raketuksi,","Näin tuli Jerusalem jälleen vahvaksi raketuksi,"],[10,13,"Ja pakanat vähistä kaupungeista, jotka Bakkides oli antanut vahvaksi tehdä, pakenivat pois omalle maallensa;","Ja pakanat vähistä kaupungeista, jotka Bakkides oli antanut vahvaksi tehdä, pakenivat pois omalle maallensa;"],[10,14,"Mutta pitivät ainoastaan Betsuran, ja ne luopuneet juoksivat sinne; sillä se oli heidän asuinsiansa.","Mutta pitivät ainoastaan Betsuran, ja ne luopuneet juoksivat sinne; sillä se oli heidän asuinsiansa."],[10,15,"Koska Aleksander ymmärsi, että Demetrius pyysi ystävyyttä pitää Jonatanin kanssa, ja kuuli ne kiitettävät työt, jotka Jonatan ja hänen veljensä tehneet olivat, sanoi hän:","Koska Aleksander ymmärsi, että Demetrius pyysi ystävyyttä pitää Jonatanin kanssa, ja kuuli ne kiitettävät työt, jotka Jonatan ja hänen veljensä tehneet olivat, sanoi hän:"],[10,16,"Senkaltaista jaloa miestä emme taida löytää; sen tähden tahdomme me kirjoittaa hänen tykönsä, että hän meidän ystävämme ja liittoveljemme oleman pitää.","Senkaltaista jaloa miestä emme taida löytää; sen tähden tahdomme me kirjoittaa hänen tykönsä, että hän meidän ystävämme ja liittoveljemme oleman pitää."],[10,17,"Ja kirjoitti näin:","Ja kirjoitti näin:"],[10,18,"Kuningas Aleksander toivottaa veljellensä Jonatanille terveyttä!","Kuningas Aleksander toivottaa veljellensä Jonatanille terveyttä!"],[10,19,"Me kuulemme sinua ylistettävän voimalliseksi mieheksi ja mahdolliseksi meidän ystävyyteemme;","Me kuulemme sinua ylistettävän voimalliseksi mieheksi ja mahdolliseksi meidän ystävyyteemme;"],[10,20,"Sentähden asetamme me sinun kansas ylimmäiseksi papiksi, ja sinä pitää kutsuttaman kuninkaan ystäväksi, ja nyt lähetämme me sinulle purpuravaatteen ja kultaisen kruunun, sentähden pidä uskollisesti meidän kanssamme ja ole meidän ystävämme.","Sentähden asetamme me sinun kansas ylimmäiseksi papiksi, ja sinä pitää kutsuttaman kuninkaan ystäväksi, ja nyt lähetämme me sinulle purpuravaatteen ja kultaisen kruunun, sentähden pidä uskollisesti meidän kanssamme ja ole meidän ystävämme."],[10,21,"Ja niin puki Jonatan päällensä papin vaatteet, kuudentenakymmenentenä vuotena toista sataa, seitsemännellä kuukaudella, lehtimajan juhlapäivänä, ja kokosi sotajoukon ja antoi tehdä paljon sota-aseita.","Ja niin puki Jonatan päällensä papin vaatteet, kuudentenakymmenentenä vuotena toista sataa, seitsemännellä kuukaudella, lehtimajan juhlapäivänä, ja kokosi sotajoukon ja antoi tehdä paljon sota-aseita."],[10,22,"Mutta kun Demetrius tämän ymmärsi, tuli hän sangen surulliseksi,","Mutta kun Demetrius tämän ymmärsi, tuli hän sangen surulliseksi,"],[10,23,"Että Aleksander häneltä Juudalaiset väänsi pois tykönsä ja sen kautta tuli voimallisemmaksi;","Että Aleksander häneltä Juudalaiset väänsi pois tykönsä ja sen kautta tuli voimallisemmaksi;"],[10,24,"Ja ajatteli hän myös ystävällisesti kirjoittaa heidän tykönsä, ja kunniaa ja tavaraa luvata, että heidän piti hänelle apua lupaaman.","Ja ajatteli hän myös ystävällisesti kirjoittaa heidän tykönsä, ja kunniaa ja tavaraa luvata, että heidän piti hänelle apua lupaaman."],[10,25,"Ja kirjoitti näin:","Ja kirjoitti näin:"],[10,26,"Kuningas Demetrius toivottaa Juudalaisille terveyttä!","Kuningas Demetrius toivottaa Juudalaisille terveyttä!"],[10,27,"Me olemme mielellämme kuulleet Ja siitä iloinneet, ettette meistä luovu meidän vihollistemme puolelle, vaan kaikella uskollisuudella meidän kanssamme pidätte.","Me olemme mielellämme kuulleet Ja siitä iloinneet, ettette meistä luovu meidän vihollistemme puolelle, vaan kaikella uskollisuudella meidän kanssamme pidätte."],[10,28,"Sentähden rukoilemme me, että te vielä nyt niin tästedes tahtoisitte meille uskolliset olla, Ja ei antaa vääntää teitänne pois meidän puoleltamme.","Sentähden rukoilemme me, että te vielä nyt niin tästedes tahtoisitte meille uskolliset olla, Ja ei antaa vääntää teitänne pois meidän puoleltamme."],[10,29,"Tämän teidän uskollisuutenne me tahdomme maksaa, ja keventää teiltä monet taakat ja antaa enempi vapautta, ja armoa tehdä.","Tämän teidän uskollisuutenne me tahdomme maksaa, ja keventää teiltä monet taakat ja antaa enempi vapautta, ja armoa tehdä."],[10,30,"Ja nyt minä annan kaikille Juudalaisille veron vapaaksi, suolatullin, kruunun teon, kolmannen mitan jyvistä ja puolen kaikkinaisesta puiden hedelmästä, joka minulle tulis; tämän kuorman alta pitää tästedes Juudan maa ja ne kolme kihlakuntaa, jotka siihen lisätyt ovat Samariasta ja Galileasta, aina vapaat oleman;","Ja nyt minä annan kaikille Juudalaisille veron vapaaksi, suolatullin, kruunun teon, kolmannen mitan jyvistä ja puolen kaikkinaisesta puiden hedelmästä, joka minulle tulis; tämän kuorman alta pitää tästedes Juudan maa ja ne kolme kihlakuntaa, jotka siihen lisätyt ovat Samariasta ja Galileasta, aina vapaat oleman;"],[10,31,"Ja Jerusalem pitää pyhä ja vapaa oleman kaikesta rasituksesta, verosta ja kymmenyksistä.","Ja Jerusalem pitää pyhä ja vapaa oleman kaikesta rasituksesta, verosta ja kymmenyksistä."],[10,32,"Minä tahdon myös Jerusalemin linnan teille jälleen avata ja ylimmäisen papin haltuun antaa, että hänen pitää sen saaman ja pitää paneman väkeä sinne, jotka hän tahtoo sitä varjelemaan.","Minä tahdon myös Jerusalemin linnan teille jälleen avata ja ylimmäisen papin haltuun antaa, että hänen pitää sen saaman ja pitää paneman väkeä sinne, jotka hän tahtoo sitä varjelemaan."],[10,33,"Ja kaikki ne Juudalaiset, jotka minun valtakunnassani vankina ovat, pitää vallallensa annettaman, ja vapaat oleman, ja he ja heidän karjansa pitää verosta vapaat oleman.","Ja kaikki ne Juudalaiset, jotka minun valtakunnassani vankina ovat, pitää vallallensa annettaman, ja vapaat oleman, ja he ja heidän karjansa pitää verosta vapaat oleman."],[10,34,"Ja pitää heille vapaus oleman, kaikessa minun valtakunnassani pitää heidän sabbatinsa, uudet kuunsa ja muut määrätyt pyhäpäivät,","Ja pitää heille vapaus oleman, kaikessa minun valtakunnassani pitää heidän sabbatinsa, uudet kuunsa ja muut määrätyt pyhäpäivät,"],[10,35,"Ja kolme päivää sekä edellä että jälkeen juhlapäivän, joka mieheltä estämättä oleman heidän jumalan palveluksessansa,","Ja kolme päivää sekä edellä että jälkeen juhlapäivän, joka mieheltä estämättä oleman heidän jumalan palveluksessansa,"],[10,36,"Ja pitää kolmekymmentä tuhatta miestä Juudeassa valittaman, niin minä tahdon palkan antaa, niinkuin muillekin minun sotaväelleni, ja ne pitää kuninkaan vahvoihin kaupunkeihin asetettaman.","Ja pitää kolmekymmentä tuhatta miestä Juudeassa valittaman, niin minä tahdon palkan antaa, niinkuin muillekin minun sotaväelleni, ja ne pitää kuninkaan vahvoihin kaupunkeihin asetettaman."],[10,37,"Ja niistä pitää muutamat valittaman, jotka kuninkaalle hänen korkeimmissa asioissansa niinkuin hänen hyvin uskotut neuvonantajansa oleman pitää. Ei pidä myös Juudalaisilla yhtään muukalaista, vaan omasta kansasta vapaat päämiehet oleman, että he lakinsa pitäisivät, niinkuin Juudankin maalla.","Ja niistä pitää muutamat valittaman, jotka kuninkaalle hänen korkeimmissa asioissansa niinkuin hänen hyvin uskotut neuvonantajansa oleman pitää. Ei pidä myös Juudalaisilla yhtään muukalaista, vaan omasta kansasta vapaat päämiehet oleman, että he lakinsa pitäisivät, niinkuin Juudankin maalla."],[10,38,"Ja ne kolme kihlakuntaa Samarian maassa ja Galileassa, jotka Juudean omat ovat, ei pidä yhdenkään alle annetut oleman, vaan ainoastaan ylimmäisen papin, että se tiettävä olis, että hän yksinänsä sen herra on.","Ja ne kolme kihlakuntaa Samarian maassa ja Galileassa, jotka Juudean omat ovat, ei pidä yhdenkään alle annetut oleman, vaan ainoastaan ylimmäisen papin, että se tiettävä olis, että hän yksinänsä sen herra on."],[10,39,"Ptolomain kaupungin ja ne maakunnat ympärillä, jotka siihen tulevat, annan minä Jerusalemin templin, siihen kulutukseen kuin uhriin tarvitaan.","Ptolomain kaupungin ja ne maakunnat ympärillä, jotka siihen tulevat, annan minä Jerusalemin templin, siihen kulutukseen kuin uhriin tarvitaan."],[10,40,"Ja tahdon myös toimittaa templin rakennukseen joka vuosi viisitoistakymmentä tuhatta sikliä hopiaa minun omastani.","Ja tahdon myös toimittaa templin rakennukseen joka vuosi viisitoistakymmentä tuhatta sikliä hopiaa minun omastani."],[10,41,"Ja mitä minä vanhasta minun virkani puolesta olen velkapää ollut antamaan templiin, se pitää tästedes myös annettaman.","Ja mitä minä vanhasta minun virkani puolesta olen velkapää ollut antamaan templiin, se pitää tästedes myös annettaman."],[10,42,"Ja ne viisituhatta sikliä hopiaa, jotka minun virkamieheni templin ylöskannosta ovat ottaneet pois, ne pitää taas vuosi vuodelta pappein omat oleman.","Ja ne viisituhatta sikliä hopiaa, jotka minun virkamieheni templin ylöskannosta ovat ottaneet pois, ne pitää taas vuosi vuodelta pappein omat oleman."],[10,43,"Ja pitää templillä tämä vapaus oleman, että kaikessa minun valtakunnassani joka jonkun rangaistuksen ansainnut on, ja pakenee templiin, hänen pitää siellä murheetoin oleman henkensä ja tavaransa puolesta.","Ja pitää templillä tämä vapaus oleman, että kaikessa minun valtakunnassani joka jonkun rangaistuksen ansainnut on, ja pakenee templiin, hänen pitää siellä murheetoin oleman henkensä ja tavaransa puolesta."],[10,44,"Templin rakennukseen, ja muurien ja tornien parannukseen Jerusalemissa","Templin rakennukseen, ja muurien ja tornien parannukseen Jerusalemissa"],[10,45,"Ja muualla maassa tahtoo kuningas myös omasta otostansa kulutuksen antaa.","Ja muualla maassa tahtoo kuningas myös omasta otostansa kulutuksen antaa."],[10,46,"Mutta kuin tämä kirja luettiin Jonatanin ja kansan edessä, ei he tahtoneet uskoa häntä, eikä siitä tietävinänsä olleet, sillä he tiesivät hyvin, minkä kaltaisen petoksen ja hirmuisen hirmuval-taisuuden hän ennen Israelia vastaan tehnyt oli.","Mutta kuin tämä kirja luettiin Jonatanin ja kansan edessä, ei he tahtoneet uskoa häntä, eikä siitä tietävinänsä olleet, sillä he tiesivät hyvin, minkä kaltaisen petoksen ja hirmuisen hirmuval-taisuuden hän ennen Israelia vastaan tehnyt oli."],[10,47,"Ja päättivät tehdäksensä apua Aleksanderille, Joka ennen jo ystävyyttä heiltä anoi, ja rauhan luvannut oli; häntä he auttivat joka aika.","Ja päättivät tehdäksensä apua Aleksanderille, Joka ennen jo ystävyyttä heiltä anoi, ja rauhan luvannut oli; häntä he auttivat joka aika."],[10,48,"Kuin nyt Aleksander ja Demetrius toinen toistansa vastaan menivät tappelemaan,","Kuin nyt Aleksander ja Demetrius toinen toistansa vastaan menivät tappelemaan,"],[10,49,"Niin pakeni Demetriuksen sotaväki, ja Aleksander kiiruhti heidän jälkeensä,","Niin pakeni Demetriuksen sotaväki, ja Aleksander kiiruhti heidän jälkeensä,"],[10,50,"Ja teki hirmuisen verenvuodatuksen huomenesta hamaan ehtoosen asti, ja Demetrius tuli lyödyksi sinä päivänä.","Ja teki hirmuisen verenvuodatuksen huomenesta hamaan ehtoosen asti, ja Demetrius tuli lyödyksi sinä päivänä."],[10,51,"Senjälkeen lähetti Aleksander sanan Egyptin kuninkaan Ptolomeuksen tykö, tämän asian kanssa:","Senjälkeen lähetti Aleksander sanan Egyptin kuninkaan Ptolomeuksen tykö, tämän asian kanssa:"],[10,52,"Että minä olen tullut minun valtakuntaani jälleen, ja istun kuninkaallisella istuimella, ja olen saanut hallituksen ja olen karkottanut Demetriuksen, ja perintömaani voittanut;","Että minä olen tullut minun valtakuntaani jälleen, ja istun kuninkaallisella istuimella, ja olen saanut hallituksen ja olen karkottanut Demetriuksen, ja perintömaani voittanut;"],[10,53,"Niin minä pyydän sinulta ystävyyttä, ja rukoilen sinua, että sinä tahtoisit antaa tyttäres minulle avioksi:","Niin minä pyydän sinulta ystävyyttä, ja rukoilen sinua, että sinä tahtoisit antaa tyttäres minulle avioksi:"],[10,54,"Niin minä tahdon olla sinua kohtaan niinkuin vävyn tulee, ja kiitollinen olla, ja antaa hänelle kuninkaallisen huomenlahjan.","Niin minä tahdon olla sinua kohtaan niinkuin vävyn tulee, ja kiitollinen olla, ja antaa hänelle kuninkaallisen huomenlahjan."],[10,55,"Siihen vastasi Ptolomeus, ja toivotti Aleksanderille onnea, että hän isänsä maalle jälleen tullut ja valtakuntansa voittanut oli,","Siihen vastasi Ptolomeus, ja toivotti Aleksanderille onnea, että hän isänsä maalle jälleen tullut ja valtakuntansa voittanut oli,"],[10,56,"Ja lupasi hänelle niin tehdä kuin hän kirjoittanut oli, ja käski hänen tulla tykönsä Ptolomaidiin; siellä he tahtoivat keskenänsä toinen toistansa puhutella ja sen naimisen päättää.","Ja lupasi hänelle niin tehdä kuin hän kirjoittanut oli, ja käski hänen tulla tykönsä Ptolomaidiin; siellä he tahtoivat keskenänsä toinen toistansa puhutella ja sen naimisen päättää."],[10,57,"Toisena vuonna seitsemättäkymmentä toista sataa vaelsi Ptolomeus tyttärensä Kleopatran kanssa Egyptistä ja tuli Ptolomaidiin.","Toisena vuonna seitsemättäkymmentä toista sataa vaelsi Ptolomeus tyttärensä Kleopatran kanssa Egyptistä ja tuli Ptolomaidiin."],[10,58,"Sinne tuli myös kuningas Aleksander, ja Kleopatra annettiin Aleksanderille, ja häät pidettiin suurella kuninkaallisella koreudella.","Sinne tuli myös kuningas Aleksander, ja Kleopatra annettiin Aleksanderille, ja häät pidettiin suurella kuninkaallisella koreudella."],[10,59,"Ja kuningas Aleksander kirjoitti Jonatanille ja kutsui hänen tykönsä.","Ja kuningas Aleksander kirjoitti Jonatanille ja kutsui hänen tykönsä."],[10,60,"Niin tuli Jonatan suurella kunnialla Ptolomaidiin molempain kuningasten tykö ja lahjoitti heille ja heidän ystävillensä kalliita lahjoja kullasta ja hopiasta, ja sai ystävyyden heiltä.","Niin tuli Jonatan suurella kunnialla Ptolomaidiin molempain kuningasten tykö ja lahjoitti heille ja heidän ystävillensä kalliita lahjoja kullasta ja hopiasta, ja sai ystävyyden heiltä."],[10,61,"Ja muutamat luopuneet Israelista tulivat sinne kantamaan Jonatanin päälle; vaan ei kuningas tahtonut kuulla heitä,","Ja muutamat luopuneet Israelista tulivat sinne kantamaan Jonatanin päälle; vaan ei kuningas tahtonut kuulla heitä,"],[10,62,"Mutta käski Jonatanin panna pois vaatteensa ja pukea purpuravaatteet yllensä, joka myös niin tapahtui.","Mutta käski Jonatanin panna pois vaatteensa ja pukea purpuravaatteet yllensä, joka myös niin tapahtui."],[10,63,"Silloin istutti kuningas hänen sivuunsa, ja antoi käskyn ylimmäisillensä, että he hänen kanssansa ympäri kaupunkia käymän piti ja kuuluttaman, ettei kenenkään pitänyt kantaman hänen päällensä, taikka muutoin häntä vaivaaman.","Silloin istutti kuningas hänen sivuunsa, ja antoi käskyn ylimmäisillensä, että he hänen kanssansa ympäri kaupunkia käymän piti ja kuuluttaman, ettei kenenkään pitänyt kantaman hänen päällensä, taikka muutoin häntä vaivaaman."],[10,64,"Mutta koska hänen päällekantajansa näkivät, että kuningas häntä niin korkiasti kunnioitti, sekä purpuralla että tällä kuulutuksella, niin pakenivat he kaikki matkaansa.","Mutta koska hänen päällekantajansa näkivät, että kuningas häntä niin korkiasti kunnioitti, sekä purpuralla että tällä kuulutuksella, niin pakenivat he kaikki matkaansa."],[10,65,"Ja kuningas teki hänelle suuren kunnian, ja antoi kirjoittaa hänen ylimmäisten ystäviensä sekaan, ja teki hänen päämieheksi ja lähimmäiseksi neuvonantajaksensa.","Ja kuningas teki hänelle suuren kunnian, ja antoi kirjoittaa hänen ylimmäisten ystäviensä sekaan, ja teki hänen päämieheksi ja lähimmäiseksi neuvonantajaksensa."],[10,66,"Sitte vaelsi Jonatan jälleen Jerusalemiin ilolla ja hyvässä rauhassa.","Sitte vaelsi Jonatan jälleen Jerusalemiin ilolla ja hyvässä rauhassa."],[10,67,"Viidennellä vuodella seitsemättäkymmentä toista sataa tuli kuningas Demetrius, entisen Demetriuksen poika Kretasta perintövaltaansa.","Viidennellä vuodella seitsemättäkymmentä toista sataa tuli kuningas Demetrius, entisen Demetriuksen poika Kretasta perintövaltaansa."],[10,68,"Silloin Aleksander peräti suuresti hämmästyi, ja tuli Antiokiaan,","Silloin Aleksander peräti suuresti hämmästyi, ja tuli Antiokiaan,"],[10,69,"Mutta Demetrius saatti Apolloniuksen, joka olI päämies alimmaisessa Syriassa, puolellensa; hän kokosi sotajoukon, ja tuli Jamniaan, ja lähetti Jonatanin ylimmäisen papin tykö, ja antoi sanoa hänelle:","Mutta Demetrius saatti Apolloniuksen, joka olI päämies alimmaisessa Syriassa, puolellensa; hän kokosi sotajoukon, ja tuli Jamniaan, ja lähetti Jonatanin ylimmäisen papin tykö, ja antoi sanoa hänelle:"],[10,70,"Ei yksikään tee meille vastusta, vaan sinä ainoa, ja saatat sen, että minä katsotaan ylön.","Ei yksikään tee meille vastusta, vaan sinä ainoa, ja saatat sen, että minä katsotaan ylön."],[10,71,"Sinä olet röyhkeä vuorilla; mutta jos sinä tahdot urhoollisen työn tehdä, niin tule alas lakialle kedolle, siinä koetelkaamme toinen toistamme.","Sinä olet röyhkeä vuorilla; mutta jos sinä tahdot urhoollisen työn tehdä, niin tule alas lakialle kedolle, siinä koetelkaamme toinen toistamme."],[10,72,"Jos sinä tahdot kysyä, kuinka vahvat me olemme, minä ja ne muut, jotka minua seuraavat ja minua auttavat, niin pitää sinulle sanottaman: ette taida seisovaiset olla tämän kansan edessä, joilta teidän isänne kahdesti lyödyt ovat omassa maassansa:","Jos sinä tahdot kysyä, kuinka vahvat me olemme, minä ja ne muut, jotka minua seuraavat ja minua auttavat, niin pitää sinulle sanottaman: ette taida seisovaiset olla tämän kansan edessä, joilta teidän isänne kahdesti lyödyt ovat omassa maassansa:"],[10,73,"Paljoa vähemmin taidat sinä lakialla kedolla senkaltaisen väkevän kansan edessä sekä hevosmiehistä että jalkamiehistä seisovainen olla, siinä paikassa, jossa ei yhtään vuorta eikä vahaa ole, joiden varjoon joku paeta taitais.","Paljoa vähemmin taidat sinä lakialla kedolla senkaltaisen väkevän kansan edessä sekä hevosmiehistä että jalkamiehistä seisovainen olla, siinä paikassa, jossa ei yhtään vuorta eikä vahaa ole, joiden varjoon joku paeta taitais."],[10,74,"Kuin Jonatan senkaltaisen kerskauksen kuuli, vihastui hän, ja valitsi kymmenentuhatta miestä, ja läksi Jerusalemista, tuli myös hänen tykönsä Simon, hänen veljensä, auttamaan häntä, ja sioittivat itsensä Jopen eteen.","Kuin Jonatan senkaltaisen kerskauksen kuuli, vihastui hän, ja valitsi kymmenentuhatta miestä, ja läksi Jerusalemista, tuli myös hänen tykönsä Simon, hänen veljensä, auttamaan häntä, ja sioittivat itsensä Jopen eteen."],[10,75,"Mutta Jopen kaupungin asuvaiset ei päästäneet heitä sisälle, sillä Apollonius oli pannut siihen väkeä varjelukseksi; sentähden Jonatan karkasi heidän päällensä väkirynnäköllä.","Mutta Jopen kaupungin asuvaiset ei päästäneet heitä sisälle, sillä Apollonius oli pannut siihen väkeä varjelukseksi; sentähden Jonatan karkasi heidän päällensä väkirynnäköllä."],[10,76,"Ja kaupunkilaiset peljästyivät ja avasivat portit. Näin sai Jonatan Jopen kaupungin.","Ja kaupunkilaiset peljästyivät ja avasivat portit. Näin sai Jonatan Jopen kaupungin."],[10,77,"Kuin Apollonius tämän kuuli, asetti hän itsensä Jopen eteen kolmellatuhannella hevosmiehellä ja paljolla jalkaväellä, ja teeskeli itsensä niinkuin hän olis tahtonut vaeltaa Asdodiin, että hän olis houkutellut Jonatanin ulos väljälle; sillä hänellä oli suuri joukko hevosväkeä, joihin hän uskalsi.","Kuin Apollonius tämän kuuli, asetti hän itsensä Jopen eteen kolmellatuhannella hevosmiehellä ja paljolla jalkaväellä, ja teeskeli itsensä niinkuin hän olis tahtonut vaeltaa Asdodiin, että hän olis houkutellut Jonatanin ulos väljälle; sillä hänellä oli suuri joukko hevosväkeä, joihin hän uskalsi."],[10,78,"Jonatan riensi hänen perässänsä Asdodiin, ja vaelsi kukin joukko järjestyksessänsä, valmiina tappelemaan.","Jonatan riensi hänen perässänsä Asdodiin, ja vaelsi kukin joukko järjestyksessänsä, valmiina tappelemaan."],[10,79,"Mutta Apollonius oli salaisesti jättänyt leiriin tuhannen ratsasmiestä.","Mutta Apollonius oli salaisesti jättänyt leiriin tuhannen ratsasmiestä."],[10,80,"Niin ymmärsi Jonatan, että väki oli salattuna hänen takanansa;","Niin ymmärsi Jonatan, että väki oli salattuna hänen takanansa;"],[10,81,"Sentähden kuin ne hänen väkeänsä lähenivät, pidätti Jonatan joukkonsa niinkuin hän oli heidät sioittanut. Silloin ampuivat ratsasmiehet väen päälle koko sen päivän, huomenesta niin ehtoosen, siihen asti että heidän hevosensa väsyivät.","Sentähden kuin ne hänen väkeänsä lähenivät, pidätti Jonatan joukkonsa niinkuin hän oli heidät sioittanut. Silloin ampuivat ratsasmiehet väen päälle koko sen päivän, huomenesta niin ehtoosen, siihen asti että heidän hevosensa väsyivät."],[10,82,"Sitte otti Simon väkensä ja löi vihollisia, niin ratsasmiehet pakenivat; sillä he olivat väsyneet;","Sitte otti Simon väkensä ja löi vihollisia, niin ratsasmiehet pakenivat; sillä he olivat väsyneet;"],[10,83,"Ja tulivat sinne ja tänne väljällä hajoitetuksi, ja pakenivat Asdodiin, ja riensivät epäjumalan Dagonin templiin., että he siellä olisivat pelastaneet henkensä.","Ja tulivat sinne ja tänne väljällä hajoitetuksi, ja pakenivat Asdodiin, ja riensivät epäjumalan Dagonin templiin., että he siellä olisivat pelastaneet henkensä."],[10,84,"Mutta Jonatan hävitti Asdodin kaupungin ja ne kylät ympäriltä, ja poltti ne. Hän poltti myös epäjumalan templin kaikkein niiden kanssa, jotka sinne paenneet olivat.","Mutta Jonatan hävitti Asdodin kaupungin ja ne kylät ympäriltä, ja poltti ne. Hän poltti myös epäjumalan templin kaikkein niiden kanssa, jotka sinne paenneet olivat."],[10,85,"Ja niiden luku, jotka lyödyt ja poltetut olivat, oli yhteen liki kahdeksantuhatta miestä.","Ja niiden luku, jotka lyödyt ja poltetut olivat, oli yhteen liki kahdeksantuhatta miestä."],[10,86,"Senjälkeen vaelsi Jonatan sotaväellä Askalonin tykö ja kauppamiehet läksivät kaupungista häntä vastaan, ja antoivat itsensä, ja ottivat hänet vastaan suurella kunnialla.","Senjälkeen vaelsi Jonatan sotaväellä Askalonin tykö ja kauppamiehet läksivät kaupungista häntä vastaan, ja antoivat itsensä, ja ottivat hänet vastaan suurella kunnialla."],[10,87,"Näin palasi taas Jonatan Jerusalemlin sotaväkensä ja saaliinsa kanssa.","Näin palasi taas Jonatan Jerusalemlin sotaväkensä ja saaliinsa kanssa."],[10,88,"Ja kuin Aleksander nämät kuuli, kunnioitti hän Jonatania vielä suuremmasti,","Ja kuin Aleksander nämät kuuli, kunnioitti hän Jonatania vielä suuremmasti,"],[10,89,"Ja lähetti. hänelle kultaisen vyön, niinkuin tapa on antaa ainoastaan kuningasten langoIle. Siihen myös antoi hän hänelle lahjaksi ja omaksi Akkaronin ja mitä sen alla oli.","Ja lähetti. hänelle kultaisen vyön, niinkuin tapa on antaa ainoastaan kuningasten langoIle. Siihen myös antoi hän hänelle lahjaksi ja omaksi Akkaronin ja mitä sen alla oli."],[11,1,"Ja Egyptin kuningas kokosi väkeä, niin paljon kuin santaa on meren pohjassa, ja paljon haaksia, ja meni Aleksanderin valtakuntaa petoksella saamaan allensa, ja molempia valtakuntia hallitsemaan.","Ja Egyptin kuningas kokosi väkeä, niin paljon kuin santaa on meren pohjassa, ja paljon haaksia, ja meni Aleksanderin valtakuntaa petoksella saamaan allensa, ja molempia valtakuntia hallitsemaan."],[11,2,"Sentähden meni hän Syriaan, ja oli hyvä ystävä olevinansa. Niin avattiin hänen eteensä kaikkein kaupunkein portit, ja käytiin häntä vastaan, ja otettiin kunniallisesti vastaan, niinkuin Aleksander oli käskenyt, että hän oli hänen appensa.","Sentähden meni hän Syriaan, ja oli hyvä ystävä olevinansa. Niin avattiin hänen eteensä kaikkein kaupunkein portit, ja käytiin häntä vastaan, ja otettiin kunniallisesti vastaan, niinkuin Aleksander oli käskenyt, että hän oli hänen appensa."],[11,3,"Mutta kuhunka kaupunkiin Ptolomeus tuli, siihen myös jätti sotajoukon vartiaksi.","Mutta kuhunka kaupunkiin Ptolomeus tuli, siihen myös jätti sotajoukon vartiaksi."],[11,4,"Ja kuin hän Asdodiin tuli, osoittivat he hänelle, kuinka Jonatan Dagonin templin ja kaupungin polttanut ja maahan lyönyt oli, ja kuinka kuolleiden ruumiit siellä ja täällä hajoitettuna makasivat, ja teiden vieriin, suuriin joukkoihin haudatut olivat,","Ja kuin hän Asdodiin tuli, osoittivat he hänelle, kuinka Jonatan Dagonin templin ja kaupungin polttanut ja maahan lyönyt oli, ja kuinka kuolleiden ruumiit siellä ja täällä hajoitettuna makasivat, ja teiden vieriin, suuriin joukkoihin haudatut olivat,"],[11,5,"Ja sanoivat kuninkaalle, että Jonatan sen vahingon oli tehnyt, saattaaksensa häntä kuninkaan vihoihin. Mutta ei kuningas siihen mitään vastannut.","Ja sanoivat kuninkaalle, että Jonatan sen vahingon oli tehnyt, saattaaksensa häntä kuninkaan vihoihin. Mutta ei kuningas siihen mitään vastannut."],[11,6,"Ja Jonatan meni myös kuningasta vastaan Joppeen; siellä he puhuttelivat toinen toistansa, ja olivat yhdessä sen yön.","Ja Jonatan meni myös kuningasta vastaan Joppeen; siellä he puhuttelivat toinen toistansa, ja olivat yhdessä sen yön."],[11,7,"Ja Jonatan seurasi kuningasta hamaan Eleuteruksen virtaan asti, sitten meni hän jälleen Jerusalemiin kotiansa.","Ja Jonatan seurasi kuningasta hamaan Eleuteruksen virtaan asti, sitten meni hän jälleen Jerusalemiin kotiansa."],[11,8,"Ja kuningas Ptolomeus sai kaupungit hamaan Seleukiaan asti, lähes merta, ja ajatteli ajaa Aleksanderia pois,","Ja kuningas Ptolomeus sai kaupungit hamaan Seleukiaan asti, lähes merta, ja ajatteli ajaa Aleksanderia pois,"],[11,9,"Ja lähetti sanan Demetriukselle, että hän tulis hänen tykönsä tekemään liittoa hänen kanssansa ja lupasi hänelle tyttärensä, joka Aleksanderilla oli, lupasi myös auttaa häntä kuninkaaksi,","Ja lähetti sanan Demetriukselle, että hän tulis hänen tykönsä tekemään liittoa hänen kanssansa ja lupasi hänelle tyttärensä, joka Aleksanderilla oli, lupasi myös auttaa häntä kuninkaaksi,"],[11,10,"Ja sanoi katuvansa sitä, että hän Aleksanderille tyttärensä oli antanut;","Ja sanoi katuvansa sitä, että hän Aleksanderille tyttärensä oli antanut;"],[11,11,"Ja sanoi Aleksanderin syyn, hänen seisoneen hänen henkensä ja valtakuntansa jälkeen.","Ja sanoi Aleksanderin syyn, hänen seisoneen hänen henkensä ja valtakuntansa jälkeen."],[11,12,"Ja osoitti vihansa julkisesti, ja eroitti itsensä Aleksanderin ystävyydestä, ja otti häneltä tyttärensä pois, ja antoi Demetriukselle.","Ja osoitti vihansa julkisesti, ja eroitti itsensä Aleksanderin ystävyydestä, ja otti häneltä tyttärensä pois, ja antoi Demetriukselle."],[11,13,"Ja kuin Ptolomeus tuli Antiokiaan, pani hän molemmat kruunut päähänsä sekä Egyptin että Asian kruunun.","Ja kuin Ptolomeus tuli Antiokiaan, pani hän molemmat kruunut päähänsä sekä Egyptin että Asian kruunun."],[11,14,"Mutta kuningas Aleksander oli siihen aikaan Kilikiassa; sillä muutamat kaupungit olivat siellä hänestä erinneet.","Mutta kuningas Aleksander oli siihen aikaan Kilikiassa; sillä muutamat kaupungit olivat siellä hänestä erinneet."],[11,15,"Kuin hän sai kuulla Ptolomeuksesta, meni hän häntä vastaan sotimaan hänen kanssansa; mutta Ptolomeus oli paremmin varustettu, ja meni häntä vastaan ja ajoi hänen pois.","Kuin hän sai kuulla Ptolomeuksesta, meni hän häntä vastaan sotimaan hänen kanssansa; mutta Ptolomeus oli paremmin varustettu, ja meni häntä vastaan ja ajoi hänen pois."],[11,16,"Ja Aleksander pakeni Arabiaan, että hän siellä olis saanut rauhassa olla, mutta kuningas Ptolomeus oli sangen voimallinen.","Ja Aleksander pakeni Arabiaan, että hän siellä olis saanut rauhassa olla, mutta kuningas Ptolomeus oli sangen voimallinen."],[11,17,"Sentähden antoi Zabdiel Arabiasta vieraansa Aleksanderin pään hakata pois, ja lähetti sen kuningas Ptolomeukselle.","Sentähden antoi Zabdiel Arabiasta vieraansa Aleksanderin pään hakata pois, ja lähetti sen kuningas Ptolomeukselle."],[11,18,"Ptolomeus kuoli kolmantena päivänä sen jälkeen; silloin myös ne sotamiehet, jotka Ptolomeus oli asettanut kaupunkeihin, tapettiin niiltä, jotka kaupungeissa asuivat.","Ptolomeus kuoli kolmantena päivänä sen jälkeen; silloin myös ne sotamiehet, jotka Ptolomeus oli asettanut kaupunkeihin, tapettiin niiltä, jotka kaupungeissa asuivat."],[11,19,"Näin sai Demetrius valtakunnan, seitsemäntenä vuotena seitsemättäkymmentä toista sataa.","Näin sai Demetrius valtakunnan, seitsemäntenä vuotena seitsemättäkymmentä toista sataa."],[11,20,"Siihen aikaan kokosi Jonatan väkensä Juudean maalla, omistaaksensa Jerusalemin linnaa jälleen, ja antoi sen eteen panna rakennukset ja sota-aseet.","Siihen aikaan kokosi Jonatan väkensä Juudean maalla, omistaaksensa Jerusalemin linnaa jälleen, ja antoi sen eteen panna rakennukset ja sota-aseet."],[11,21,"Niin muutamat luopuneista menivät kuningas Demetriuksen tykö, ja kantoivat Jonatanin päälle, ja sanoivat, että hän oli linnan piirittänyt.","Niin muutamat luopuneista menivät kuningas Demetriuksen tykö, ja kantoivat Jonatanin päälle, ja sanoivat, että hän oli linnan piirittänyt."],[11,22,"Silloin vihastui kuningas suuresti ja meni kiiruusti Ptolomaidiin, ja kirjoitti Jonatanille, ettei hän linnaa olisi ahdistanut, mutta kohta tullut hänen tykönsä Ptolomaidiin; siellä hän tahtoi häntä muutamista asioista puhutella.","Silloin vihastui kuningas suuresti ja meni kiiruusti Ptolomaidiin, ja kirjoitti Jonatanille, ettei hän linnaa olisi ahdistanut, mutta kohta tullut hänen tykönsä Ptolomaidiin; siellä hän tahtoi häntä muutamista asioista puhutella."],[11,23,"Mutta kuin tämä sana tuli Jonatanille, antoi hän linnan olla piiritettynä, ja valitsi muutamia vanhimmista Israelissa ja papeista, jotka häntä seuraaman piti, ja nousi ja antoi itsensä hengenvaaraan,","Mutta kuin tämä sana tuli Jonatanille, antoi hän linnan olla piiritettynä, ja valitsi muutamia vanhimmista Israelissa ja papeista, jotka häntä seuraaman piti, ja nousi ja antoi itsensä hengenvaaraan,"],[11,24,"Ja otti monta kallista kappaletta myötänsä, kullasta, hopiasta ja vaatteista, ja meni Ptolomaidiin kuninkaan tykö, ja löysi armon ja ystävyyden hänen tykönänsä.","Ja otti monta kallista kappaletta myötänsä, kullasta, hopiasta ja vaatteista, ja meni Ptolomaidiin kuninkaan tykö, ja löysi armon ja ystävyyden hänen tykönänsä."],[11,25,"Kuin siis ne, jotka hänen kansastansa luopuneet olivat, kantelivat hänen päällensä,","Kuin siis ne, jotka hänen kansastansa luopuneet olivat, kantelivat hänen päällensä,"],[11,26,"Piti kuningas hänen kunniassa, niinkuin hän myös ennenkin pidetty oli, ja teki hänelle suuren kunnian kaikkein päämiestensä edessä,","Piti kuningas hänen kunniassa, niinkuin hän myös ennenkin pidetty oli, ja teki hänelle suuren kunnian kaikkein päämiestensä edessä,"],[11,27,"Ja vahvisti hänen ylimmäisen papin virkaan ja kaikkinaiseen muuhun kunniaan, joka hänellä siihen päivään asti oli ollut, ja piti hänen ylimmäisenä ystävänänsä.","Ja vahvisti hänen ylimmäisen papin virkaan ja kaikkinaiseen muuhun kunniaan, joka hänellä siihen päivään asti oli ollut, ja piti hänen ylimmäisenä ystävänänsä."],[11,28,"Jonatan rukoili myös kuningasta, että hän kaiken Juudean ja ne kolme kihlakuntaa Samariassa ja Galileassa olis antanut verotoinna olla, ja lupasi hänelle sen vapauden edestä kolmesataa leiviskää kultaa.","Jonatan rukoili myös kuningasta, että hän kaiken Juudean ja ne kolme kihlakuntaa Samariassa ja Galileassa olis antanut verotoinna olla, ja lupasi hänelle sen vapauden edestä kolmesataa leiviskää kultaa."],[11,29,"Se kelpasi kuninkaalle, ja antoi Jonatanille kirjan näin:","Se kelpasi kuninkaalle, ja antoi Jonatanille kirjan näin:"],[11,30,"Kuningas Demetrius toivottaa veljellensä Jonatanille ja Juudan kansalle terveyttä!","Kuningas Demetrius toivottaa veljellensä Jonatanille ja Juudan kansalle terveyttä!"],[11,31,"Me lähetämme teille kopion, kirjasta, jonka me isällemme Lastenekselle teidän tähtenne kirjoittaneet olemme, että teidän sen tietämän pitää.","Me lähetämme teille kopion, kirjasta, jonka me isällemme Lastenekselle teidän tähtenne kirjoittaneet olemme, että teidän sen tietämän pitää."],[11,32,"Kuningas Demetrius toivottaa isällensä Laskenekselle terveyttä!","Kuningas Demetrius toivottaa isällensä Laskenekselle terveyttä!"],[11,33,"Me olemme ajatelleet ystävillemme ja uskollisille liittoveljillemme Juudalaisille tehdä hyvää, heidän uskollisen ystävyytensä tähden meitä kohtaan.","Me olemme ajatelleet ystävillemme ja uskollisille liittoveljillemme Juudalaisille tehdä hyvää, heidän uskollisen ystävyytensä tähden meitä kohtaan."],[11,34,"Sentähden me asetamme, että papit Jerusalemissa kaiken Juudean ja ne kolme kaupunkia, Aphereman, Lyddan ja Raman, jotka Samariasta ovat Juudean tykö pantu, rajoinensa pitää omistaman.","Sentähden me asetamme, että papit Jerusalemissa kaiken Juudean ja ne kolme kaupunkia, Aphereman, Lyddan ja Raman, jotka Samariasta ovat Juudean tykö pantu, rajoinensa pitää omistaman."],[11,35,"Me teemme heidät myös vapaaksi kaikesta siitä, minkä heidän ennen piti kuninkaalle joka vuosi antaman: jyvistä, hedelmistä, kymmenyksistä, veroista, suolatullista ja muista kruunun teoista.","Me teemme heidät myös vapaaksi kaikesta siitä, minkä heidän ennen piti kuninkaalle joka vuosi antaman: jyvistä, hedelmistä, kymmenyksistä, veroista, suolatullista ja muista kruunun teoista."],[11,36,"Näistä kaikista pitää heidän tästedes vapaat oleman; ja senkaltainen vapaus pitää heille vahvana ja lujana pidettämän.","Näistä kaikista pitää heidän tästedes vapaat oleman; ja senkaltainen vapaus pitää heille vahvana ja lujana pidettämän."],[11,37,"Tämän kaltainen kirja pitää annettaman Jonatanille, jonka hänen pitää paneman pyhälle vuorelle kunnialliseen ja julkiseen siaan.","Tämän kaltainen kirja pitää annettaman Jonatanille, jonka hänen pitää paneman pyhälle vuorelle kunnialliseen ja julkiseen siaan."],[11,38,"Koska kuningas Demetrius näki, että kaikessa valtakunnassa rauha oli, ja ettei yksikään enää asettanut itsiänsä häntä vastaan, päästi hän kaiken oman maan sotaväen menemään kunkin majoillensa. Mutta muukalaisen sotaväen, jonka hän pakanoilta luodoista ottanut oli, piti hän tykönänsä, jonka tähden myös oman maakunnan sotaväki häntä suuresti vihasi.","Koska kuningas Demetrius näki, että kaikessa valtakunnassa rauha oli, ja ettei yksikään enää asettanut itsiänsä häntä vastaan, päästi hän kaiken oman maan sotaväen menemään kunkin majoillensa. Mutta muukalaisen sotaväen, jonka hän pakanoilta luodoista ottanut oli, piti hän tykönänsä, jonka tähden myös oman maakunnan sotaväki häntä suuresti vihasi."],[11,39,"Mutta kuin Tryphon, yksi päämiehistä, joka muinen Aleksanderin ystävä oli ollut, näki, että sotaväki kuningas Demetriusta vihasi, meni hän Emalkuelin Arabialaisen tykö, joka nuoren Antiokuksen, Aleksanderin pojan, kasvattanut oli.","Mutta kuin Tryphon, yksi päämiehistä, joka muinen Aleksanderin ystävä oli ollut, näki, että sotaväki kuningas Demetriusta vihasi, meni hän Emalkuelin Arabialaisen tykö, joka nuoren Antiokuksen, Aleksanderin pojan, kasvattanut oli."],[11,40,"Sitä hän neuvoi antamaan nuorukaista hänen haltuunsa, ja lupasi asettaa hänen isänsä valtakuntaan jälleen. Ja jutteli Arabialaiselle, kuinka ja minkätähden sotaväki rupesi vihaamaan kuningas Demetriusta, ja niin viipyi hän Arabialaisen tykönä kauvan aikaa.","Sitä hän neuvoi antamaan nuorukaista hänen haltuunsa, ja lupasi asettaa hänen isänsä valtakuntaan jälleen. Ja jutteli Arabialaiselle, kuinka ja minkätähden sotaväki rupesi vihaamaan kuningas Demetriusta, ja niin viipyi hän Arabialaisen tykönä kauvan aikaa."],[11,41,"Silloin Jonatan kirjoitti Demetriukselle, ja rukoili häntä käskemään niitä, jotka linnassa olivat, menemään pois ja linnaa hänelle antamaan; sillä he tekivät Israelille paljon pahaa.","Silloin Jonatan kirjoitti Demetriukselle, ja rukoili häntä käskemään niitä, jotka linnassa olivat, menemään pois ja linnaa hänelle antamaan; sillä he tekivät Israelille paljon pahaa."],[11,42,"Silloin kirjoitti Demetrius Jonatanille näin: en ainoasti tätä, jota sinä anot, mutta paljoa suuremman kunnian ja hyvyyden minä tahdon sinulle ja sinun kansalles tehdä, niin pian kuin minä taidan.","Silloin kirjoitti Demetrius Jonatanille näin: en ainoasti tätä, jota sinä anot, mutta paljoa suuremman kunnian ja hyvyyden minä tahdon sinulle ja sinun kansalles tehdä, niin pian kuin minä taidan."],[11,43,"Mutta nyt minä olen suuressa vaarassa: sentähden tee niin hyvin minua kohtaan ja lähetä minulle apua: sillä kaikki minun sotaväkeni on minun hyljännyt ja asettanut itsensä minua vastaan.","Mutta nyt minä olen suuressa vaarassa: sentähden tee niin hyvin minua kohtaan ja lähetä minulle apua: sillä kaikki minun sotaväkeni on minun hyljännyt ja asettanut itsensä minua vastaan."],[11,44,"Sen tähden lähetti Jonatan hänelle kolmetuhatta jaloa sotamiestä. Ne tulivat Antiokiaan kuninkaan tykö, ja kuningas ihastui heidän tulemisestansa sangen suuresti.","Sen tähden lähetti Jonatan hänelle kolmetuhatta jaloa sotamiestä. Ne tulivat Antiokiaan kuninkaan tykö, ja kuningas ihastui heidän tulemisestansa sangen suuresti."],[11,45,"Niin kansa nosti kaupungissa kapinan, joita oli sata ja kaksikymmentä tuhatta miestä, ja tahtoivat tappaa kuninkaan.","Niin kansa nosti kaupungissa kapinan, joita oli sata ja kaksikymmentä tuhatta miestä, ja tahtoivat tappaa kuninkaan."],[11,46,"Mutta kuningas pakeni linnaansa. Silloin sotaväki omisti kaupungin kujat ja tahtoi väkisellä linnaa saada.","Mutta kuningas pakeni linnaansa. Silloin sotaväki omisti kaupungin kujat ja tahtoi väkisellä linnaa saada."],[11,47,"Sen tähden kutsui kuningas Juudalaiset häntä varjelemaan. Niin juoksivat kaikki Juudalaiset kuninkaan avuksi, ja jakoivat itsensä kaupungin kujille,","Sen tähden kutsui kuningas Juudalaiset häntä varjelemaan. Niin juoksivat kaikki Juudalaiset kuninkaan avuksi, ja jakoivat itsensä kaupungin kujille,"],[11,48,"Ja löivät sinä päivänä satatuhatta miestä, ja sytyttivät tulen kaupungissa, ja ottivat heidän tavaransa. Näin he auttivat kuningasta.","Ja löivät sinä päivänä satatuhatta miestä, ja sytyttivät tulen kaupungissa, ja ottivat heidän tavaransa. Näin he auttivat kuningasta."],[11,49,"Kuin kaupungin kansa näki, että Juudalaiset kaupungin saivat haltuunsa, myöntyivät he, ja huusivat kuninkaalle, ja rukoilivat rauhaa, että Juudalaiset olisivat asetetut, ettei he myös enää väkeä tappaneet olisi, ja kaupunkia peräti hävittäneet.","Kuin kaupungin kansa näki, että Juudalaiset kaupungin saivat haltuunsa, myöntyivät he, ja huusivat kuninkaalle, ja rukoilivat rauhaa, että Juudalaiset olisivat asetetut, ettei he myös enää väkeä tappaneet olisi, ja kaupunkia peräti hävittäneet."],[11,50,"Niin tehtiin rauha, ja Juudalaiset heittivät aseensa pois, ja suuresti kunnioitettiin kuninkaalta, ja saivat korkian nimen koko valtakunnassa;","Niin tehtiin rauha, ja Juudalaiset heittivät aseensa pois, ja suuresti kunnioitettiin kuninkaalta, ja saivat korkian nimen koko valtakunnassa;"],[11,51,"Ja menivät jälleen kotiansa Jerusalemiin, ja veivät myötänsä paljon hyvyyttä, jonka he olivat sodassa voittaneet.","Ja menivät jälleen kotiansa Jerusalemiin, ja veivät myötänsä paljon hyvyyttä, jonka he olivat sodassa voittaneet."],[11,52,"Koska siis Demetrius taas surutoin oli, ja rauha oli kaikissa paikoissa hänen valtakunnassansa,","Koska siis Demetrius taas surutoin oli, ja rauha oli kaikissa paikoissa hänen valtakunnassansa,"],[11,53,"Ei hän ensinkään pitänyt sitä, mitä hän Jonatanille luvannut oli, mutta peräti eroitti itsensä hänestä, ja oli hänelle kiittämätöin hänen hyväin tekoinsa edestä, ja osoitti hänelle petollisuutensa.","Ei hän ensinkään pitänyt sitä, mitä hän Jonatanille luvannut oli, mutta peräti eroitti itsensä hänestä, ja oli hänelle kiittämätöin hänen hyväin tekoinsa edestä, ja osoitti hänelle petollisuutensa."],[11,54,"Vähää jälkeen tuli Tryphon jälleen nuoren Antiokuksen kanssa. Tämä Antiokus tuli kuninkaaksi, ja pantiin kruunu hänen päähänsä.","Vähää jälkeen tuli Tryphon jälleen nuoren Antiokuksen kanssa. Tämä Antiokus tuli kuninkaaksi, ja pantiin kruunu hänen päähänsä."],[11,55,"Ja hänen tykönsä tuli kaikki se sotaväki, jolle kuningas oli luvan antanut. Kuin he sotivat Demetriuksen kanssa, löivät he hänet pakoon, ja ajoivat häntä takaa.","Ja hänen tykönsä tuli kaikki se sotaväki, jolle kuningas oli luvan antanut. Kuin he sotivat Demetriuksen kanssa, löivät he hänet pakoon, ja ajoivat häntä takaa."],[11,56,"Ja Tryphon otti elephantit ja voitti Antiokian.","Ja Tryphon otti elephantit ja voitti Antiokian."],[11,57,"Ja nuori Antiokus kirjoitti Jonatanille, ja vahvisti hänen ylimmäisen papin virkaan ja myöten antoi, että hänen ne neljä kaupunkia piti omistaman ja pitämän, ja oleman kuninkaan ystävänä;","Ja nuori Antiokus kirjoitti Jonatanille, ja vahvisti hänen ylimmäisen papin virkaan ja myöten antoi, että hänen ne neljä kaupunkia piti omistaman ja pitämän, ja oleman kuninkaan ystävänä;"],[11,58,"Ja lähetti hänelle kultaisia astioita, ja antoi luvan hänelle pitää kultaa pöydällänsä ja purpuraa ja kultaisen vyön kantaa suolillansa.","Ja lähetti hänelle kultaisia astioita, ja antoi luvan hänelle pitää kultaa pöydällänsä ja purpuraa ja kultaisen vyön kantaa suolillansa."],[11,59,"Ja Simonin, Jonatanin veljen, teki hän sen maakunnan päämieheksi Tyrosta niin hamaan Egyptiin asti.","Ja Simonin, Jonatanin veljen, teki hän sen maakunnan päämieheksi Tyrosta niin hamaan Egyptiin asti."],[11,60,"Ja Jonatan läksi ulos ja meni, virran ylitse, ja tuli niihin kaupunkeihin, jotka olivat ympäristöllä. Ja hänen tykönsä meni kaikki sotaväki Syriasta, auttamaan häntä. Ja kuin hän tuli Askalonin alle, kävivät kaupungin asukkaat hänen tykönsä, ja ottivat hänen kunniallisesti vastaan, ja antautuivat hänen allensa.","Ja Jonatan läksi ulos ja meni, virran ylitse, ja tuli niihin kaupunkeihin, jotka olivat ympäristöllä. Ja hänen tykönsä meni kaikki sotaväki Syriasta, auttamaan häntä. Ja kuin hän tuli Askalonin alle, kävivät kaupungin asukkaat hänen tykönsä, ja ottivat hänen kunniallisesti vastaan, ja antautuivat hänen allensa."],[11,61,"Senjälkeen meni hän Gatsan eteen; mutta ne, jotka Gatsassa olivat, ei tahtoneet häntä päästää sisälle; sentähden piiritti hän kaupungin, ja poltti läheiset esikaupungit ja otti saaliin.","Senjälkeen meni hän Gatsan eteen; mutta ne, jotka Gatsassa olivat, ei tahtoneet häntä päästää sisälle; sentähden piiritti hän kaupungin, ja poltti läheiset esikaupungit ja otti saaliin."],[11,62,"Niin rukoilivat Gatsan asuvaiset rauhaa, ja Jonatan teki rauhan heidän kanssansa, ja otti muutamia heidän lapsiansa panttivangiksi, ja lähetti Jerusalemiin; mutta hän meni lävitse maakunnan Damaskuun asti.","Niin rukoilivat Gatsan asuvaiset rauhaa, ja Jonatan teki rauhan heidän kanssansa, ja otti muutamia heidän lapsiansa panttivangiksi, ja lähetti Jerusalemiin; mutta hän meni lävitse maakunnan Damaskuun asti."],[11,63,"Mutta kuin hän kuuli, että kuningas Demetriuksen päämiehet olivat suurella sotajoukolla tulleet Kedekseen, joka on Galileassa, omistamaan sitä maakuntaa, jonka kuningas oli hänelle antanut.","Mutta kuin hän kuuli, että kuningas Demetriuksen päämiehet olivat suurella sotajoukolla tulleet Kedekseen, joka on Galileassa, omistamaan sitä maakuntaa, jonka kuningas oli hänelle antanut."],[11,64,"Meni hän heitä vastaan, ja jätti veljensä Simonin siaansa siihen maahan.","Meni hän heitä vastaan, ja jätti veljensä Simonin siaansa siihen maahan."],[11,65,"Ja Simon meni Betsuraan, Ja sitä niin kovin ahdisti kauvan aikaa, ettei siitä yksikään tohtinut tulla ulos.","Ja Simon meni Betsuraan, Ja sitä niin kovin ahdisti kauvan aikaa, ettei siitä yksikään tohtinut tulla ulos."],[11,66,"Sentähden ne rukoilivat rauhaa, ja hän teki heidän kanssansa rauhan, ja antoi heidän pelkäämättä käydä ulos, ja omisti kaupungin, ja pani siihen sotaväkeä sitä varjelemaan.","Sentähden ne rukoilivat rauhaa, ja hän teki heidän kanssansa rauhan, ja antoi heidän pelkäämättä käydä ulos, ja omisti kaupungin, ja pani siihen sotaväkeä sitä varjelemaan."],[11,67,"Mutta Jonatan meni sotaväkensä Genesaretin meren tykö, ja oli huomeneltain varhain ylhäällä, ja he tulivat Batsarin kedolle.","Mutta Jonatan meni sotaväkensä Genesaretin meren tykö, ja oli huomeneltain varhain ylhäällä, ja he tulivat Batsarin kedolle."],[11,68,"Niin menivät pakanat häntä vastaan lakialle, ja heitä oli salainen joukko vuorella.","Niin menivät pakanat häntä vastaan lakialle, ja heitä oli salainen joukko vuorella."],[11,69,"Kuin Jonatan löi sitä toista joukkoa, niin tuli salainen joukko vuorelta hänen päällensä.","Kuin Jonatan löi sitä toista joukkoa, niin tuli salainen joukko vuorelta hänen päällensä."],[11,70,"Niin pakeni kaikki Jonatanin sotaväki, niin ettei muita jäänyt hänen tykönsä kuin ainoasti sodan päämiehet, Matatias Absalomin poika ja Juudas Kalphin poika:","Niin pakeni kaikki Jonatanin sotaväki, niin ettei muita jäänyt hänen tykönsä kuin ainoasti sodan päämiehet, Matatias Absalomin poika ja Juudas Kalphin poika:"],[11,71,"Silloin repäisi Jonatan vaatteensa, ja pani multaa päänsä päälle, rukoili,","Silloin repäisi Jonatan vaatteensa, ja pani multaa päänsä päälle, rukoili,"],[11,72,"Ja meni jälleen vihollisten tykö, ja löi heidät pakoon.","Ja meni jälleen vihollisten tykö, ja löi heidät pakoon."],[11,73,"Koska hänen väkensä, jotka ennen olivat paenneet, sen näkivät, kääntyivät he auttamaan Jonatania jälleen, ja ajoivat vihollisiansa takaa hamaan Kedeksen leiriin asti, ja he myös sioittivat itsensä siihen.","Koska hänen väkensä, jotka ennen olivat paenneet, sen näkivät, kääntyivät he auttamaan Jonatania jälleen, ja ajoivat vihollisiansa takaa hamaan Kedeksen leiriin asti, ja he myös sioittivat itsensä siihen."],[11,74,"Ja siinä tuli sinä päivänä tapetuksi liki kolmetuhatta pakanaa. Senjälkeen meni Jonatan Jerusalemiin jälleen","Ja siinä tuli sinä päivänä tapetuksi liki kolmetuhatta pakanaa. Senjälkeen meni Jonatan Jerusalemiin jälleen"],[12,1,"Mutta koska Jonatan näki hänellänsä tilan olevan, valitsi hän muutamia, jotka hän Roomiin lähetti uudistamaan ja vahvistamaan liittoa jälleen Roomalaisten kanssa.","Mutta koska Jonatan näki hänellänsä tilan olevan, valitsi hän muutamia, jotka hän Roomiin lähetti uudistamaan ja vahvistamaan liittoa jälleen Roomalaisten kanssa."],[12,2,"Hän kirjoitti myös Spartan, asuvaisten tykö ja muihin maan paikkoihin.","Hän kirjoitti myös Spartan, asuvaisten tykö ja muihin maan paikkoihin."],[12,3,"Kuin lähetetyt miehet tulivat Roomiin, menivät he kaupungin hallituksen eteen, ja sanoivat: Jonatan, ylimmäinen pappi, ja Juudan kansa ovat meitä tänne lähettäneet, uudistamaan jälleen sitä liittoa, joka meidän välillämme muinen tehtiin.","Kuin lähetetyt miehet tulivat Roomiin, menivät he kaupungin hallituksen eteen, ja sanoivat: Jonatan, ylimmäinen pappi, ja Juudan kansa ovat meitä tänne lähettäneet, uudistamaan jälleen sitä liittoa, joka meidän välillämme muinen tehtiin."],[12,4,"Ja Roomalaiset antoivat heille tiekirjan, että heidän piti saaman rauhassa kotiansa palata.","Ja Roomalaiset antoivat heille tiekirjan, että heidän piti saaman rauhassa kotiansa palata."],[12,5,"Ja Jonatan kirjoitti Spartan asuvaisten tykö näin:","Ja Jonatan kirjoitti Spartan asuvaisten tykö näin:"],[12,6,"Jonatan, ylimmäinen pappi, kansan vanhimmat ja muut papit, ja Juudan kansa, toivottavat veljillensä, jotka Spartassa ovat, terveyttä!","Jonatan, ylimmäinen pappi, kansan vanhimmat ja muut papit, ja Juudan kansa, toivottavat veljillensä, jotka Spartassa ovat, terveyttä!"],[12,7,"Ennen muutamia ajastaikoja kirjoitti teidän kuninkaanne Areus meidän ylimmäisen papin Onian tykö, että te olette meidän veljemme, niinkuin se kirja sen todeksi osoittaa.","Ennen muutamia ajastaikoja kirjoitti teidän kuninkaanne Areus meidän ylimmäisen papin Onian tykö, että te olette meidän veljemme, niinkuin se kirja sen todeksi osoittaa."],[12,8,"Ja Onia otti teidän lähetetyt miehet kunniallisesti vastaan, ja otti teidän ystävyytenne ja liittonne vastaan, niinkuin kirjassa oli kirjoitettu.","Ja Onia otti teidän lähetetyt miehet kunniallisesti vastaan, ja otti teidän ystävyytenne ja liittonne vastaan, niinkuin kirjassa oli kirjoitettu."],[12,9,"Ja vaikka emme tällä erällä muukalaisten apua tarvitse, sillä me turvaamme meidän Jumalamme sanaan, jota me joka päivä luemme;","Ja vaikka emme tällä erällä muukalaisten apua tarvitse, sillä me turvaamme meidän Jumalamme sanaan, jota me joka päivä luemme;"],[12,10,"Niin kuitenkin me lähetämme teille sanan, että te uudistaisitte ja vahvistaisitte veljellisen ja ystävällisen liiton meidän välillemme, ettemme sitä unhottaisi; sillä sitte on suuri aika kuin te meidän tykömme lähetitte.","Niin kuitenkin me lähetämme teille sanan, että te uudistaisitte ja vahvistaisitte veljellisen ja ystävällisen liiton meidän välillemme, ettemme sitä unhottaisi; sillä sitte on suuri aika kuin te meidän tykömme lähetitte."],[12,11,"Se te myös tietäkäät, että me aina juhlapäivinä ja muina päivinä, kuin uhrataan, rukouksissamme ja uhreissamme teitä ajattelemme, niinkuin myös veljiä tuleekin ajatella.","Se te myös tietäkäät, että me aina juhlapäivinä ja muina päivinä, kuin uhrataan, rukouksissamme ja uhreissamme teitä ajattelemme, niinkuin myös veljiä tuleekin ajatella."],[12,12,"Ja teidän kunnianne ja terveytenne on meidän ilomme.","Ja teidän kunnianne ja terveytenne on meidän ilomme."],[12,13,"Mutta sillä välillä on meillä suuri vaiva ollut, ja suuri sota kuningasten kanssa tässä ympäristöllä;","Mutta sillä välillä on meillä suuri vaiva ollut, ja suuri sota kuningasten kanssa tässä ympäristöllä;"],[12,14,"Mutta emme ole tahtoneet teitä, ja muita meidän ystäviämme ja liittoveljiämme vaivata niissä sodissa.","Mutta emme ole tahtoneet teitä, ja muita meidän ystäviämme ja liittoveljiämme vaivata niissä sodissa."],[12,15,"Sillä meillä on apu ollut taivaasta, ja Jumala on meitä varjellut ja maahan lyönyt meidän vihollisemme.","Sillä meillä on apu ollut taivaasta, ja Jumala on meitä varjellut ja maahan lyönyt meidän vihollisemme."],[12,16,"Mutta että me nyt lähetämme nämät meidän asianajajat, Numeniuksen, Antiokuksen pojan ja Antipatrin Jasonin pojan, Roomalaisten tykö, uudistamaan ystävyyttä ja liittoa heidän kanssansa;","Mutta että me nyt lähetämme nämät meidän asianajajat, Numeniuksen, Antiokuksen pojan ja Antipatrin Jasonin pojan, Roomalaisten tykö, uudistamaan ystävyyttä ja liittoa heidän kanssansa;"],[12,17,"Niin me olemme myös siinä heille käskyn antaneet, että heidän pitäis myös tuleman teidän tykönne, ja tervehtimän teitä meidän puolestamme, ja antaman teille tämän lähetyskirjan, uudistettaa meidän veljellistä liittoamme;","Niin me olemme myös siinä heille käskyn antaneet, että heidän pitäis myös tuleman teidän tykönne, ja tervehtimän teitä meidän puolestamme, ja antaman teille tämän lähetyskirjan, uudistettaa meidän veljellistä liittoamme;"],[12,18,"Ja rukoilemme tähän vastausta.","Ja rukoilemme tähän vastausta."],[12,19,"Mutta tämä on kopio siitä lähetyskirjasta, jonka Areus, Spartan kuningas, muinen meidän tykömme lähetti:","Mutta tämä on kopio siitä lähetyskirjasta, jonka Areus, Spartan kuningas, muinen meidän tykömme lähetti:"],[12,20,"Areus, Spartan kuningas, toivottaa Onialle, ylimmäiselle papille, terveyttä!","Areus, Spartan kuningas, toivottaa Onialle, ylimmäiselle papille, terveyttä!"],[12,21,"Me löydämme vanhoista kirjoista, että Spartan asuvaiset ja Juudalaiset ovat keskenänsä olleet veljekset, (sillä molemmat kansat ovat Abrahamista tulleet).","Me löydämme vanhoista kirjoista, että Spartan asuvaiset ja Juudalaiset ovat keskenänsä olleet veljekset, (sillä molemmat kansat ovat Abrahamista tulleet)."],[12,22,"Että me nyt sen tiedämme, rukoilemme me teitä, että te kirjoittaisitte meidän tykömme, kuinka teidän käy.","Että me nyt sen tiedämme, rukoilemme me teitä, että te kirjoittaisitte meidän tykömme, kuinka teidän käy."],[12,23,"Ja jos teille niin kelpaa, niin pitää meidän karjamme, hyvyytemme ja tavaramme ja mitä meillä on, oleman niinkuin se olis teidän omanne; ja mitä teillä on, pitää oleman niinkuin se meidän omamme olis. Tämän me olemme käskeneet teille tiettäväksi tehdä.","Ja jos teille niin kelpaa, niin pitää meidän karjamme, hyvyytemme ja tavaramme ja mitä meillä on, oleman niinkuin se olis teidän omanne; ja mitä teillä on, pitää oleman niinkuin se meidän omamme olis. Tämän me olemme käskeneet teille tiettäväksi tehdä."],[12,24,"Sitten kuuli Jonatan, että Demetriuksen sodanpäämiehet jälleen tulivat paljon suuremmalla voimalla kuin ennen, ja tahtoivat tulla häntä vastaan.","Sitten kuuli Jonatan, että Demetriuksen sodanpäämiehet jälleen tulivat paljon suuremmalla voimalla kuin ennen, ja tahtoivat tulla häntä vastaan."],[12,25,"Sentähden meni hän ulos Jerusalemista heitä vastaan Hematin maalle; sillä ei hän tahtonut odottaa niinkauvan että he olisivat kerinneet hänen maakuntaansa.","Sentähden meni hän ulos Jerusalemista heitä vastaan Hematin maalle; sillä ei hän tahtonut odottaa niinkauvan että he olisivat kerinneet hänen maakuntaansa."],[12,26,"Kuin hän vakoojat lähetti vihollisten leiriin, tulivat ne jälleen ja sanoivat, että viholliset olivat aikoneet sinä yönä karata heidän päällensä.","Kuin hän vakoojat lähetti vihollisten leiriin, tulivat ne jälleen ja sanoivat, että viholliset olivat aikoneet sinä yönä karata heidän päällensä."],[12,27,"Sen tähden antoi Jonatan käskyn sotaväelle ehtoona, että heidän piti valvoman, ja kaiken sen yön oleman haarniskoissa ja valmistettuna; ja asetti väkeä ympäri leiriä vartiaksi.","Sen tähden antoi Jonatan käskyn sotaväelle ehtoona, että heidän piti valvoman, ja kaiken sen yön oleman haarniskoissa ja valmistettuna; ja asetti väkeä ympäri leiriä vartiaksi."],[12,28,"Mutta koska viholliset näkivät, että Jonatan oli hänensä valmistanut sotimaan, tuli heille pelko, niin että he nousivat ja menivät matkaansa; ja ettei kenkään sitä olisi ymmärtänyt, antoivat he valkian tehdä usiaan paikkaan leiriinsä.","Mutta koska viholliset näkivät, että Jonatan oli hänensä valmistanut sotimaan, tuli heille pelko, niin että he nousivat ja menivät matkaansa; ja ettei kenkään sitä olisi ymmärtänyt, antoivat he valkian tehdä usiaan paikkaan leiriinsä."],[12,29,"Sentähden Jonatan ei luullut heidän menevän pois huomeniseen asti; sillä hän näki tulen olevan usiassa paikassa heidän leirissänsä.","Sentähden Jonatan ei luullut heidän menevän pois huomeniseen asti; sillä hän näki tulen olevan usiassa paikassa heidän leirissänsä."],[12,30,"Mutta huomeneltain ajoi hän heitä takaa, vaan ei hän käsittänyt heitä; sillä he ennättivät päästä ylitse Eleuterin virran.","Mutta huomeneltain ajoi hän heitä takaa, vaan ei hän käsittänyt heitä; sillä he ennättivät päästä ylitse Eleuterin virran."],[12,31,"Silloin palasi Jonatan Arabialaisten tykö, jotka kutsutaan Zabilaisiksi, löi heidät ja otti heidän saaliinsa.","Silloin palasi Jonatan Arabialaisten tykö, jotka kutsutaan Zabilaisiksi, löi heidät ja otti heidän saaliinsa."],[12,32,"Niin hän myös palasi sieltä, ja meni Damaskuun, ja hävitti maakunnat kaikissa paikoissa sen ympäriltä.","Niin hän myös palasi sieltä, ja meni Damaskuun, ja hävitti maakunnat kaikissa paikoissa sen ympäriltä."],[12,33,"Mutta Simon meni Askaloniin ja muihin vahvoihin kaupunkeihin, jotka läsnä olivat. Sitte käänsi hän itsensä Joppeen;","Mutta Simon meni Askaloniin ja muihin vahvoihin kaupunkeihin, jotka läsnä olivat. Sitte käänsi hän itsensä Joppeen;"],[12,34,"Sillä hän ymmärsi, että ne tahtoivat itsensä antaa Demetriuksen päämiesten haltuun. Sentähden tuli hän ennakolta ja omisti Jopen kaupungin, ja asetti sotaväkeä siihen varjelemaan kaupunkia.","Sillä hän ymmärsi, että ne tahtoivat itsensä antaa Demetriuksen päämiesten haltuun. Sentähden tuli hän ennakolta ja omisti Jopen kaupungin, ja asetti sotaväkeä siihen varjelemaan kaupunkia."],[12,35,"Senjälkeen tuli Jonatan kotia jälleen, ja piti neuvoa kansan vanhimpain kanssa, että muutamia kaupungeita Juudeassa piti vahvistettaman,","Senjälkeen tuli Jonatan kotia jälleen, ja piti neuvoa kansan vanhimpain kanssa, että muutamia kaupungeita Juudeassa piti vahvistettaman,"],[12,36,"Ja Jerusalemin muurit korotettaman, ja yksi korkia muuri linnan ja kaupungin välillä rakettaman, että kaupunki linnasta olis tullut eroitetuksi, niin ettei ne, jotka linnassa asuivat, olisi saaneet tulla niiden päälle, jotka kaupungeissa asuivat, ja ettei kenkään olisi saanut heidän tykönsä viedä, eikä heille mitään myydä.","Ja Jerusalemin muurit korotettaman, ja yksi korkia muuri linnan ja kaupungin välillä rakettaman, että kaupunki linnasta olis tullut eroitetuksi, niin ettei ne, jotka linnassa asuivat, olisi saaneet tulla niiden päälle, jotka kaupungeissa asuivat, ja ettei kenkään olisi saanut heidän tykönsä viedä, eikä heille mitään myydä."],[12,37,"Kuin väki tuli yhteen, niin he rupesivat rakentamaan; ja että se muuri, joka oli idän puolella ojan ylitse, oli maahan langennut, rakensivat he sen kappaleen ylös jälleen, joka kutsutaan Kaphnata.","Kuin väki tuli yhteen, niin he rupesivat rakentamaan; ja että se muuri, joka oli idän puolella ojan ylitse, oli maahan langennut, rakensivat he sen kappaleen ylös jälleen, joka kutsutaan Kaphnata."],[12,38,"Ja Simon rakensi sen linnan, joka kutsutaan Adida Sephelas, ja teki sen vahvaksi, ja varusti sen vahvalla portilla.","Ja Simon rakensi sen linnan, joka kutsutaan Adida Sephelas, ja teki sen vahvaksi, ja varusti sen vahvalla portilla."],[12,39,"Niin aikoi Tryphon Asian valtakuntaa ottaa allensa, ja panna kruunun päähänsä ja tappaa kuninkaan, nuoren Antiokuksen.","Niin aikoi Tryphon Asian valtakuntaa ottaa allensa, ja panna kruunun päähänsä ja tappaa kuninkaan, nuoren Antiokuksen."],[12,40,"Mutta että hän pelkäsi, että Jonatanin piti sen estämän ja häntä vastaan nouseman, etsi hän myös tilaa, kuinka hän olis saanut ottaa Jonatanin kiinni ja surmata.","Mutta että hän pelkäsi, että Jonatanin piti sen estämän ja häntä vastaan nouseman, etsi hän myös tilaa, kuinka hän olis saanut ottaa Jonatanin kiinni ja surmata."],[12,41,"Sentähden meni hän Betsaan; sinne tuli myös Jonatan neljälläkymmennellä tuhannella hyvin varustetulla miehellä.","Sentähden meni hän Betsaan; sinne tuli myös Jonatan neljälläkymmennellä tuhannella hyvin varustetulla miehellä."],[12,42,"Mutta kuin Tryphon näki, että Jonatanilla niin suuri väki oli, pelkäsi hän ja ei tohtinut julkisesti olla häntä vastaan;","Mutta kuin Tryphon näki, että Jonatanilla niin suuri väki oli, pelkäsi hän ja ei tohtinut julkisesti olla häntä vastaan;"],[12,43,"Mutta otti hänen vastaan kunnialla, ja käski myös ystävänsä hänen kunniassa pitää, ja antoi hänelle lahjoja, ja käski sotaväkensä niin Jonatanille kuuliaiset olla kuin itse hänellensä.","Mutta otti hänen vastaan kunnialla, ja käski myös ystävänsä hänen kunniassa pitää, ja antoi hänelle lahjoja, ja käski sotaväkensä niin Jonatanille kuuliaiset olla kuin itse hänellensä."],[12,44,"Ja sanoi Jonatanille: miksi sinä teet kansalle niin suurta vaivaa, koska ei meidän välillämme ole yhtään sotaa?","Ja sanoi Jonatanille: miksi sinä teet kansalle niin suurta vaivaa, koska ei meidän välillämme ole yhtään sotaa?"],[12,45,"Anna heidän palata kotiansa, ja ota sinulles vähä väkeä, jotka sinun tykönäs ovat, ja käy minun kanssani Ptolomaidiin. Sen kaupungin minä tahdon antaa sinulle, ja ne muut vahvat kaupungit, ja tahdon sinun haltuus antaa kaiken sotaväen ja päämiehet. Sillä minun pitää menemän takaperin jälleen, ja ainoasti sen syyn tähden minä olen tänne tullut; sentähden kuitenkin seuraa minua.","Anna heidän palata kotiansa, ja ota sinulles vähä väkeä, jotka sinun tykönäs ovat, ja käy minun kanssani Ptolomaidiin. Sen kaupungin minä tahdon antaa sinulle, ja ne muut vahvat kaupungit, ja tahdon sinun haltuus antaa kaiken sotaväen ja päämiehet. Sillä minun pitää menemän takaperin jälleen, ja ainoasti sen syyn tähden minä olen tänne tullut; sentähden kuitenkin seuraa minua."],[12,46,"Jonatan uskoi häneen, ja antoi väkensä mennä pois tyköänsä Juudeaan kotiansa;","Jonatan uskoi häneen, ja antoi väkensä mennä pois tyköänsä Juudeaan kotiansa;"],[12,47,"Ja piti kolmetuhatta vaivoin tykönänsä, joista hän kaksituhatta lähetti Galileaan, mutta se yksi tuhat ainoasti seurasi häntä.","Ja piti kolmetuhatta vaivoin tykönänsä, joista hän kaksituhatta lähetti Galileaan, mutta se yksi tuhat ainoasti seurasi häntä."],[12,48,"Kuin Jonatan tuli Ptolomaidin kaupunkiin, antoi Tryphon sulkea portit, ja Jonatanin ottaa kiinni ja hänen väkensä tappaa.","Kuin Jonatan tuli Ptolomaidin kaupunkiin, antoi Tryphon sulkea portit, ja Jonatanin ottaa kiinni ja hänen väkensä tappaa."],[12,49,"Ja lähetti sekä jalkamiehiä että ratsasmiehiä Galileaan, leviälle kedolle, hukuttamaan Jonatanin toista sotajoukkoa.","Ja lähetti sekä jalkamiehiä että ratsasmiehiä Galileaan, leviälle kedolle, hukuttamaan Jonatanin toista sotajoukkoa."],[12,50,"Mutta koska he ymmärsivät, että Jonatan oli vangiksi otettu väkinensä, neuvoivat he toinen toistansa valmistamaan itsensä sotaan ja menemään rohkiasti vihollista vastaan.","Mutta koska he ymmärsivät, että Jonatan oli vangiksi otettu väkinensä, neuvoivat he toinen toistansa valmistamaan itsensä sotaan ja menemään rohkiasti vihollista vastaan."],[12,51,"Mutta kuin viholliset näkivät itsensä siinä olevan hengen vaarassa, ja että nämät tahtoivat heitänsä varjella, kääntyivät he takaperin ja menivät matkaansa.","Mutta kuin viholliset näkivät itsensä siinä olevan hengen vaarassa, ja että nämät tahtoivat heitänsä varjella, kääntyivät he takaperin ja menivät matkaansa."],[12,52,"Niin se väki myös meni kotiansa jälleen rauhassa, ja itkivät Jonatania ja muita, jotka hänen seurassansa tapetut olivat, ja kaikki Israelissa olivat surulliset Jonatanin tähden.","Niin se väki myös meni kotiansa jälleen rauhassa, ja itkivät Jonatania ja muita, jotka hänen seurassansa tapetut olivat, ja kaikki Israelissa olivat surulliset Jonatanin tähden."],[12,53,"Ja kaikki pakanat ympäristöltä rupesivat karkaamaan heidän päällensä ja vaivaamaan kansaa, ja sanoivat: Ei heillä ole yhtään päämiestä eikä holhojaa enää: käykäämme nyt heitä vastaan, ja hävittäkäämme heitä, ja pyyhkikäämme pois heidän nimensä maan päältä.","Ja kaikki pakanat ympäristöltä rupesivat karkaamaan heidän päällensä ja vaivaamaan kansaa, ja sanoivat: Ei heillä ole yhtään päämiestä eikä holhojaa enää: käykäämme nyt heitä vastaan, ja hävittäkäämme heitä, ja pyyhkikäämme pois heidän nimensä maan päältä."],[13,1,"Kuin Simon. kuuli, että Tryphon suuren sotaväen koonnut oli, menemään Juudalaisia vastaan ja hävittämään heitä,","Kuin Simon. kuuli, että Tryphon suuren sotaväen koonnut oli, menemään Juudalaisia vastaan ja hävittämään heitä,"],[13,2,"Ja näki kansan peljästyneen ja hämmästyneen, tuli hän Jerusalemiin, vahvisti heitä ja sanoi:","Ja näki kansan peljästyneen ja hämmästyneen, tuli hän Jerusalemiin, vahvisti heitä ja sanoi:"],[13,3,"Te tiedätte, kuinka suurta sotaa minä ja minun veljeni ja isäni lain ja pyhän edestä olemme pitäneet, ja olette nähneet sen vaivan, jossa kaikki Israel on ollut,","Te tiedätte, kuinka suurta sotaa minä ja minun veljeni ja isäni lain ja pyhän edestä olemme pitäneet, ja olette nähneet sen vaivan, jossa kaikki Israel on ollut,"],[13,4,"Jossa myös kaikki minun veljeni Israelin tähden ovat hukkuneet, ja ei heistä silleen yhtään muuta elä kuin minä yksinäni.","Jossa myös kaikki minun veljeni Israelin tähden ovat hukkuneet, ja ei heistä silleen yhtään muuta elä kuin minä yksinäni."],[13,5,"Nyt en minä tahdo säästää henkeäni tässä surussa ja vaivassa, sillä en minä ole parempi kuin minun veljenikään, enkä myös pyydä parempaa menoa kuin heillä oli;","Nyt en minä tahdo säästää henkeäni tässä surussa ja vaivassa, sillä en minä ole parempi kuin minun veljenikään, enkä myös pyydä parempaa menoa kuin heillä oli;"],[13,6,"Mutta minä tahdon kostaa minun kansani edestä, meidän pyhämme, meidän vaimoimme ja lastemme edestä; sillä kaikki pakanat tässä ympäristöllä ovat julmistuneet meidän päällemme, ja kokoontuvat meitä hukuttamaan.","Mutta minä tahdon kostaa minun kansani edestä, meidän pyhämme, meidän vaimoimme ja lastemme edestä; sillä kaikki pakanat tässä ympäristöllä ovat julmistuneet meidän päällemme, ja kokoontuvat meitä hukuttamaan."],[13,7,"Tästä puheesta sai kansa lohdutuksen jälleen, vahvistuivat, ja vastasivat ja huusivat:","Tästä puheesta sai kansa lohdutuksen jälleen, vahvistuivat, ja vastasivat ja huusivat:"],[13,8,"Sinun pitää oleman meidän päämiehemme Juudaan ja Jonatanin sinun veljes siassa, sotimaan vihollisia vastaan.","Sinun pitää oleman meidän päämiehemme Juudaan ja Jonatanin sinun veljes siassa, sotimaan vihollisia vastaan."],[13,9,"Ja me tahdomme olla sinulle kuuliaiset niissä kaikissa, joita sinä meille käsket.","Ja me tahdomme olla sinulle kuuliaiset niissä kaikissa, joita sinä meille käsket."],[13,10,"Niin kutsui Simon sotaväen yhteen, ja antoi käskyn, että Jerusalemin muurit olisivat äkisti paratut, ja kaupunki tulis ympärinsä hyvin turvatuksi ja vahvistetuksi,","Niin kutsui Simon sotaväen yhteen, ja antoi käskyn, että Jerusalemin muurit olisivat äkisti paratut, ja kaupunki tulis ympärinsä hyvin turvatuksi ja vahvistetuksi,"],[13,11,"Ja lähetti Jonatanin Absalomin pojan sotajoukon kanssa Joppeen; ja Jonatan ajoi viholliset ulos Jopesta ja omisti kaupungin.","Ja lähetti Jonatanin Absalomin pojan sotajoukon kanssa Joppeen; ja Jonatan ajoi viholliset ulos Jopesta ja omisti kaupungin."],[13,12,"Silloin meni Tryphon ulos Ptolomaidista suurella sotaväellä, ja aikoi mennä Juudeaan, ja vei Jonatanin vankina myötänsä.","Silloin meni Tryphon ulos Ptolomaidista suurella sotaväellä, ja aikoi mennä Juudeaan, ja vei Jonatanin vankina myötänsä."],[13,13,"Mutta Simon kävi häntä vastaan, ja asetti leirinsä lakialle kedolle lähes Addusta.","Mutta Simon kävi häntä vastaan, ja asetti leirinsä lakialle kedolle lähes Addusta."],[13,14,"Mutta kuin Tryphon ymmärsi, että Simon veljensä Jonatanin siaan oli tullut päämieheksi, ja ajatteli tapella hänen kanssansa, lähetti hän sanan Simonille ja antoi hänelle sanoa:","Mutta kuin Tryphon ymmärsi, että Simon veljensä Jonatanin siaan oli tullut päämieheksi, ja ajatteli tapella hänen kanssansa, lähetti hän sanan Simonille ja antoi hänelle sanoa:"],[13,15,"Minä olen Jonatanin pitänyt kiinni rahan tähden, jonka hän virkansa puolesta on kuninkaalle velkaa.","Minä olen Jonatanin pitänyt kiinni rahan tähden, jonka hän virkansa puolesta on kuninkaalle velkaa."],[13,16,"Jos sinä tahdot lähettää minulle sata leiviskää hopiaa, ja antaa kaksi hänen poikaansa pantiksi, ettei hän meidän tyköämme pakenisi pois, eikä asettelisi itsiänsä meitä vastaan, kuin hän vallallensa pääsee, niin minä tahdon hänen irralle päästää, ja sinulle antaa.","Jos sinä tahdot lähettää minulle sata leiviskää hopiaa, ja antaa kaksi hänen poikaansa pantiksi, ettei hän meidän tyköämme pakenisi pois, eikä asettelisi itsiänsä meitä vastaan, kuin hän vallallensa pääsee, niin minä tahdon hänen irralle päästää, ja sinulle antaa."],[13,17,"Vaikka Simon ymmärsi sen kaiken olevan petoksen, kuitenkin hän niin toimitti, että raha ja lapset tulivat Tryphonille lähetetyksi, ettei kansa olisi hänen ylitsensä valittanut ja sanonut:","Vaikka Simon ymmärsi sen kaiken olevan petoksen, kuitenkin hän niin toimitti, että raha ja lapset tulivat Tryphonille lähetetyksi, ettei kansa olisi hänen ylitsensä valittanut ja sanonut:"],[13,18,"Jonatanin täytyi sentähden hukkua, ettei hän tahtonut häntä lunastaa.","Jonatanin täytyi sentähden hukkua, ettei hän tahtonut häntä lunastaa."],[13,19,"Sentähden lähetti hän hänelle ne lapset ja sata leiviskää hopiaa. Mutta Tryphon ei pitänyt lupaustansa, eikä Jonatania irralle päästänyt.","Sentähden lähetti hän hänelle ne lapset ja sata leiviskää hopiaa. Mutta Tryphon ei pitänyt lupaustansa, eikä Jonatania irralle päästänyt."],[13,20,"Ja vielä sitte meni Tryphon edemmä, että hän olis taitanut tulla maalle vahinkoa tekemään, ja vaelsi Hadorin tietä. Mutta Simon sotaväkinensä oli joka paikassa hänen sivullansa, ja kuhunka hän tahtoi mennä, sen ennätti häneltä Simon.","Ja vielä sitte meni Tryphon edemmä, että hän olis taitanut tulla maalle vahinkoa tekemään, ja vaelsi Hadorin tietä. Mutta Simon sotaväkinensä oli joka paikassa hänen sivullansa, ja kuhunka hän tahtoi mennä, sen ennätti häneltä Simon."],[13,21,"Niin myös ne, jotka linnassa olivat, lähettivät sanan Tryphonille, että hän olis vaeltanut heidän tykönsä korven lävitse, ennen kuin Simon olis ennättänyt, ja että hän olis antanut heille viljaa tuoda.","Niin myös ne, jotka linnassa olivat, lähettivät sanan Tryphonille, että hän olis vaeltanut heidän tykönsä korven lävitse, ennen kuin Simon olis ennättänyt, ja että hän olis antanut heille viljaa tuoda."],[13,22,"Sentähden kiiruhti Tryphon kaikkein ratsasmiestensä kanssa menemään heidän tykönsä, mutta sinä yönä tuli sangen suuri lumi ja esti hänen sieltä.","Sentähden kiiruhti Tryphon kaikkein ratsasmiestensä kanssa menemään heidän tykönsä, mutta sinä yönä tuli sangen suuri lumi ja esti hänen sieltä."],[13,23,"Sitte hän meni Galaadiin, ja Baskaman tykönä antoi tappaa Jonatanin poikinensa, jotka siinä haudattiin.","Sitte hän meni Galaadiin, ja Baskaman tykönä antoi tappaa Jonatanin poikinensa, jotka siinä haudattiin."],[13,24,"Ja Tryphon meni jälleen omalle maallensa.","Ja Tryphon meni jälleen omalle maallensa."],[13,25,"Niin Simon lähetti noutamaan veljensä ruumiin, ja pani sen oman isänsä hautaan Modin kaupungissa.","Niin Simon lähetti noutamaan veljensä ruumiin, ja pani sen oman isänsä hautaan Modin kaupungissa."],[13,26,"Ja koko Israel valitti kauvan ja itki Jonatania.","Ja koko Israel valitti kauvan ja itki Jonatania."],[13,27,"Ja Simon antoi tehdä isällensä ja veljillensä korkian haudan vuolluista kivistä,","Ja Simon antoi tehdä isällensä ja veljillensä korkian haudan vuolluista kivistä,"],[13,28,"Jonka päälle hän pani seitsemän patsasta, liki toinen toistansa, isällensä, äidillensä ja neljälle veljellensä,","Jonka päälle hän pani seitsemän patsasta, liki toinen toistansa, isällensä, äidillensä ja neljälle veljellensä,"],[13,29,"Ja antoi suuret patsaat sen ympärille tehdä, ja asetti niiden päälle heidän aseensa ijankaikkiseksi muistoksi, ja aseitten sivuun antoi panna hakatut haahdet, jotka purjehtivaiset meressä näkemän piti.","Ja antoi suuret patsaat sen ympärille tehdä, ja asetti niiden päälle heidän aseensa ijankaikkiseksi muistoksi, ja aseitten sivuun antoi panna hakatut haahdet, jotka purjehtivaiset meressä näkemän piti."],[13,30,"Tämä hauta on Modissa vielä tänäpänä.","Tämä hauta on Modissa vielä tänäpänä."],[13,31,"Mutta Tryphon johdatteli nuorta Antiokusta petollisesti sinne ja tänne maakunnissa, siihen asti kuin hän salaisesti hänen tappoi,","Mutta Tryphon johdatteli nuorta Antiokusta petollisesti sinne ja tänne maakunnissa, siihen asti kuin hän salaisesti hänen tappoi,"],[13,32,"Ja sitte pani itse kruunun päähänsä, tuli Asian kuninkaaksi ja vaivasi Juudan maakuntaa sangen kovin.","Ja sitte pani itse kruunun päähänsä, tuli Asian kuninkaaksi ja vaivasi Juudan maakuntaa sangen kovin."],[13,33,"Mutta Simon rakensi monta kaupunkia Juudeassa paksuilla muureilla, korkeilla torneilla ja vahvoilla porteilla, ja toimitti viljaa vahvimpiin kaupunkeihin,","Mutta Simon rakensi monta kaupunkia Juudeassa paksuilla muureilla, korkeilla torneilla ja vahvoilla porteilla, ja toimitti viljaa vahvimpiin kaupunkeihin,"],[13,34,"Ja lähetti valituita miehiä kuningas Demetriuksen tykö, rukoilemaan häneltä lievitystä siitä kuormasta, jonka Tryphon oli laskenut hänen päällensä; sillä ei Tryphon muuta tehnyt maakunnassa, vaan väkivaltaa ja murhaa.","Ja lähetti valituita miehiä kuningas Demetriuksen tykö, rukoilemaan häneltä lievitystä siitä kuormasta, jonka Tryphon oli laskenut hänen päällensä; sillä ei Tryphon muuta tehnyt maakunnassa, vaan väkivaltaa ja murhaa."],[13,35,"Siihen vastasi Demetrius ja kirjoitti näin:","Siihen vastasi Demetrius ja kirjoitti näin:"],[13,36,"Kuningas Demetrius toivottaa ylimmäiselle papille Simonille, ja vanhimmille, ja Juudan kansalle terveyttä!","Kuningas Demetrius toivottaa ylimmäiselle papille Simonille, ja vanhimmille, ja Juudan kansalle terveyttä!"],[13,37,"Kultaisen kruunun ynnä palmun kanssa, jonka te minulle lähetitte, olemme me saaneet, ja olemme valmiit tekemään hyvän rauhan teidän kanssanne, ja kirjoittamaan meidän käskyläistemme tykö, että heidän pitää antaman teitä kaikesta siltä kuormasta vapaana olla, josta me ennen olemme luvanneet teille vapauden antaa.","Kultaisen kruunun ynnä palmun kanssa, jonka te minulle lähetitte, olemme me saaneet, ja olemme valmiit tekemään hyvän rauhan teidän kanssanne, ja kirjoittamaan meidän käskyläistemme tykö, että heidän pitää antaman teitä kaikesta siltä kuormasta vapaana olla, josta me ennen olemme luvanneet teille vapauden antaa."],[13,38,"Ja mitä me teille luvanneet olemme, se pitää uskollisesti lujana ja vahvana pidettämän. Kaikki ne linnat, jotka te olette rakentaneet, pitää teidän pitämän ja nautitseman.","Ja mitä me teille luvanneet olemme, se pitää uskollisesti lujana ja vahvana pidettämän. Kaikki ne linnat, jotka te olette rakentaneet, pitää teidän pitämän ja nautitseman."],[13,39,"Ja me annamme anteeksi kaikki, mitä te toisinansa olette tehneet meitä vastaan, kruunun teot ja muut verot, jotka Jerusalem piti tekemän, ne me annamme teille anteeksi.","Ja me annamme anteeksi kaikki, mitä te toisinansa olette tehneet meitä vastaan, kruunun teot ja muut verot, jotka Jerusalem piti tekemän, ne me annamme teille anteeksi."],[13,40,"Ja jotka meitä tahtovat palvella, ne me tahdomme ottaa vastaan, ja meidän välillämme pitää hyvä rauha oleman.","Ja jotka meitä tahtovat palvella, ne me tahdomme ottaa vastaan, ja meidän välillämme pitää hyvä rauha oleman."],[13,41,"Seitsemäntenäkymmenentenä vuotena toista sataa, tuli Israel vapahdetuksi pakanain ikeen alta:","Seitsemäntenäkymmenentenä vuotena toista sataa, tuli Israel vapahdetuksi pakanain ikeen alta:"],[13,42,"Ja ruvettiin kirjoittamaan heidän asiakirjoihinsa näin: ensimäisenä Simonin, ylimmäisen papin ja Juudalalsten päämiehen vuotena.","Ja ruvettiin kirjoittamaan heidän asiakirjoihinsa näin: ensimäisenä Simonin, ylimmäisen papin ja Juudalalsten päämiehen vuotena."],[13,43,"Niinä päivinä piiritti Simon Gatsan kaupungin, ja asetti sen eteen vahvat sodan rakennukset, ja väkisellä voitti kaupungin, ja sai yhden tornin.","Niinä päivinä piiritti Simon Gatsan kaupungin, ja asetti sen eteen vahvat sodan rakennukset, ja väkisellä voitti kaupungin, ja sai yhden tornin."],[13,44,"Ja ne, jotka tulivat tornin päälle, hyppäsivät kaupunkiin. Ja kansa, joka oli kaupungissa, hämmästyi ja peräti peljästyi,","Ja ne, jotka tulivat tornin päälle, hyppäsivät kaupunkiin. Ja kansa, joka oli kaupungissa, hämmästyi ja peräti peljästyi,"],[13,45,"Ja juoksivat vaimoinensa ja lapsinensa muurien päälle, repäisivät vaatteensa ja huusivat korkiasti, anoivat armoa ja sanoivat:","Ja juoksivat vaimoinensa ja lapsinensa muurien päälle, repäisivät vaatteensa ja huusivat korkiasti, anoivat armoa ja sanoivat:"],[13,46,"Älä meitä rankaise meidän pahuutemme jälkeen, mutta ole meille armollinen, niin me tahdomme hyvällä mielellä kuuliaiset olla.","Älä meitä rankaise meidän pahuutemme jälkeen, mutta ole meille armollinen, niin me tahdomme hyvällä mielellä kuuliaiset olla."],[13,47,"Tämä lepytti Simonin niin, ettei hän antanut heitä tappaa; mutta käski heitä mennä kaupungista pois, ja antoi puhdistaa ne huoneet, Joihin epäjumalat pannut olivat.","Tämä lepytti Simonin niin, ettei hän antanut heitä tappaa; mutta käski heitä mennä kaupungista pois, ja antoi puhdistaa ne huoneet, Joihin epäjumalat pannut olivat."],[13,48,"Sitten meni hän kaupunkiin, kiitti ja kunnioitti Jumalaa, ja antoi kaikki kauhistukset ottaa pois ja hävittää, ja pani siihen kansaa, Joka Jumalan lain piti, ja teki kaupungin vahvaksi, ja rakensi jällensä siihen itsellensä huoneen.","Sitten meni hän kaupunkiin, kiitti ja kunnioitti Jumalaa, ja antoi kaikki kauhistukset ottaa pois ja hävittää, ja pani siihen kansaa, Joka Jumalan lain piti, ja teki kaupungin vahvaksi, ja rakensi jällensä siihen itsellensä huoneen."],[13,49,"Ja ne, jotka Jerusalemin linnassa olivat, suljettiin, niin ettei yksikään saanut käydä ulos taikka sisälle, eikä mitään ostaa taikka myydä, mutta kärsivät suurta nälkää, niin että monen täytyi nälästä kuolla.","Ja ne, jotka Jerusalemin linnassa olivat, suljettiin, niin ettei yksikään saanut käydä ulos taikka sisälle, eikä mitään ostaa taikka myydä, mutta kärsivät suurta nälkää, niin että monen täytyi nälästä kuolla."],[13,50,"Ja sentähden he huusivat Simonin tykö, Ja rukoilivat rauhaa ja antoivat itsensä. Niin teki Simon armon heidän kanssansa ja antoi heidän elää. Mutta heidän piti linnasta menemän pois, ja Simon antoi linnan jälleen puhdistaa kaikista kauhistuksista,","Ja sentähden he huusivat Simonin tykö, Ja rukoilivat rauhaa ja antoivat itsensä. Niin teki Simon armon heidän kanssansa ja antoi heidän elää. Mutta heidän piti linnasta menemän pois, ja Simon antoi linnan jälleen puhdistaa kaikista kauhistuksista,"],[13,51,"Ja sai sen kolmantena päivänä kolmattakymmentä toisena kuuna, ensimäisenä vuotena kahdeksattakymmentä toista sataa, ja meni sinne kiitosvirsillä, palmuoksilla ja kaikkinaisilla kanteleilla, kiitti Jumalaa, että he siitä suuresta julmuudesta, joka Israelin päällä oli, tulivat vapahdetuksi.","Ja sai sen kolmantena päivänä kolmattakymmentä toisena kuuna, ensimäisenä vuotena kahdeksattakymmentä toista sataa, ja meni sinne kiitosvirsillä, palmuoksilla ja kaikkinaisilla kanteleilla, kiitti Jumalaa, että he siitä suuresta julmuudesta, joka Israelin päällä oli, tulivat vapahdetuksi."],[13,52,"Ja käski sen päivän joka vuosi ilolla pyhitettää,","Ja käski sen päivän joka vuosi ilolla pyhitettää,"],[13,53,"Ja rakensi vuorella muurit ympäri templiä, läsnä linnaa, ja teki ne vielä vahvemmiksi, ja asui itse siellä, hän ja ne, jotka hän tykönänsä piti. Ja että hän näki poikansa Johanneksen toimellisen ja kelvollisen miehen olevan, asetti hän hänen kaiken sotaväen päämieheksi, ja pani asumaan Gatsaan.","Ja rakensi vuorella muurit ympäri templiä, läsnä linnaa, ja teki ne vielä vahvemmiksi, ja asui itse siellä, hän ja ne, jotka hän tykönänsä piti. Ja että hän näki poikansa Johanneksen toimellisen ja kelvollisen miehen olevan, asetti hän hänen kaiken sotaväen päämieheksi, ja pani asumaan Gatsaan."],[14,1,"Toisena vuonna kahdeksattakymmentä toista sataa kokosi kuningas Demetrius sotaväkensä, ja meni Mediaan apua saamaan Tryphonia vastaan.","Toisena vuonna kahdeksattakymmentä toista sataa kokosi kuningas Demetrius sotaväkensä, ja meni Mediaan apua saamaan Tryphonia vastaan."],[14,2,"Mutta kuin Arsases, Persian ja Median kuningas, ymmärsi, että Demetrius oli mennyt valtakuntaansa, lähetti hän yhden päämiehistänsä häntä vastaan, ja käski vangiksi ottaa hänen ja elävänä tykönsä tuoda.","Mutta kuin Arsases, Persian ja Median kuningas, ymmärsi, että Demetrius oli mennyt valtakuntaansa, lähetti hän yhden päämiehistänsä häntä vastaan, ja käski vangiksi ottaa hänen ja elävänä tykönsä tuoda."],[14,3,"Se päämies löi Demetriuksen sotaväen, otti hänen kiinni ja vei kuningas Arsaseksen tykö; niin piti Arsases hänen vankina, ja antoi hänestä ottaa vaarin.","Se päämies löi Demetriuksen sotaväen, otti hänen kiinni ja vei kuningas Arsaseksen tykö; niin piti Arsases hänen vankina, ja antoi hänestä ottaa vaarin."],[14,4,"Silloin oli Juudeassa lepo ja hyvä rauha, niinkauvan kuin Simon eli; ja Simon hallitsi sangen hyvin, ja teki maakunnalle paljon hyvää, niin että hän hyvällä mielellä pidettiin herrana kaikkina ikäpäivinänsä.","Silloin oli Juudeassa lepo ja hyvä rauha, niinkauvan kuin Simon eli; ja Simon hallitsi sangen hyvin, ja teki maakunnalle paljon hyvää, niin että hän hyvällä mielellä pidettiin herrana kaikkina ikäpäivinänsä."],[14,5,"Ja hän voitti suurella kunnialla Jopen kaupungin ja sen sataman, josta hän sai purjehtia merelle luotolaisten tykö,","Ja hän voitti suurella kunnialla Jopen kaupungin ja sen sataman, josta hän sai purjehtia merelle luotolaisten tykö,"],[14,6,"Ja voitti allensa maakuntia, ja rajat omassa maassansa siirsi edemmäksi, ja päästi monta, jotka ennen olivat poljetut alas ja vankina olleet.","Ja voitti allensa maakuntia, ja rajat omassa maassansa siirsi edemmäksi, ja päästi monta, jotka ennen olivat poljetut alas ja vankina olleet."],[14,7,"Hänellä myös oli Gatsa ja Betsura ja Jerusalemin linna, jonka hän vastuudesta puhdisti, ja ei yksikään tohtinut olla häntä vastaan.","Hänellä myös oli Gatsa ja Betsura ja Jerusalemin linna, jonka hän vastuudesta puhdisti, ja ei yksikään tohtinut olla häntä vastaan."],[14,8,"Jokainen kynti peltojansa hyvässä rauhassa, maa kasvoi viljan, ja puut kantoivat hedelmän.","Jokainen kynti peltojansa hyvässä rauhassa, maa kasvoi viljan, ja puut kantoivat hedelmän."],[14,9,"Vanhimmat hallitsivat ilman estettä, ja toimittivat kaikki hyvin; kauppamiehet menestyivät ja hyötyivät kaupoissansa, ja valmistivat itsellensä aseita ja varaa vihollisia vastaan.","Vanhimmat hallitsivat ilman estettä, ja toimittivat kaikki hyvin; kauppamiehet menestyivät ja hyötyivät kaupoissansa, ja valmistivat itsellensä aseita ja varaa vihollisia vastaan."],[14,10,"Simon myös toimitti jyviä ja viljaa kaupunkeihin, niin että tarpeen aikanakin piti heillä kyllä oleman, ja hän oli kuuluisa mies kaikessa maailmassa.","Simon myös toimitti jyviä ja viljaa kaupunkeihin, niin että tarpeen aikanakin piti heillä kyllä oleman, ja hän oli kuuluisa mies kaikessa maailmassa."],[14,11,"Hän piti rauhan maakunnassa, niin että kaikki Israel iloitsi.","Hän piti rauhan maakunnassa, niin että kaikki Israel iloitsi."],[14,12,"Ja jokainen nautitsi viinamäkensä ja yrttitarhansa rauhassa, ja ei he ketään peljänneet, sillä ei yksikään tohtinut heitä vaivata.","Ja jokainen nautitsi viinamäkensä ja yrttitarhansa rauhassa, ja ei he ketään peljänneet, sillä ei yksikään tohtinut heitä vaivata."],[14,13,"Ja ei Syrian kuninkaat tohtineet siihen aikaan heille mitään pahaa tehdä.","Ja ei Syrian kuninkaat tohtineet siihen aikaan heille mitään pahaa tehdä."],[14,14,"Ja hän teki oikeuden maakunnassa, ja varjeli köyhiä kansansa seassa väkivaltaa vastaan, ja rankaisi kaikki väärät, ja hukutti jumalattomat.","Ja hän teki oikeuden maakunnassa, ja varjeli köyhiä kansansa seassa väkivaltaa vastaan, ja rankaisi kaikki väärät, ja hukutti jumalattomat."],[14,15,"Pyhän saatti hän jälleen kunniaan, ja antoi pyhää kalua siihen lisätä.","Pyhän saatti hän jälleen kunniaan, ja antoi pyhää kalua siihen lisätä."],[14,16,"Ja kuin se sanoma kuului Roomissa ja Spartassa, että Jonatan tapettu oli, tulivat he kaikki surullisiksi.","Ja kuin se sanoma kuului Roomissa ja Spartassa, että Jonatan tapettu oli, tulivat he kaikki surullisiksi."],[14,17,"Mutta kuin Roomalaiset kuulivat, että Simon hänen veljensä oli ylimmäinen pappi, ja oli maakunnan omistanut, ja viholliset ajanut pois,","Mutta kuin Roomalaiset kuulivat, että Simon hänen veljensä oli ylimmäinen pappi, ja oli maakunnan omistanut, ja viholliset ajanut pois,"],[14,18,"Niin he uudistivat sen liiton, jonka he ennen Juudaan ja hänen veljensä Jonatanin kanssa tehneet olivat, ja kirjoittivat vaskitauluihin ja lähettivät hänelle.","Niin he uudistivat sen liiton, jonka he ennen Juudaan ja hänen veljensä Jonatanin kanssa tehneet olivat, ja kirjoittivat vaskitauluihin ja lähettivät hänelle."],[14,19,"Se kirjoitus luettiin julkisesti kansan edessä Jerusalemissa.","Se kirjoitus luettiin julkisesti kansan edessä Jerusalemissa."],[14,20,"Ja Spartasta kirjoitettiin Simonin tykö näin: neuvonantajat ja Spartan asuvaiset toivottavat ylimmäiselle papille Simonille, ja vanhimmille, ja papeille, ja Juudan kansalle, omille veljillensä, terveyttä!","Ja Spartasta kirjoitettiin Simonin tykö näin: neuvonantajat ja Spartan asuvaiset toivottavat ylimmäiselle papille Simonille, ja vanhimmille, ja papeille, ja Juudan kansalle, omille veljillensä, terveyttä!"],[14,21,"Teidän asianajajat tulivat meidän tykömme ja sanoivat, että te teidän vihollisenne olette lyöneet suurella kunnialla, ja olette nyt hyvässä rauhassa, josta meillä on suuri ilo. Me olemme myös meidän kaupungin kirjoihin antaneet kirjoittaa, mitä he toimittaneet ovat, näin:","Teidän asianajajat tulivat meidän tykömme ja sanoivat, että te teidän vihollisenne olette lyöneet suurella kunnialla, ja olette nyt hyvässä rauhassa, josta meillä on suuri ilo. Me olemme myös meidän kaupungin kirjoihin antaneet kirjoittaa, mitä he toimittaneet ovat, näin:"],[14,22,"Juudalaisten asianajajat, Numeuius Antiokuksen poika ja Antipater Jasonin poika, tulivat meidän tykömme uudistamaan ystävyyttä Juudalaisten ja meidän välillämme.","Juudalaisten asianajajat, Numeuius Antiokuksen poika ja Antipater Jasonin poika, tulivat meidän tykömme uudistamaan ystävyyttä Juudalaisten ja meidän välillämme."],[14,23,"Ja me toimitimme yksimielisesti, että ne sanansaattajat kunniallisesti piti otettaman vastaan, ja heidän puheensa kaupungin kirjaan kirjoitettaman ijankaikkiseksi muistoksi. Tämän vastauksen he kirjoittivat Simonille, ylimmäiselle papille.","Ja me toimitimme yksimielisesti, että ne sanansaattajat kunniallisesti piti otettaman vastaan, ja heidän puheensa kaupungin kirjaan kirjoitettaman ijankaikkiseksi muistoksi. Tämän vastauksen he kirjoittivat Simonille, ylimmäiselle papille."],[14,24,"Senjälkeen lähetti Simon Numeniuksen jällensä Roomiin, viemään suurta kultaista kilpeä, joka painoi tuhannen leiviskää, ja uudistamaan liittoa heidän kanssansa.","Senjälkeen lähetti Simon Numeniuksen jällensä Roomiin, viemään suurta kultaista kilpeä, joka painoi tuhannen leiviskää, ja uudistamaan liittoa heidän kanssansa."],[14,25,"Kuin Roomalaiset kuulivat hänen asiansa, sanoivat he: meidän pitää ilman estettä tekemän Simonille ja hänen lapsillensa kunniaa.","Kuin Roomalaiset kuulivat hänen asiansa, sanoivat he: meidän pitää ilman estettä tekemän Simonille ja hänen lapsillensa kunniaa."],[14,26,"Sillä hän ja hänen veljensä ovat miehuulliset olleet, ja Israelin varjelleet, ja viholliset ajaneet pois, sentähden vahvistivat Roomalaiset sen yksimielisesti, että Juudalaiset piti vapaat oleman; ja he antoivat sen kirjoittaa vaskitauluihin, jotka piti patsaisiin lyötämän Zionin vuorelle.","Sillä hän ja hänen veljensä ovat miehuulliset olleet, ja Israelin varjelleet, ja viholliset ajaneet pois, sentähden vahvistivat Roomalaiset sen yksimielisesti, että Juudalaiset piti vapaat oleman; ja he antoivat sen kirjoittaa vaskitauluihin, jotka piti patsaisiin lyötämän Zionin vuorelle."],[14,27,"Tämä seuraavainen kirjoitus on tehty kahdeksantena päivänä toistakymmentä Elulin kuulla, toisena vuotena kahdeksattakymmentä toista sataa, ylimmäisen papin Simonin Saramelista kolmantena hallituksen vuotena,","Tämä seuraavainen kirjoitus on tehty kahdeksantena päivänä toistakymmentä Elulin kuulla, toisena vuotena kahdeksattakymmentä toista sataa, ylimmäisen papin Simonin Saramelista kolmantena hallituksen vuotena,"],[14,28,"Suuressa vanhimpain, pappein ja kaiken Juudan kansan kokouksessa:","Suuressa vanhimpain, pappein ja kaiken Juudan kansan kokouksessa:"],[14,29,"Jokaiselle olkoon tiettävä ja julkinen, että niissä suurissa sodissa, jotka meidän maakunnissa ovat olleet, Simon Matatiaan poika, Jaribin suvusta., ja hänen veljensä ovat henkensä antaneet vaaraan, ja olleet oman kansansa vihollisia vastaan, ettei pyhä ja Jumalan laki olisi tullut maahan lyödyksi ja hävitetyksi, ja ovat saaneet kansansa suureen kunniaan.","Jokaiselle olkoon tiettävä ja julkinen, että niissä suurissa sodissa, jotka meidän maakunnissa ovat olleet, Simon Matatiaan poika, Jaribin suvusta., ja hänen veljensä ovat henkensä antaneet vaaraan, ja olleet oman kansansa vihollisia vastaan, ettei pyhä ja Jumalan laki olisi tullut maahan lyödyksi ja hävitetyksi, ja ovat saaneet kansansa suureen kunniaan."],[14,30,"Sillä Jonatan kokosi kansan jälleen, ja otti hallitusviran ja tuli ylimmäiseksi papiksi.","Sillä Jonatan kokosi kansan jälleen, ja otti hallitusviran ja tuli ylimmäiseksi papiksi."],[14,31,"Mutta kuin hän kuoli, tulivat viholliset jälleen, ja tahtoivat hävittää maakunnan ja pyhän. 13: 23.","Mutta kuin hän kuoli, tulivat viholliset jälleen, ja tahtoivat hävittää maakunnan ja pyhän. 13: 23."],[14,32,"Niin Simon nousi ja soti meidän vihollisiamme vastaan, ja toimitti meidän sotaväelle aseita, ja maksoi heidän palkkansa omasta rahastansa ja hyvyydestänsä,","Niin Simon nousi ja soti meidän vihollisiamme vastaan, ja toimitti meidän sotaväelle aseita, ja maksoi heidän palkkansa omasta rahastansa ja hyvyydestänsä,"],[14,33,"Ja vahvisti kaupungit Juudeassa ja Betsuran rajakaupungin, jossa viholliset ennen sota-aseensa ja sodan valmistukset pitivät, ja pani Juudalaisia sitä varjelemaan.","Ja vahvisti kaupungit Juudeassa ja Betsuran rajakaupungin, jossa viholliset ennen sota-aseensa ja sodan valmistukset pitivät, ja pani Juudalaisia sitä varjelemaan."],[14,34,"Hän vahvisti myös Jopen, joka on merikaupunki, ja Gatsan, joka on Asdodin rajoilla; sillä Gatsa oli ennen ollut vihollisten linna, mutta Simon omisti sen, ja pani siihen Juudalaisia, ja asetti siihen hyvän hallituksen.","Hän vahvisti myös Jopen, joka on merikaupunki, ja Gatsan, joka on Asdodin rajoilla; sillä Gatsa oli ennen ollut vihollisten linna, mutta Simon omisti sen, ja pani siihen Juudalaisia, ja asetti siihen hyvän hallituksen."],[14,35,"Kuin kansa Simonin uskollisuuden ymmärsi, ja tiesi ne hyvät työt, jotka hän heille tehnyt oli, valitsivat he hänen päämieheksensä ja ylimmäiseksi papiksensa hänen hyvyytensä ja uskollisuutensa tähden, jonka hän kaikelle kansalle osoitti, ja ahkeroitsi alamaisillensa kaikkea hyvää tehdä.","Kuin kansa Simonin uskollisuuden ymmärsi, ja tiesi ne hyvät työt, jotka hän heille tehnyt oli, valitsivat he hänen päämieheksensä ja ylimmäiseksi papiksensa hänen hyvyytensä ja uskollisuutensa tähden, jonka hän kaikelle kansalle osoitti, ja ahkeroitsi alamaisillensa kaikkea hyvää tehdä."],[14,36,"Sillä hänen aikanansa antoi Jumala menestyksen hänen kättensä kautta, niin että pakanat meidän maakunnasta ja Jerusalemista ja linnasta tulivat ajetuksi pois, jossa he olivat, josta he myös läksivät ja hävittivät pyhän, ja puhtaan jumalanpalveluksen sokaisivat.","Sillä hänen aikanansa antoi Jumala menestyksen hänen kättensä kautta, niin että pakanat meidän maakunnasta ja Jerusalemista ja linnasta tulivat ajetuksi pois, jossa he olivat, josta he myös läksivät ja hävittivät pyhän, ja puhtaan jumalanpalveluksen sokaisivat."],[14,37,"Mutta Simon omisti linnan, ja pani siihen Juudalaisia varjelemaan Jerusalemin kaupunkia ja maakuntaa, ja korotti Jerusalemin muurit.","Mutta Simon omisti linnan, ja pani siihen Juudalaisia varjelemaan Jerusalemin kaupunkia ja maakuntaa, ja korotti Jerusalemin muurit."],[14,38,"Ja kuningas Demetrius vahvisti hänen ylimmäisen papin virkaan","Ja kuningas Demetrius vahvisti hänen ylimmäisen papin virkaan"],[14,39,"Ja piti ystävänänsä, ja teki hänelle suuren kunnian.","Ja piti ystävänänsä, ja teki hänelle suuren kunnian."],[14,40,"Sillä hän ymmärsi, että Roomalaiset Juudalaisten asiamiehiä kunniallisesti ottivat vastaan, ja olivat tehneet liiton heidän kanssansa, ja ottaneet heitä varjelukseensa;","Sillä hän ymmärsi, että Roomalaiset Juudalaisten asiamiehiä kunniallisesti ottivat vastaan, ja olivat tehneet liiton heidän kanssansa, ja ottaneet heitä varjelukseensa;"],[14,41,"Ja että Juudan kansalla ja heidän papeillansa yksimielisesti se neuvo oli, että Simon piti heidän päämiehensä ja ylimmäinen pappinsa alinomaisesti oleman, siihenasti että Jumala heille sen oikian Prophetan olis herättänyt;","Ja että Juudan kansalla ja heidän papeillansa yksimielisesti se neuvo oli, että Simon piti heidän päämiehensä ja ylimmäinen pappinsa alinomaisesti oleman, siihenasti että Jumala heille sen oikian Prophetan olis herättänyt;"],[14,42,"Ja että hänen piti päämiehen oleman, ja pyhän varjeleman, ja asettaman käskyläiset maakuntaan, ja kaikki sodan neuvot ja linnat pitämän hallussansa ja voimassansa;","Ja että hänen piti päämiehen oleman, ja pyhän varjeleman, ja asettaman käskyläiset maakuntaan, ja kaikki sodan neuvot ja linnat pitämän hallussansa ja voimassansa;"],[14,43,"Ja että jokaisen piti häntä kuuleman, ja kaikki käskyt hänen nimellänsä käymän ulos; ja että hänen piti purpurassa ja kullassa käymän.","Ja että jokaisen piti häntä kuuleman, ja kaikki käskyt hänen nimellänsä käymän ulos; ja että hänen piti purpurassa ja kullassa käymän."],[14,44,"Kaikki nämät piti uskollisesti ja vahvasti kaikelta kansalta ja kaikilta papeilta pidettämän, ja ei yhdenkään pitänyt asettaman itsiänsä tätä vastaan, eikä yhdelläkään oleman voimaa maakunnassa kansaa yhteen kutsua, eikä purpuraa taikka kultaista vyötä kantaa, vaan hänellä ainoasti.","Kaikki nämät piti uskollisesti ja vahvasti kaikelta kansalta ja kaikilta papeilta pidettämän, ja ei yhdenkään pitänyt asettaman itsiänsä tätä vastaan, eikä yhdelläkään oleman voimaa maakunnassa kansaa yhteen kutsua, eikä purpuraa taikka kultaista vyötä kantaa, vaan hänellä ainoasti."],[14,45,"Mutta joka tekee tätä vastaan ja tämän säädyn rikkoo, sen pitää vikapään oleman.","Mutta joka tekee tätä vastaan ja tämän säädyn rikkoo, sen pitää vikapään oleman."],[14,46,"Näin lupasi kaikki kansa Simonille olla kuuliainen.","Näin lupasi kaikki kansa Simonille olla kuuliainen."],[14,47,"Siihen myös Simon tyytyi ja tuli ylimmäiseksi papiksi, ja Juudan kansan päämieheksi.","Siihen myös Simon tyytyi ja tuli ylimmäiseksi papiksi, ja Juudan kansan päämieheksi."],[14,48,"Ja yhteinen kansa käski tämän päätöksen vaskisiin tauluihin kirjoittaa, ja pantaa templin läpikäytävään julkiseen paikkaan,","Ja yhteinen kansa käski tämän päätöksen vaskisiin tauluihin kirjoittaa, ja pantaa templin läpikäytävään julkiseen paikkaan,"],[14,49,"Ja yhden senkaltaisen kirjoituksen siitä panna veroarkkuun, josta Simon ja hänen jälkeentulevaisensa piti sen aina löytämän.","Ja yhden senkaltaisen kirjoituksen siitä panna veroarkkuun, josta Simon ja hänen jälkeentulevaisensa piti sen aina löytämän."],[15,1,"Kuinka erinkaltaisesti Antiokus ja Roomalaiset Juudalaisia kohtaavat. Ja kuningas Antiokus Demetriuksen poika kirjoitti luodoista Simonin ja Juudan kansan tykö näin:","Kuinka erinkaltaisesti Antiokus ja Roomalaiset Juudalaisia kohtaavat. Ja kuningas Antiokus Demetriuksen poika kirjoitti luodoista Simonin ja Juudan kansan tykö näin:"],[15,2,"Kuningas Antiokus toivottaa Simonille, ylimmäiselle papille, ja Juudan kansalle terveyttä!","Kuningas Antiokus toivottaa Simonille, ylimmäiselle papille, ja Juudan kansalle terveyttä!"],[15,3,"Että muutamat kapinan nostajat ovat ottaneet minulta pois minun perintövaltakuntani,","Että muutamat kapinan nostajat ovat ottaneet minulta pois minun perintövaltakuntani,"],[15,4,"Niin minä tahdon sen jälleen alleni ottaa, ja antaa sen olikian perillisten alle tulla: ja sentähden olen minä muukalaista sotaväkeä ottanut ja haaksia teettänyt, ja tahdon valtakuntaani käydä, että minä kapinan nostajat rankaisisin, jotka minun valtakunnassani paljon vahinkoa tehneet ovat ja monta kaupunkia hävittäneet.","Niin minä tahdon sen jälleen alleni ottaa, ja antaa sen olikian perillisten alle tulla: ja sentähden olen minä muukalaista sotaväkeä ottanut ja haaksia teettänyt, ja tahdon valtakuntaani käydä, että minä kapinan nostajat rankaisisin, jotka minun valtakunnassani paljon vahinkoa tehneet ovat ja monta kaupunkia hävittäneet."],[15,5,"Sentähden minä annan sinulle kaikki ne, mitä kuninkaat ennen sinulle antaneet ovat,","Sentähden minä annan sinulle kaikki ne, mitä kuninkaat ennen sinulle antaneet ovat,"],[15,6,"Ja annan sinulle voiman rahaa lyödä omassa maakunnassas.","Ja annan sinulle voiman rahaa lyödä omassa maakunnassas."],[15,7,"Ja Jerusalem ja pyhä saa vapaa olla. Sinun omas pitää myös oleman kaikki ne linnat, jotkas rakentanut olet, ja kaikki, mitäs tähän asti pitänyt olet, ja kaikki ne sota-aseet, jotka sinä tehnyt olet.","Ja Jerusalem ja pyhä saa vapaa olla. Sinun omas pitää myös oleman kaikki ne linnat, jotkas rakentanut olet, ja kaikki, mitäs tähän asti pitänyt olet, ja kaikki ne sota-aseet, jotka sinä tehnyt olet."],[15,8,"Ja annan sinulle vapauden kaikista niistä, mitkä kuninkaalle tehtämän pitäis, ja muutoin kuninkaan omat ovat, tästä ajasta ruveten, niin ijäksi päiväksi.","Ja annan sinulle vapauden kaikista niistä, mitkä kuninkaalle tehtämän pitäis, ja muutoin kuninkaan omat ovat, tästä ajasta ruveten, niin ijäksi päiväksi."],[15,9,"Ja kuin me valtakuntamme jälleen saamme, niin me tahdomme sinulle, ja sinun kansalles ja templille vielä suuremman kunnian tehdä, niin että teidän pitää kaikessa valtakunnassa kuuluisat oleman.","Ja kuin me valtakuntamme jälleen saamme, niin me tahdomme sinulle, ja sinun kansalles ja templille vielä suuremman kunnian tehdä, niin että teidän pitää kaikessa valtakunnassa kuuluisat oleman."],[15,10,"Neljäntenä vuotena kahdeksattakymmentä toista sataa tuli Antiokus jälleen perintövaltakuntaansa, ja kaikki sotaväki hylkäsi Tryphonin, ja meni hänen tykönsä, ja sangen harvat jäivät Tryphonin puolelle.","Neljäntenä vuotena kahdeksattakymmentä toista sataa tuli Antiokus jälleen perintövaltakuntaansa, ja kaikki sotaväki hylkäsi Tryphonin, ja meni hänen tykönsä, ja sangen harvat jäivät Tryphonin puolelle."],[15,11,"Kuin kuningas Antiokus meni hänen jälkeensä, pakeni hän Doraan, joka on meren tykönä.","Kuin kuningas Antiokus meni hänen jälkeensä, pakeni hän Doraan, joka on meren tykönä."],[15,12,"Sillä hän näki olevansa vaarassa, että sotaväki hänen jätti.","Sillä hän näki olevansa vaarassa, että sotaväki hänen jätti."],[15,13,"Mutta Antiokus meni hänen jälkeensä Doraan sadalla ja kahdellakymmenellä tuhannella jalkamiehellä ja kahdeksallatuhannella ratsasmiehellä;","Mutta Antiokus meni hänen jälkeensä Doraan sadalla ja kahdellakymmenellä tuhannella jalkamiehellä ja kahdeksallatuhannella ratsasmiehellä;"],[15,14,"Ja piiritti kaupungin sekä maalta että vedeltä, niin ettei yksikään saanut siitä käydä ulos taikka sisälle.","Ja piiritti kaupungin sekä maalta että vedeltä, niin ettei yksikään saanut siitä käydä ulos taikka sisälle."],[15,15,"Siihen aikaan tuli Numenius Roomista ja muut, jotka hänen kanssansa lähetetyt olivat, ja toivat kirjoja kuningasten tykö ja maakuntiin, joissa oli kirjoitettu näin:","Siihen aikaan tuli Numenius Roomista ja muut, jotka hänen kanssansa lähetetyt olivat, ja toivat kirjoja kuningasten tykö ja maakuntiin, joissa oli kirjoitettu näin:"],[15,16,"Lukius, Roomin kaupungin haltia, toivottaa kuningas Ptolomeukselle terveyttä!","Lukius, Roomin kaupungin haltia, toivottaa kuningas Ptolomeukselle terveyttä!"],[15,17,"Simon, ylimmäinen pappi, ja Juudan kansa ovat lähettäneet asiansa ajajat meidän tykömme, uudistamaan ystävyyttä ja liittoa meidän välillämme.","Simon, ylimmäinen pappi, ja Juudan kansa ovat lähettäneet asiansa ajajat meidän tykömme, uudistamaan ystävyyttä ja liittoa meidän välillämme."],[15,18,"Ja ovat myös lähettäneet meille kultaisen kilven, joka painaa tuhannen leiviskää.","Ja ovat myös lähettäneet meille kultaisen kilven, joka painaa tuhannen leiviskää."],[15,19,"Sentähden me kirjoitamme kuningasten ja muiden herrain tykö, ettei heidän Juudalaisia vastaan mitään tekemän pidä, eikä heidän kaupunkeihinsa ja maakuntiinsa menemän, eikä myös pidä heidän ketään auttaman sotimaan heitä vastaan.","Sentähden me kirjoitamme kuningasten ja muiden herrain tykö, ettei heidän Juudalaisia vastaan mitään tekemän pidä, eikä heidän kaupunkeihinsa ja maakuntiinsa menemän, eikä myös pidä heidän ketään auttaman sotimaan heitä vastaan."],[15,20,"Sillä me olemme ottaneet heiltä sen kilven tykömme.","Sillä me olemme ottaneet heiltä sen kilven tykömme."],[15,21,"Ja jos muutamia kovakorvaisia heidän maakunnastansa teidän tykönne on paenneet, ne teidän pitää lähettämän ylimmäisen papin Simonin tykö, että hän heitä lakinsa jälkeen sais rangaista.","Ja jos muutamia kovakorvaisia heidän maakunnastansa teidän tykönne on paenneet, ne teidän pitää lähettämän ylimmäisen papin Simonin tykö, että hän heitä lakinsa jälkeen sais rangaista."],[15,22,"Näin olemme me myös kirjoittaneet kuningas Demetriuksen, Attaluksen, Aretan Ja Alsasen tykö,","Näin olemme me myös kirjoittaneet kuningas Demetriuksen, Attaluksen, Aretan Ja Alsasen tykö,"],[15,23,"Ja kaikkiin maakuntiin, Ja Sampsasiin ja Spartalaisten tykö, ja niiden tykö, jotka Delossa, Myndossa, Sikyonissa, Kariassa, Samossa, Pamphyliassa, Lysiassa, Halikarnassossa, Rodossa, Faselissa, Koossa, Sidonissa, Gortynassa, Knidossa, Kyprissä Ja Kyrenessä asuvat.","Ja kaikkiin maakuntiin, Ja Sampsasiin ja Spartalaisten tykö, ja niiden tykö, jotka Delossa, Myndossa, Sikyonissa, Kariassa, Samossa, Pamphyliassa, Lysiassa, Halikarnassossa, Rodossa, Faselissa, Koossa, Sidonissa, Gortynassa, Knidossa, Kyprissä Ja Kyrenessä asuvat."],[15,24,"Ja tämänkaltaisen kirjan me olemme lähettäneet ylimmäiselle papille Simonille ja Juudan kansalle.","Ja tämänkaltaisen kirjan me olemme lähettäneet ylimmäiselle papille Simonille ja Juudan kansalle."],[15,25,"Silloin vei Antiokus vielä toisen sotaväen Doran alle, kovemmin sitä piirittämään, ja pani sodan rakennukset sen eteen, ja ahdisti kaupungin joka taholta ja sulki Tryphonin sinne, ettei hän saanut käydä ulos eikä sisälle.","Silloin vei Antiokus vielä toisen sotaväen Doran alle, kovemmin sitä piirittämään, ja pani sodan rakennukset sen eteen, ja ahdisti kaupungin joka taholta ja sulki Tryphonin sinne, ettei hän saanut käydä ulos eikä sisälle."],[15,26,"Ja Simon lähetti Antiokuksen avuksi kaksituhatta hyvää ja valittua miestä, ja paljon kultaa, ja hopiaa ja aseita.","Ja Simon lähetti Antiokuksen avuksi kaksituhatta hyvää ja valittua miestä, ja paljon kultaa, ja hopiaa ja aseita."],[15,27,"Mutta Antiokus ei ottanut niitä vastaan, eikä sitä pitänyt, mitä hän ennen luvannut oli vaan peräti kylmeni Simonia vastaan,","Mutta Antiokus ei ottanut niitä vastaan, eikä sitä pitänyt, mitä hän ennen luvannut oli vaan peräti kylmeni Simonia vastaan,"],[15,28,"Ja lähetti yhden ystävistänsä hänen tykönsä, nimeltä Atenobiuksen, häntä puhuttelemaan ja sanomaan: te olette Jopen, ja Gatsan ja Jerusalemin linnan omistaneet, jotka kaikki minun valtakuntaani tulevat;","Ja lähetti yhden ystävistänsä hänen tykönsä, nimeltä Atenobiuksen, häntä puhuttelemaan ja sanomaan: te olette Jopen, ja Gatsan ja Jerusalemin linnan omistaneet, jotka kaikki minun valtakuntaani tulevat;"],[15,29,"Ja olette maakunnan niiden ympäristöltä hävittäneet, ja suuren vahingon tehneet minun valtakunnassani, ja olette omistaneet minun perintömaani.","Ja olette maakunnan niiden ympäristöltä hävittäneet, ja suuren vahingon tehneet minun valtakunnassani, ja olette omistaneet minun perintömaani."],[15,30,"Sentähden anon minä teiltä nämät kaupungit jällensä, jotka te olette ottaneet minulta pois, ja kaiken veron niistä kaupungeista, jotka teillä on paitsi Juudan maata.","Sentähden anon minä teiltä nämät kaupungit jällensä, jotka te olette ottaneet minulta pois, ja kaiken veron niistä kaupungeista, jotka teillä on paitsi Juudan maata."],[15,31,"Mutta jos ette sitä tahdo tehdä, niin antakaat minulle niiden kaupunkein edestä viisisataa leiviskää hopiaa, ja sen vahingon ja veron edestä toiset viisisataa leiviskää, mutta jos ette sitä tottele, niin me tahdomme sotia teitä vastaan.","Mutta jos ette sitä tahdo tehdä, niin antakaat minulle niiden kaupunkein edestä viisisataa leiviskää hopiaa, ja sen vahingon ja veron edestä toiset viisisataa leiviskää, mutta jos ette sitä tottele, niin me tahdomme sotia teitä vastaan."],[15,32,"Kuin Atenobius, kuninkaan ystävä, tuli Jerusalemiin ja näki Simonin suuren kunnian ja sen koreuden, joka hänellä oli kullasta ja hopiasta, ja kuinka hän muutoinkin oli jalosti valmistettu, ihmetteli hän sitä sangen suuresti, ja jutteli hänen edessänsä, mitä kuningas oli käskenyt.","Kuin Atenobius, kuninkaan ystävä, tuli Jerusalemiin ja näki Simonin suuren kunnian ja sen koreuden, joka hänellä oli kullasta ja hopiasta, ja kuinka hän muutoinkin oli jalosti valmistettu, ihmetteli hän sitä sangen suuresti, ja jutteli hänen edessänsä, mitä kuningas oli käskenyt."],[15,33,"Siihen antoi Simon hänelle tämän vastauksen: se maakunta, jonka me jälleen omistaneet olemme, on meidän isäimme perintö, ja ei se kenenkään muiden oma ole; mutta meidän vihollisemme ovat sen kauvan aikaa väkivallalla ja vääryydellä omanansa pitäneet.","Siihen antoi Simon hänelle tämän vastauksen: se maakunta, jonka me jälleen omistaneet olemme, on meidän isäimme perintö, ja ei se kenenkään muiden oma ole; mutta meidän vihollisemme ovat sen kauvan aikaa väkivallalla ja vääryydellä omanansa pitäneet."],[15,34,"Sentähden olemme me nyt meidän omamme jälleen ottaneet, ja emme kenenkään toisen omaa.","Sentähden olemme me nyt meidän omamme jälleen ottaneet, ja emme kenenkään toisen omaa."],[15,35,"Mutta että sinä sitä valitat, että me Jopen ja Gatsan olemme ottaneet, siihen oli se syy, että niistä tehtiin meidän maakunnallemme ja kansallemme suuri vahinko; mutta kuitenkin me tahdomme niiden edestä antaa sata leiviskää.","Mutta että sinä sitä valitat, että me Jopen ja Gatsan olemme ottaneet, siihen oli se syy, että niistä tehtiin meidän maakunnallemme ja kansallemme suuri vahinko; mutta kuitenkin me tahdomme niiden edestä antaa sata leiviskää."],[15,36,"Siihen ei Atenobius mitään vastannut, vaan vihastui ja meni matkaansa kuninkaan tykö, ja ilmoitti hänelle Simonin vastauksen, ja hänen kunniansa ja jaloutensa ja kaikki, mitä hän nähnyt oli. Silloin kuningas vihastui sangen hirmuisesti.","Siihen ei Atenobius mitään vastannut, vaan vihastui ja meni matkaansa kuninkaan tykö, ja ilmoitti hänelle Simonin vastauksen, ja hänen kunniansa ja jaloutensa ja kaikki, mitä hän nähnyt oli. Silloin kuningas vihastui sangen hirmuisesti."],[15,37,"Mutta Tryphon pääsi pois sieltä, ja haahdella pakeni Ortosiaan.","Mutta Tryphon pääsi pois sieltä, ja haahdella pakeni Ortosiaan."],[15,38,"Niin kuningas teki Kendebeuksen merimaakunnan päämieheksi, ja antoi hänelle sotaväkeä sekä ratsasmiehiä että jalkamiehiä,","Niin kuningas teki Kendebeuksen merimaakunnan päämieheksi, ja antoi hänelle sotaväkeä sekä ratsasmiehiä että jalkamiehiä,"],[15,39,"Ja käski hänen sioittaa itsensä Juudan maan rajoille, ja vahvistaa Kedronin kaupungin, ja rakentaa linnan vuorelle, josta heidän piti Juudeaan menemän: mutta kuningas ajoi Tryphonia takaa, käsittääksensä häntä.","Ja käski hänen sioittaa itsensä Juudan maan rajoille, ja vahvistaa Kedronin kaupungin, ja rakentaa linnan vuorelle, josta heidän piti Juudeaan menemän: mutta kuningas ajoi Tryphonia takaa, käsittääksensä häntä."],[15,40,"Kuin siis Kendebeus tuli Jamniaan, löi hän Juudalaisia ja ryösti heidän maakuntansa, ja antoi tappaa paljon kansaa, ja otti monta kiinni ja vei pois,","Kuin siis Kendebeus tuli Jamniaan, löi hän Juudalaisia ja ryösti heidän maakuntansa, ja antoi tappaa paljon kansaa, ja otti monta kiinni ja vei pois,"],[15,41,"Ja rakensi Kedronin kaupungin, ja pani siihen sotaväkeä, että he sieltä rajoilta olisivat karanneet ulos, ja sulkeneet Juudalalsten sotaväen tien, niinkuin kuningas heidän käskenyt oli.","Ja rakensi Kedronin kaupungin, ja pani siihen sotaväkeä, että he sieltä rajoilta olisivat karanneet ulos, ja sulkeneet Juudalalsten sotaväen tien, niinkuin kuningas heidän käskenyt oli."],[16,1,"Johanneksen Simonin pojan urhoollisuudesta, niin myös Ptolomeuksen murhatyöstä appiansa Simonia vastaan. Sentähden meni Johannes Gatsasta isänsä Simonin tykö, ja ilmoitti hänelle, että Kendebeus oli maalle tullut, ja paljon vahinkoa tehnyt.","Johanneksen Simonin pojan urhoollisuudesta, niin myös Ptolomeuksen murhatyöstä appiansa Simonia vastaan. Sentähden meni Johannes Gatsasta isänsä Simonin tykö, ja ilmoitti hänelle, että Kendebeus oli maalle tullut, ja paljon vahinkoa tehnyt."],[16,2,"Silloin Simon kutsui kaksi vanhinta poikaansa tykönsä, Juudaan ja Johanneksen, ja sanoi heille: minä ja minun veljeni ja koko minun isäni huone olemme hamasta nuoruudesta niin tähän aikaan asti sotineet Israelin vihollisia vastaan, ja Jumala on meille onnen antanut, ja Israel on monasti meidän kättemme kautta holhottu.","Silloin Simon kutsui kaksi vanhinta poikaansa tykönsä, Juudaan ja Johanneksen, ja sanoi heille: minä ja minun veljeni ja koko minun isäni huone olemme hamasta nuoruudesta niin tähän aikaan asti sotineet Israelin vihollisia vastaan, ja Jumala on meille onnen antanut, ja Israel on monasti meidän kättemme kautta holhottu."],[16,3,"Mutta että minä vanha ja heikko olen, niin teidän pitää nyt astuman minun ja minun veljeni siaan, ja menemän sotimaan kansanne edestä. Jumala taivaasta auttakoon teitä ja olkoon teidän kanssanne!","Mutta että minä vanha ja heikko olen, niin teidän pitää nyt astuman minun ja minun veljeni siaan, ja menemän sotimaan kansanne edestä. Jumala taivaasta auttakoon teitä ja olkoon teidän kanssanne!"],[16,4,"Niin hän antoi valita maakunnasta kaksikymmentä tuhatta jalkamiestä ja muutamia hevosmiehiä; tällä joukolla meni Johannes ja Juudas Kendebeusta vastaan, ja olivat yötä Modissa.","Niin hän antoi valita maakunnasta kaksikymmentä tuhatta jalkamiestä ja muutamia hevosmiehiä; tällä joukolla meni Johannes ja Juudas Kendebeusta vastaan, ja olivat yötä Modissa."],[16,5,"Mutta huomeneltain, kuin he Modista tulivat lakialle kedolle, tuli suuri sotaväki heitä vastaan, sekä ratsasmiehiä että jalkaväkeä. Ja siellä oli virta molempain sotajoukkojen välillä.","Mutta huomeneltain, kuin he Modista tulivat lakialle kedolle, tuli suuri sotaväki heitä vastaan, sekä ratsasmiehiä että jalkaväkeä. Ja siellä oli virta molempain sotajoukkojen välillä."],[16,6,"Niin Johannes meni virran tykö, ja käänsi itsensä vihollisia vastaan, ja kuin hän näki, ettei sotaväki tahtonut virtaan mennä, niin hän rohkaisi itsensä, ja meni ensisti ylitse, ja kuin muu väki sen näki, menivät he myös ylitse hänen perässänsä.","Niin Johannes meni virran tykö, ja käänsi itsensä vihollisia vastaan, ja kuin hän näki, ettei sotaväki tahtonut virtaan mennä, niin hän rohkaisi itsensä, ja meni ensisti ylitse, ja kuin muu väki sen näki, menivät he myös ylitse hänen perässänsä."],[16,7,"Niin Johannes asetti väkensä rinnan vihollisia vastaan, ja pani hevosmiehet jalkaväen tykö, mutta vihollisilla oli paljoa enempi sotaväkeä.","Niin Johannes asetti väkensä rinnan vihollisia vastaan, ja pani hevosmiehet jalkaväen tykö, mutta vihollisilla oli paljoa enempi sotaväkeä."],[16,8,"Kuin siis Johannes antoi pappein vaskitorviin puhaltaa, ja löi vihollista, niin Kendebeus pakeni sotajoukkoinensa, ja siinä tuli monta haavoitetuksi ja lyödyksi; ja ne muut pakenivat vähään, vahvaan kaupunkiin.","Kuin siis Johannes antoi pappein vaskitorviin puhaltaa, ja löi vihollista, niin Kendebeus pakeni sotajoukkoinensa, ja siinä tuli monta haavoitetuksi ja lyödyksi; ja ne muut pakenivat vähään, vahvaan kaupunkiin."],[16,9,"Siinä sodassa tuli myös Juudas, Johanneksen veli, haavoitetuksi, mutta Johannes ajoi takaa vihollisia Kedronin linnaan asti.","Siinä sodassa tuli myös Juudas, Johanneksen veli, haavoitetuksi, mutta Johannes ajoi takaa vihollisia Kedronin linnaan asti."],[16,10,"Ja viholliset pakenivat Atsodin maan paikoille linnoihin. Silloin Johannes poltti ne linnat, niin että vihollisista liki kaksituhatta miestä tuli surmatuiksi. Senjälkeen meni Johannes rauhassa kotiansa Juudeaan.","Ja viholliset pakenivat Atsodin maan paikoille linnoihin. Silloin Johannes poltti ne linnat, niin että vihollisista liki kaksituhatta miestä tuli surmatuiksi. Senjälkeen meni Johannes rauhassa kotiansa Juudeaan."],[16,11,"Mutta siellä oli yksi asetettu Jerihon maan päämieheksi, nimeltä Ptolomeus, Abodin poika, joka oli sangen rikas.","Mutta siellä oli yksi asetettu Jerihon maan päämieheksi, nimeltä Ptolomeus, Abodin poika, joka oli sangen rikas."],[16,12,"Ja ylimmäinen pappi Simon oli hänelle antanut tyttärensä avioksi,","Ja ylimmäinen pappi Simon oli hänelle antanut tyttärensä avioksi,"],[16,13,"Jonka tähden hän myös oli ylpiä sydämestä, ja pyysi maan ruhtinaaksi, ja etsi tilaa Simonia ja hänen poikiansa petoksella päiviltä ottaa pois.","Jonka tähden hän myös oli ylpiä sydämestä, ja pyysi maan ruhtinaaksi, ja etsi tilaa Simonia ja hänen poikiansa petoksella päiviltä ottaa pois."],[16,14,"Kuin Simon vaelsi ympäri Juudan maata, kaikkia paikkoja katselemassa, ja hallitusta hyvin toimittamassa, ja tuli Jerihoon kahden poikansa Matatiaan ja Juudaan kanssa, seitsemäntenä vuotena kahdeksattakymmentä toista sataa, ensimäisenä kuuna toistakymmentä, joka kutsutaan Sabat:","Kuin Simon vaelsi ympäri Juudan maata, kaikkia paikkoja katselemassa, ja hallitusta hyvin toimittamassa, ja tuli Jerihoon kahden poikansa Matatiaan ja Juudaan kanssa, seitsemäntenä vuotena kahdeksattakymmentä toista sataa, ensimäisenä kuuna toistakymmentä, joka kutsutaan Sabat:"],[16,15,"Silloin otti Abodin poika heidät vastaan linnassa, joka kutsutaan Dok, ja valmisti heille suuren pidon, mutta se oli petosta täynnä, sillä hänellä oli siinä sotaväki kätkettynä.","Silloin otti Abodin poika heidät vastaan linnassa, joka kutsutaan Dok, ja valmisti heille suuren pidon, mutta se oli petosta täynnä, sillä hänellä oli siinä sotaväki kätkettynä."],[16,16,"Ja kuin Simon ja hänen poikansa tulivat iloisiksi ja juopuneiksi, nousi Ptolomeus palvelioinensa, ja otti aseensa ja karkasi Simonin päälle, siinä kussa hän istui, ja löi hänen ja kaksi hänen poikaansa, ja heidän palveliansa kuoliaaksi.","Ja kuin Simon ja hänen poikansa tulivat iloisiksi ja juopuneiksi, nousi Ptolomeus palvelioinensa, ja otti aseensa ja karkasi Simonin päälle, siinä kussa hän istui, ja löi hänen ja kaksi hänen poikaansa, ja heidän palveliansa kuoliaaksi."],[16,17,"Tämän häpiällisen petoksen teki Ptolomeos Israelissa, ja osoitti pahuutensa hyväin töiden edestä.","Tämän häpiällisen petoksen teki Ptolomeos Israelissa, ja osoitti pahuutensa hyväin töiden edestä."],[16,18,"Senjälkeen kirjoitti hän kuningas Antiokuksen tykö, ja rukoili häneltä sotaväkeä avuksensa, omistaaksensa maakuntaa ja kaupungeita ja mitä niissä oli.","Senjälkeen kirjoitti hän kuningas Antiokuksen tykö, ja rukoili häneltä sotaväkeä avuksensa, omistaaksensa maakuntaa ja kaupungeita ja mitä niissä oli."],[16,19,"Hän lähetti myös joukon Gatsaan, surmaamaan Johannesta, ja kirjoitti päämiesten tykö, ja kutsui heitä tykönsä, ja lupasi heille antaa suuren palkan ja lahjat,","Hän lähetti myös joukon Gatsaan, surmaamaan Johannesta, ja kirjoitti päämiesten tykö, ja kutsui heitä tykönsä, ja lupasi heille antaa suuren palkan ja lahjat,"],[16,20,"Ja lähetti sotaväkensä Jerusalemia ja templiä omistamaan.","Ja lähetti sotaväkensä Jerusalemia ja templiä omistamaan."],[16,21,"Mutta yksi sanansaattaja joutui edellä Gatsaan, joka ilmoitti Johannekselle, että hänen isänsä ja veljensä tapetut olivat, ja että myös häntä oli aiottu tappaa.","Mutta yksi sanansaattaja joutui edellä Gatsaan, joka ilmoitti Johannekselle, että hänen isänsä ja veljensä tapetut olivat, ja että myös häntä oli aiottu tappaa."],[16,22,"Kuin Johannes nämät kuuli, peljästyi hän sangen kovin, Ja antoi ottaa kiinni ne, jotka lähetetyt olivat häntä tappamaan, ja kuin hän ymmärsi, että tämä on heidän ajatuksensa, niin hän antoi heidät tappaa.","Kuin Johannes nämät kuuli, peljästyi hän sangen kovin, Ja antoi ottaa kiinni ne, jotka lähetetyt olivat häntä tappamaan, ja kuin hän ymmärsi, että tämä on heidän ajatuksensa, niin hän antoi heidät tappaa."],[16,23,"Mutta mitä Johannes sen jälkeen muuta teki, Ja millaisia sotia hän piti vihollisia vastaan, ja kuinka hän hallitsi ja muurit rakensi,","Mutta mitä Johannes sen jälkeen muuta teki, Ja millaisia sotia hän piti vihollisia vastaan, ja kuinka hän hallitsi ja muurit rakensi,"],[16,24,"Se on kirjoitettu erinomaiseen kirjaan, hänen aikansa hallituksesta, niinkauvan kuin hän isänsä jälkeen ylimmäinen pappi oli.","Se on kirjoitettu erinomaiseen kirjaan, hänen aikansa hallituksesta, niinkauvan kuin hän isänsä jälkeen ylimmäinen pappi oli."]]}};